#!/bin/bash
# DMITBox local safety refactor. Generated by build/build.py; edit src/ instead.
set -u -o pipefail
IFS=$' \t\n'
umask 077
PATH=/usr/sbin:/usr/bin:/sbin:/bin
export PATH
unset BASH_ENV ENV CDPATH GLOBIGNORE
LC_ALL=C
export LC_ALL
readonly DMB_VERSION='4.0.0-dev'
DMB_STATE_DIR=/var/lib/dmitbox-local
DMB_CONFIG_DIR=/etc/dmitbox-local
DMB_RUNTIME_DIR=/run/dmitbox-local
DMB_LOCK_DIR=/run/dmitbox-local/locks
DMB_ETC_ROOT=/etc
DMB_RUN_ROOT=/run
DMB_ARTIFACT=$(readlink -f -- "${BASH_SOURCE[0]}") || exit 78
readonly DMB_STATE_DIR DMB_CONFIG_DIR DMB_RUNTIME_DIR DMB_LOCK_DIR DMB_ETC_ROOT DMB_RUN_ROOT DMB_ARTIFACT
declare -a DMB_LOCK_FDS=()

# BEGIN MODULE core.sh
# Shared runtime. Production paths are assigned by the generated entry point;
# inherited environment variables never select privileged state or executables.
dmb_error() { printf 'dmitbox: %s\n' "$*" >&2; }
dmb_require_root() { (( EUID == 0 )) || { dmb_error 'Root is required for this operation'; return 77; }; }
dmb_need() { local c; for c in "$@"; do command -v "$c" >/dev/null 2>&1 || { dmb_error "Missing dependency: $c (install explicitly)"; return 69; }; done; }
dmb_state_root() { printf '%s\n' "$DMB_STATE_DIR"; }
dmb_config_root() { printf '%s\n' "$DMB_CONFIG_DIR"; }
dmb_lock_root() { printf '%s\n' "$DMB_LOCK_DIR"; }
dmb_artifact_path() { [[ ${DMB_ARTIFACT:-} == /* && -f $DMB_ARTIFACT ]] || return 1; printf '%s\n' "$DMB_ARTIFACT"; }
dmb_valid_name() { [[ ${1-} =~ ^[A-Za-z0-9][A-Za-z0-9_.:-]{0,127}$ ]]; }
dmb_valid_user() { [[ ${1-} =~ ^[a-zA-Z_][a-zA-Z0-9_.-]{0,31}\$?$ ]]; }
dmb_valid_unit() { [[ ${1-} =~ ^[A-Za-z0-9_@.:-]+\.(service|socket|timer)$ ]]; }
dmb_run() (
  local seconds=${1-} fd; shift || return 64
  [[ $seconds =~ ^[1-9][0-9]{0,3}$ && $# -gt 0 ]] || return 64
  # Close all registered locks in descendants; never evaluate state as code.
  if declare -F dmb_tx_close_locks >/dev/null; then dmb_tx_close_locks || return
  else for fd in "${DMB_LOCK_FDS[@]-}"; do [[ $fd =~ ^[0-9]+$ ]] && exec {fd}>&-; done; fi
  timeout --signal=TERM --kill-after=3 "$seconds" "$@"
)
dmb_timeout() { dmb_run "$@"; }
dmb_trusted_path() {
  local path=${1-} missing=${2-} part current='' uid mode oct
  [[ $path == /* && $path != *$'\n'* && $path != *'/../'* && $path != */.. && $path != *'/./'* ]] || return 78
  local -a parts; IFS=/ read -r -a parts <<< "$path"
  for part in "${parts[@]}"; do
    [[ -n $part ]] || continue
    current+="/$part"
    [[ ! -L $current ]] || { dmb_error "Symlink in protected path: $current"; return 78; }
    if [[ ! -e $current ]]; then [[ $missing == allow_missing ]] && return 0; return 78; fi
    uid=$(stat -c %u -- "$current") || return 78
    mode=$(stat -c %a -- "$current") || return 78
    [[ $uid == 0 && $mode =~ ^[0-7]{3,4}$ ]] || return 78
    oct=$((8#$mode))
    (( (oct & 0022) == 0 )) || { dmb_error "Writable protected ancestor: $current"; return 78; }
  done
}
dmb_private_tmp() {
  local parent=${1:-$DMB_RUNTIME_DIR/tmp}
  dmb_require_root || return
  dmb_trusted_path "$parent" allow_missing || return
  mkdir -p -- "$parent" && chmod 0700 -- "$parent" || return
  dmb_trusted_path "$parent" || return
  mktemp -d "$parent/work.XXXXXXXXXXXX"
}
dmb_scratch_tmp() {
  # Native parsers sometimes require a filename for a hypothetical config.
  # This private, disposable workspace creates no durable program state.
  dmb_require_root || return
  dmb_trusted_path /run || return
  mktemp -d /run/.dmitbox-plan.XXXXXXXXXXXX
}
dmb_atomic_write() (
  local path=$1 mode=$2 expected=${3:-} expected_state=${4:-} parent tmp actual
  [[ $mode =~ ^0?[0-7]{3,4}$ ]] || return 64
  [[ -z $expected || $expected =~ ^[a-f0-9]{64}$ ]] || return 64
  parent=${path%/*}; [[ -n $parent ]] || parent=/
  dmb_trusted_path "$parent" || return
  dmb_trusted_path "$path" allow_missing || return
  [[ ! -e $path || -f $path ]] || return 78
  tmp=$(mktemp "$parent/.dmitbox-write.XXXXXXXXXXXX") || return
  trap 'rm -f -- "$tmp"' EXIT
  chmod "$mode" "$tmp" || return
  # An existing file's metadata is retained; chmod only selects creation mode.
  if [[ -e $path ]]; then cp --attributes-only --preserve=all -- "$path" "$tmp" || return; fi
  cat > "$tmp" || return
  if [[ -n $expected ]]; then
    actual=$(sha256sum -- "$tmp") || return
    [[ ${actual%% *} == "$expected" ]] || return 74
  fi
  # Internal durable records must be complete even when a producer failed
  # before closing its pipe. A zero-length/truncated record is never published.
  if [[ $path == "$DMB_STATE_DIR/"*.json || $path == "$DMB_RUNTIME_DIR/"*.json ]]; then
    jq -e 'true' "$tmp" >/dev/null || return 74
  fi
  if [[ -e $path ]]; then cp --attributes-only --preserve=all -- "$path" "$tmp" || return; fi
  if [[ -n $expected_state ]]; then
    declare -F dmb_file_state >/dev/null || return 69
    actual=$(dmb_file_state "$tmp" | jq -ceS .) || return
    [[ $actual == "$(jq -ceS . <<< "$expected_state")" ]] || return 78
  fi
  sync -f "$tmp" || return
  mv -T -- "$tmp" "$path" || return
  sync -f "$parent" || return
)
dmb_json_hash() { jq -cS . | sha256sum | cut -d' ' -f1; }
dmb_audit() {
  local event=$1 detail=${2:-'{}'} record dir
  dmb_valid_name "$event" || return 64
  dir=$DMB_STATE_DIR/audit
  dmb_trusted_path "$dir" allow_missing || return
  mkdir -p -- "$dir" && chmod 0700 -- "$dir" || return
  record=$(mktemp "$dir/event.XXXXXXXXXXXX.json") || return
  jq -cn --arg event "$event" --arg boot "$(cat /proc/sys/kernel/random/boot_id)" --arg uptime "$(cut -d' ' -f1 /proc/uptime)" --argjson detail "$detail" '{schema:1,event:$event,boot_id:$boot,uptime:$uptime,detail:$detail}' | dmb_atomic_write "$record" 0600
}
# END MODULE core.sh

# BEGIN MODULE validation.sh
# Strict family-aware parsing. No DNS lookup, libc shorthand, zones, or octal.
dmb_ipv4_words() {
  local ip=${1-} x; local -a words
  [[ $ip =~ ^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$ ]] || return 64
  IFS=. read -r -a words <<< "$ip"
  for x in "${words[@]}"; do
    [[ $x == 0 || $x =~ ^[1-9][0-9]{0,2}$ ]] || return 64
    (( 10#$x <= 255 )) || return 64
  done
  printf '%d %d %d %d\n' "${words[@]}"
}
dmb_ipv6_words() {
  local ip=${1-} left right x v4 tail missing; local -a a=() b=() ipv6_expanded=() w=()
  [[ $ip == *:* && $ip != *[!0-9a-fA-F:.]* ]] || return 64
  if [[ $ip == *.* ]]; then
    tail=${ip##*:}; v4=$(dmb_ipv4_words "$tail") || return 64
    IFS=' ' read -r -a w <<< "$v4"
    printf -v tail '%x:%x' "$((w[0]*256+w[1]))" "$((w[2]*256+w[3]))"
    ip=${ip%:*}:$tail
  fi
  if [[ $ip == *::* ]]; then
    left=${ip%%::*}; right=${ip#*::}; [[ $right != *::* ]] || return 64
    [[ -z $left ]] || IFS=: read -r -a a <<< "$left"
    [[ -z $right ]] || IFS=: read -r -a b <<< "$right"
    missing=$((8-${#a[@]}-${#b[@]})); ((missing>=1)) || return 64
  else
    [[ $ip != :* && $ip != *: ]] || return 64
    IFS=: read -r -a a <<< "$ip"; ((${#a[@]}==8)) || return 64
    missing=0
  fi
  for x in "${a[@]}"; do [[ $x =~ ^[a-fA-F0-9]{1,4}$ ]] || return 64; ipv6_expanded+=("$((16#$x))"); done
  while ((missing>0)); do ipv6_expanded+=(0); ((missing--)); done
  for x in "${b[@]}"; do [[ $x =~ ^[a-fA-F0-9]{1,4}$ ]] || return 64; ipv6_expanded+=("$((16#$x))"); done
  ((${#ipv6_expanded[@]}==8)) || return 64
  printf '%s\n' "${ipv6_expanded[*]}"
}
dmb_ipv6_render() {
  local -a w=("$@"); local i start=-1 best=-1 len=0 longest=1 rendered='' hex
  for ((i=0;i<=8;i++)); do
    if ((i<8 && w[i]==0)); then ((start>=0)) || start=$i; ((len++))
    else
      if ((len>longest)); then best=$start; longest=$len; fi
      start=-1; len=0
    fi
  done
  for ((i=0;i<8;i++)); do
    if ((i==best)); then rendered+='::'; i=$((i+longest-1)); continue; fi
    printf -v hex '%x' "${w[i]}"
    [[ -z $rendered || $rendered == *: ]] || rendered+=:
    rendered+=$hex
  done
  printf '%s\n' "$rendered"
}
dmb_ip_parse() {
  local ip=${1-} family=${2-} words; local -a w
  if [[ $ip == *:* ]]; then
    [[ -z $family || $family == 6 ]] || return 64
    words=$(dmb_ipv6_words "$ip") || return; IFS=' ' read -r -a w <<< "$words"; dmb_ipv6_render "${w[@]}"
  else
    [[ -z $family || $family == 4 ]] || return 64
    words=$(dmb_ipv4_words "$ip") || return; IFS=' ' read -r -a w <<< "$words"; printf '%d.%d.%d.%d\n' "${w[@]}"
  fi
}
dmb_cidr_parse() {
  local cidr=${1-} family=${2-} ip bits words width max i keep; local -a w
  [[ $cidr == */* && $cidr != */*/* ]] || return 64
  ip=${cidr%/*}; bits=${cidr##*/}; [[ $bits == 0 || $bits =~ ^[1-9][0-9]{0,2}$ ]] || return 64
  ip=$(dmb_ip_parse "$ip" "$family") || return
  if [[ $ip == *:* ]]; then width=16; max=128; words=$(dmb_ipv6_words "$ip"); else width=8; max=32; words=$(dmb_ipv4_words "$ip"); fi
  ((bits<=max)) || return 64; IFS=' ' read -r -a w <<< "$words"
  for ((i=0;i<${#w[@]};i++)); do keep=$((bits-i*width)); if ((keep<=0)); then w[i]=0; elif ((keep<width)); then w[i]=$((w[i] & (((1<<keep)-1)<<(width-keep)))); fi; done
  if ((width==16)); then ip=$(dmb_ipv6_render "${w[@]}"); else printf -v ip '%d.%d.%d.%d' "${w[@]}"; fi
  printf '%s/%d\n' "$ip" "$bits"
}
dmb_ip_in_cidr() {
  local ip=$1 cidr=$2 canonical actual
  canonical=$(dmb_cidr_parse "$cidr") || return
  actual=$(dmb_cidr_parse "$ip/${canonical##*/}") || return
  [[ $canonical == "$actual" ]]
}
# END MODULE validation.sh

# BEGIN MODULE filesystem.sh
# Regular-file ownership adapter. Raw snapshots and inode identity are separate
# from the stable logical state used by the transaction engine.
dmb_file_metadata() {
  local path=$1 acl attrs
  dmb_need getfacl getfattr base64 jq || return
  acl=$(LC_ALL=C getfacl -cpn -- "$path" | base64 -w0) || return
  attrs=$(LC_ALL=C getfattr --absolute-names --encoding=hex -d -m - -- "$path" | sed '/^#/d;/^$/d' | LC_ALL=C sort | base64 -w0) || return
  jq -cn --arg mode "$(stat -c %a -- "$path")" --argjson uid "$(stat -c %u -- "$path")" --argjson gid "$(stat -c %g -- "$path")" --arg acl "$acl" --arg attrs "$attrs" '{mode:$mode,uid:$uid,gid:$gid,acl_b64:$acl,xattrs_b64:$attrs}'
}
dmb_file_state() {
  local path=$1 meta hash
  dmb_trusted_path "$path" allow_missing || return
  if [[ ! -e $path ]]; then printf '{"exists":false}\n'; return; fi
  [[ -f $path && ! -L $path && $(stat -c %h -- "$path") == 1 ]] || { dmb_error 'Only regular files with one hard link are supported'; return 78; }
  meta=$(dmb_file_metadata "$path") || return
  hash=$(sha256sum -- "$path") || return; hash=${hash%% *}
  jq -cn --argjson meta "$meta" --arg hash "$hash" '$meta+{exists:true,type:"file",sha256:$hash}'
}
dmb_file_desired() {
  local path=$1 content=$2 mode=${3:-600} before hash acl u g o
  [[ -f $content && ! -L $content && $mode =~ ^[0-7]{3}$ ]] || return 64
  before=$(dmb_file_state "$path") || return
  hash=$(sha256sum -- "$content") || return; hash=${hash%% *}
  if [[ $(jq -r .exists <<< "$before") == true ]]; then jq -cS --arg hash "$hash" '.sha256=$hash' <<< "$before"; return; fi
  u=$((8#${mode:0:1})); g=$((8#${mode:1:1})); o=$((8#${mode:2:1}))
  local perms='' n bit; for n in "$u" "$g" "$o"; do for bit in 4 2 1; do if ((n&bit)); then case $bit in 4) perms+=r;; 2) perms+=w;; 1) perms+=x;; esac; else perms+=-; fi; done; done
  acl=$(printf 'user::%s\ngroup::%s\nother::%s\n\n' "${perms:0:3}" "${perms:3:3}" "${perms:6:3}" | base64 -w0)
  jq -cn --arg hash "$hash" --arg mode "$mode" --arg acl "$acl" '{exists:true,type:"file",sha256:$hash,mode:$mode,uid:0,gid:0,acl_b64:$acl,xattrs_b64:""}'
}
dmb_file_capture() {
  local path=$1 dir=$2 slot=$3 before after identity
  dmb_valid_name "$slot" || return 64
  dmb_trusted_path "$dir" || return
  before=$(dmb_file_state "$path" | jq -cS .) || return
  [[ ! -e $dir/$slot.json && ! -e $dir/$slot.raw ]] || return 78
  if [[ $(jq -r .exists <<< "$before") == true ]]; then
    identity=$(stat -c '%d:%i:%h' -- "$path") || return
    cp -a -- "$path" "$dir/$slot.raw" || return
    after=$(dmb_file_state "$dir/$slot.raw" | jq -cS .) || return
    [[ $before == "$after" && $identity == "$(stat -c '%d:%i:%h' -- "$path")" ]] || return 76
    sync -f "$dir/$slot.raw" || return
  else identity=absent; fi
  jq -cn --arg path "$path" --arg identity "$identity" --argjson state "$before" '{schema:1,path:$path,identity:$identity,state:$state}' | dmb_atomic_write "$dir/$slot.json" 0600
}
dmb_file_restore() {
  local path=$1 dir=$2 slot=$3 expected=$4 current before raw tmp parent
  dmb_valid_name "$slot" || return 64
  dmb_trusted_path "$dir/$slot.json" || return
  [[ $(jq -er .path "$dir/$slot.json") == "$path" ]] || return 76
  current=$(dmb_file_state "$path" | jq -cS .) || return
  before=$(jq -cS .state "$dir/$slot.json") || return
  [[ $current != "$before" ]] || return 0
  [[ $(printf '%s\n' "$current" | sha256sum | cut -d' ' -f1) == "$expected" ]] || return 76
  parent=${path%/*}
  if [[ $(jq -r .exists <<< "$before") == false ]]; then rm -- "$path" || return; sync -f "$parent" || return
  else
    raw=$dir/$slot.raw
    [[ $(dmb_file_state "$raw" | jq -cS .) == "$before" ]] || return 76
    tmp=$(mktemp "$parent/.dmitbox-restore.XXXXXXXXXXXX") || return
    if ! cp --preserve=all -- "$raw" "$tmp"; then rm -f -- "$tmp"; return 74; fi
    # A successful cp alone does not establish ACL/xattr/security-context
    # preservation. Never replace the live resource with an unverified copy.
    if [[ $(dmb_file_state "$tmp" | jq -cS .) != "$before" ]]; then rm -f -- "$tmp"; return 78; fi
    if ! sync -f "$tmp" || ! mv -T -- "$tmp" "$path" || ! sync -f "$parent"; then rm -f -- "$tmp"; return 74; fi
  fi
  [[ $(dmb_file_state "$path" | jq -cS .) == "$before" ]]
}
dmb_fs_plan_validate() {
  local plan=$1 index=$2 adapter purpose path content algorithm expected_content
  adapter=$(jq -er --argjson i "$index" '.steps[$i].adapter // .adapter' "$plan") || return 64
  # SSH uses the file primitives after validating its enrolled fragment and
  # port-only payload. It must not inherit generic file-write authority.
  [[ $adapter == fs ]] || return 0
  purpose=$(jq -er --argjson i "$index" '.steps[$i].purpose' "$plan") || return 64
  path=$(jq -er --argjson i "$index" '.steps[$i].path' "$plan") || return 64
  case $purpose in
    gai) [[ $path == "$DMB_ETC_ROOT/gai.conf" ]] || return 64;;
    tcp-profile)
      [[ $path == /etc/sysctl.d/90-dmitbox-local-tcp.conf ]] || return 64
      jq -e --argjson i "$index" '.steps[$i] | .after.exists==true and (.before==null or .before.exists==false)' "$plan" >/dev/null || return 64
      content=$(jq -er --argjson i "$index" '.steps[$i].content_b64' "$plan" | base64 -d) || return 64
      algorithm=${content##* = }
      [[ $algorithm == bbr || $algorithm == cubic ]] || return 64
      printf -v expected_content '# dmitbox-local profile schema=1\nnet.ipv4.tcp_congestion_control = %s' "$algorithm"
      [[ $content == "$expected_content" ]] || return 64
      # A generic file step cannot silently install a boot-time tuning profile
      # without the corresponding explicitly measured, named runtime change.
      jq -e --arg algorithm "$algorithm" '. as $p|any(.steps[]; (.adapter // $p.adapter)=="tcp" and .key=="net.ipv4.tcp_congestion_control" and .after.value==$algorithm and .measurement.requested==true)' "$plan" >/dev/null || return 64;;
    recovery-probe) [[ $path == "$DMB_STATE_DIR/recovery-probe" ]] || return 64;;
    *) dmb_error 'Generic filesystem mutation requires a supported purpose and its exact owned path'; return 64;;
  esac
}
dmb_fs_capture() { local path; dmb_fs_plan_validate "$1" "$2" || return; path=$(jq -er --argjson i "$2" '.steps[$i].path' "$1") || return; dmb_file_state "$path"; }
dmb_fs_snapshot() {
  dmb_fs_plan_validate "$1" "$2" || return
  local path id; path=$(jq -er --argjson i "$2" '.steps[$i].path' "$1") || return
  id=$(jq -er --argjson i "$2" '.steps[$i].id' "$1") || return
  # A repeated file resource needs an adapter capable of synthesizing the
  # intermediate snapshot. The generic adapter deliberately has no such claim.
  jq -e --argjson i "$2" --arg path "$path" 'all(.steps[:$i][]; .path!=$path)' "$1" >/dev/null || return 69
  dmb_file_capture "$path" "$3/snapshots" "$id"
}
dmb_fs_apply() {
  local plan=$1 i=$2 path mode before expected tmp parent hash expected_state
  dmb_fs_plan_validate "$plan" "$i" || return
  path=$(jq -er --argjson i "$i" '.steps[$i].path' "$plan") || return
  mode=$(jq -er --argjson i "$i" '.steps[$i].after.mode // "600"' "$plan") || return
  before=$(jq -cS --argjson i "$i" '.steps[$i].before' "$plan") || return
  [[ $(dmb_file_state "$path" | jq -cS .) == "$before" ]] || return 76
  expected=$(jq -r --argjson i "$i" '.steps[$i].after.exists' "$plan") || return
  expected_state=$(jq -cS --argjson i "$i" '.steps[$i].after' "$plan") || return
  if [[ $expected == false ]]; then rm -- "$path" || return; sync -f "${path%/*}"; return; fi
  hash=$(jq -er --argjson i "$i" '.steps[$i].after.sha256' "$plan") || return
  if [[ $(jq -r .exists <<< "$before") == true ]]; then jq -r --argjson i "$i" '.steps[$i].content_b64' "$plan" | base64 -d | dmb_atomic_write "$path" "$mode" "$hash" "$expected_state"
  else
    parent=${path%/*}; dmb_trusted_path "$parent" || return
    tmp=$(mktemp "$parent/.dmitbox-create.XXXXXXXXXXXX") || return
    if ! jq -r --argjson i "$i" '.steps[$i].content_b64' "$plan" | base64 -d > "$tmp"; then rm -f -- "$tmp"; return 74; fi
    [[ $(sha256sum -- "$tmp" | cut -d' ' -f1) == "$hash" ]] || { rm -f -- "$tmp"; return 74; }
    chmod "$mode" "$tmp" || { rm -f -- "$tmp"; return 74; }
    # A default directory ACL or security label may differ from a planner's
    # predicted creation metadata. Refuse before linking any live resource.
    if [[ $(dmb_file_state "$tmp" | jq -cS .) != "$expected_state" ]]; then rm -f -- "$tmp"; return 78; fi
    sync -f "$tmp" && ln -T -- "$tmp" "$path"; local rc=$?
    rm -f -- "$tmp"; ((rc==0)) || return "$rc"
    sync -f "$parent"
  fi
}
dmb_fs_verify() { local actual expected; actual=$(dmb_fs_capture "$1" "$2" | jq -cS .) || return; expected=$(jq -cS --argjson i "$2" '.steps[$i].after' "$1") || return; [[ $actual == "$expected" ]]; }
dmb_fs_verify_restore() { local actual expected; actual=$(dmb_fs_capture "$1" "$2" | jq -cS .) || return; expected=$(jq -cS --argjson i "$2" '.steps[$i].before' "$1") || return; [[ $actual == "$expected" ]]; }
dmb_fs_restore() {
  local path id expected
  dmb_fs_plan_validate "$1" "$2" || return
  path=$(jq -er --argjson i "$2" '.steps[$i].path' "$1") || return
  id=$(jq -er --argjson i "$2" '.steps[$i].id' "$1") || return
  expected=$(jq -cS --argjson i "$2" '.steps[$i].after' "$1" | sha256sum | cut -d' ' -f1) || return
  dmb_file_restore "$path" "$3/snapshots" "$id" "$expected"
}
# END MODULE filesystem.sh

# BEGIN MODULE gai.sh
# glibc address selection is local policy, not a connectivity test. Preserve all
# unrelated entries and refuse competing active precedence rules.
dmb_gai_plan() {
  local action=${1-} path=$DMB_ETC_ROOT/gai.conf before content encoded hash after id source original
  case $action in v4|default|restore) ;; *) return 64;; esac
  dmb_need jq getfacl getfattr base64 || return
  before=$(dmb_file_state "$path" | jq -cS .) || return
  if [[ $action == restore ]]; then
    local candidate found=''
    for candidate in "$DMB_STATE_DIR"/transactions/tx-*/plan.json; do
      [[ -f $candidate && ! -L $candidate ]] || continue
      dmb_trusted_path "$candidate" || return
      [[ $(jq -r .state "${candidate%/*}/state.json") == COMMITTED ]] || continue
      if jq -e --arg path "$path" 'any(.steps[];.adapter=="fs" and .path==$path and .purpose=="gai")' "$candidate" >/dev/null; then
        source=$(jq -cS --arg path "$path" '.steps[]|select(.adapter=="fs" and .path==$path and .purpose=="gai")' "$candidate") || return
        [[ $(jq -cS .after <<< "$source") == "$before" ]] || continue
        [[ -z $found ]] || { dmb_error 'Multiple matching gai restore points; select an explicit audited inverse plan'; return 76; }
        found=$source; id=$(jq -r .id <<< "$source")
        original=${candidate%/*}/snapshots/$id.raw
        if [[ $(jq -r .before.exists <<< "$source") == true ]]; then
          [[ -f $original ]] || return 78
          [[ $(dmb_file_state "$original" | jq -cS .) == "$(jq -cS .before <<< "$source")" ]] || return 76
          encoded=$(base64 -w0 "$original") || return
        else encoded=''; fi
      fi
    done
    [[ -n $found ]] || { dmb_error 'No unique verified committed gai restore point'; return 69; }
    after=$(jq -cS .before <<< "$found") || return
  else
    content=''; [[ ! -e $path ]] || content=$(cat -- "$path") || return
    [[ $(printf '%s\n' "$content" | grep -c '^# BEGIN dmitbox-local gai$') -le 1 ]] || return 76
    [[ $(printf '%s\n' "$content" | grep -c '^# END dmitbox-local gai$') -le 1 ]] || return 76
    if [[ $content == *'# BEGIN dmitbox-local gai'* || $content == *'# END dmitbox-local gai'* ]]; then
      printf '%s\n' "$content" | awk '/^# BEGIN dmitbox-local gai$/{if(open)exit 1;open=1;next} /^# END dmitbox-local gai$/{if(!open)exit 1;open=0;next} END{if(open)exit 1}' || return 76
    fi
    content=$(printf '%s\n' "$content" | sed '/^# BEGIN dmitbox-local gai$/,/^# END dmitbox-local gai$/d') || return
    if printf '%s\n' "$content" | grep -Eq '^[[:space:]]*precedence[[:space:]]'; then dmb_error 'Existing precedence policy has independent ownership'; return 76; fi
    if [[ $action == v4 ]]; then
      content+=$'\n# BEGIN dmitbox-local gai\nprecedence ::1/128 50\nprecedence ::/0 40\nprecedence 2002::/16 30\nprecedence ::/96 20\nprecedence ::ffff:0:0/96 100\n# END dmitbox-local gai'
    fi
    encoded=$(printf '%s\n' "$content" | base64 -w0)
    hash=$(printf '%s' "$encoded" | base64 -d | sha256sum | cut -d' ' -f1) || return
    if [[ $(jq -r .exists <<< "$before") == true ]]; then after=$(jq -cS --arg hash "$hash" '.sha256=$hash' <<< "$before") || return
    else
      local acl
      acl=$(printf 'user::rw-\ngroup::r--\nother::r--\n\n' | base64 -w0)
      after=$(jq -cn --arg hash "$hash" --arg acl "$acl" '{exists:true,type:"file",sha256:$hash,mode:"644",uid:0,gid:0,acl_b64:$acl,xattrs_b64:""}') || return
    fi
  fi
  jq -cn --arg path "$path" --arg content "$encoded" --argjson before "$before" --argjson after "$after" '{schema:1,adapter:"fs",resources:[("file:"+$path)],allow_console_confirmation:true,steps:[{id:"gai",adapter:"fs",resource:("file:"+$path),path:$path,purpose:"gai",before:$before,after:$after,content_b64:$content}],verification:{external_access:"requires_fresh_transport_or_enrolled_console"}}'
}
dmb_gai() (
  dmb_require_root || return
  local tmp; tmp=$(dmb_private_tmp) || return
  trap 'rm -rf -- "$tmp"' EXIT
  dmb_gai_plan "$1" > "$tmp/plan.json" || return
  dmb_apply_file "$tmp/plan.json"
)
# END MODULE gai.sh

# BEGIN MODULE confirmation.sh
# Authenticated-transport confirmation. This module never trusts SSH_CONNECTION.
# shellcheck shell=bash

_dmb_confirmation_error() { printf 'Confirmation: %s\n' "$*" >&2; return 1; }
_dmb_confirmation_root() { (( EUID == 0 )); }
_dmb_confirmation_digest() { sha256sum | awk '{print $1}'; }
_dmb_confirmation_manifest() {
  local txdir=${1:-} path
  path="${DMB_STATE_DIR:-/var/lib/dmitbox-local}/enrollments/ssh.json"
  if [[ -n "$txdir" ]]; then
    local enrolled
    enrolled=$(jq -r '.confirmation_enrollment // empty' "$txdir/plan.json") || return 1
    # Plans can name the enrolled resource, not select arbitrary manifest paths.
    [[ -z "$enrolled" || "$enrolled" == ssh ]] || return 1
  fi
  dmb_trusted_path "$path" || return 1
  jq -e '.schema == 1 and (.confirmation|type=="object")' "$path" >/dev/null || return 1
  printf '%s\n' "$path"
}
_dmb_confirmation_proc_fields() {
  local proc=$1 pid=$2 text tail
  [[ "$pid" =~ ^[1-9][0-9]*$ && -d "$proc/$pid" && ! -L "$proc/$pid" ]] || return 1
  IFS= read -r text < "$proc/$pid/stat" || return 1
  [[ "$text" == "$pid ("* && "$text" == *') '* ]] || return 1
  # comm can contain spaces and ')'; fields after its final ')' are numeric.
  tail=${text##*) }
  local -a fields=()
  IFS=' ' read -r -a fields <<< "$tail"
  [[ ${#fields[@]} -ge 20 && ${fields[1]} =~ ^[0-9]+$ && ${fields[19]} =~ ^[0-9]+$ ]] || return 1
  printf '%s %s\n' "${fields[1]}" "${fields[19]}"
}
_dmb_confirmation_cgroup() {
  local proc=$1 pid=$2 number controllers path
  while IFS=: read -r number controllers path; do
    if [[ "$number" == 0 && -z "$controllers" ]] || [[ ",$controllers," == *,name=systemd,* ]]; then
      [[ "$path" == /* && "$path" != *$'\n'* ]] || return 1
      printf '%s\n' "$path"; return 0
    fi
  done < "$proc/$pid/cgroup"
  return 1
}
_dmb_confirmation_binary() {
  local manifest=$1 kind=$2 proc=$3 pid=$4 exe digest uid mode
  exe=$(readlink -- "$proc/$pid/exe") || return 1
  [[ "$exe" == /* && "$exe" != *' (deleted)' ]] || return 1
  dmb_trusted_path "$exe" || return 1
  [[ -f "$exe" && -x "$exe" ]] || return 1
  uid=$(stat -Lc '%u' -- "$proc/$pid/exe") || return 1
  mode=$(stat -Lc '%a' -- "$proc/$pid/exe") || return 1
  [[ "$uid" == 0 && "$mode" =~ ^[0-7]{3,4}$ ]] || return 1
  (( (8#$mode & 0022) == 0 )) || return 1
  digest=$(sha256sum -- "$proc/$pid/exe" | awk '{print $1}') || return 1
  jq -e --arg kind "$kind" --arg path "$exe" --arg digest "$digest" '
    .confirmation[$kind] | type=="array" and any(.[]; .path==$path and .sha256==$digest)
  ' "$manifest" >/dev/null || return 1
  printf '%s\n' "$exe"
}
_dmb_confirmation_group_allowed() {
  local manifest=$1 kind=$2 cgroup=$3
  jq -e --arg key "$kind" --arg group "$cgroup" '.confirmation[$key] | type=="array" and index($group)!=null' "$manifest" >/dev/null
}
_dmb_confirmation_ss() { ss -H -n -t -e -p -O state established; }
_dmb_confirmation_endpoint() {
  local value=$1 address port
  if [[ "$value" == \[*\]:* ]]; then
    address=${value#\[}; address=${address%\]:*}; port=${value##*:}
  else
    address=${value%:*}; port=${value##*:}
  fi
  [[ "$address" =~ ^[0-9a-fA-F:.]+$ && "$port" =~ ^[0-9]{1,5}$ ]] || return 1
  (( 10#$port > 0 && 10#$port <= 65535 )) || return 1
  printf '%s\t%s\n' "$address" "$((10#$port))"
}
_dmb_confirmation_socket() {
  local proc=$1 pid=$2 listing=$3 fd link inode line recv send local_endpoint peer_endpoint rest
  local local_address local_port peer_address peer_port found='' candidate
  local -A observed_inodes=()
  for fd in "$proc/$pid/fd/"*; do
    [[ -L "$fd" ]] || continue
    link=$(readlink -- "$fd") || continue
    [[ "$link" =~ ^socket:\[([0-9]+)\]$ ]] || continue
    inode=${BASH_REMATCH[1]}
    [[ ! -v observed_inodes[$inode] ]] || continue
    observed_inodes[$inode]=1
    while IFS= read -r line; do
      [[ " $line " =~ [[:space:]]ino:$inode([[:space:]]|$) ]] || continue
      IFS=' ' read -r recv send local_endpoint peer_endpoint rest <<< "$line"
      [[ "$recv" =~ ^[0-9]+$ && "$send" =~ ^[0-9]+$ ]] || return 1
      IFS=$'\t' read -r local_address local_port < <(_dmb_confirmation_endpoint "$local_endpoint")
      IFS=$'\t' read -r peer_address peer_port < <(_dmb_confirmation_endpoint "$peer_endpoint")
      [[ -n "$local_address" && -n "$local_port" && -n "$peer_address" && -n "$peer_port" ]] || return 1
      candidate=$(jq -cn --arg inode "$inode" --arg la "$local_address" --argjson lp "$local_port" --arg pa "$peer_address" --argjson pp "$peer_port" '{socket_inode:$inode,local_address:$la,local_port:$lp,peer_address:$pa,peer_port:$pp}') || return 1
      [[ -z "$found" || "$found" == "$candidate" ]] || return 1
      found=$candidate
    done <<< "$listing"
  done
  [[ -n "$found" ]] || return 1
  printf '%s\n' "$found"
}
_dmb_confirmation_proc_uid() {
  local proc=$1 pid=$2 key real effective saved filesystem rest
  while IFS=$' \t' read -r key real effective saved filesystem rest; do
    [[ $key == Uid: ]] || continue
    [[ $real =~ ^[0-9]{1,10}$ && $real == "$effective" && $real == "$saved" && $real == "$filesystem" ]] || return 1
    ((10#$real<4294967295)) || return 1
    printf '%s\n' "$((10#$real))"; return 0
  done < "$proc/$pid/status"
  return 1
}
_dmb_confirmation_local_user() {
  local uid=$1 name _password candidate _gid _gecos _home _shell found=''
  # A local account file is deterministic and makes no implicit NSS/network
  # request. Directory-service-only identities need a dedicated native adapter.
  dmb_trusted_path /etc/passwd || return 1
  while IFS=: read -r name _password candidate _gid _gecos _home _shell; do
    [[ $candidate == "$uid" ]] || continue
    [[ $name =~ ^[A-Za-z_][A-Za-z0-9_.-]{0,31}\$?$ && -z $found ]] || return 1
    found=$name
  done < /etc/passwd
  [[ -n $found ]] || return 1
  printf '%s\n' "$found"
}
# Explicit proc root/start arguments exist only for library fixtures. Public CLI
# always calls this with literal /proc and Bash's kernel PID, never environment.
_dmb_confirmation_transport_at() {
  local manifest=$1 proc=$2 pid=$3 listing boot fields parent start exe group socket count=0
  local session_uid='' process_uid login_user audit_uid='' observed_audit current_fields
  local -A seen=()
  listing=$(_dmb_confirmation_ss) || return 1
  IFS= read -r boot < "$proc/sys/kernel/random/boot_id" || return 1
  [[ "$boot" =~ ^[0-9a-fA-F-]{36}$ ]] || return 1
  if [[ -r $proc/$pid/loginuid ]]; then
    IFS= read -r observed_audit < "$proc/$pid/loginuid" || [[ -n $observed_audit ]] || return 1
    [[ $observed_audit =~ ^[0-9]{1,10}$ ]] || return 1
    [[ $observed_audit == 4294967295 ]] || audit_uid=$observed_audit
  fi
  while [[ "$pid" != 0 && "$pid" != 1 ]]; do
    (( count += 1 )); (( count <= 128 )) || return 1
    [[ ! -v seen[$pid] ]] || return 1; seen[$pid]=1
    fields=$(_dmb_confirmation_proc_fields "$proc" "$pid") || return 1
    IFS=' ' read -r parent start <<< "$fields"
    if exe=$(_dmb_confirmation_binary "$manifest" sshd_binaries "$proc" "$pid" 2>/dev/null); then
      process_uid=$(_dmb_confirmation_proc_uid "$proc" "$pid") || return 1
      if [[ $process_uid != 0 ]]; then
        [[ -z $session_uid || $session_uid == "$process_uid" ]] || return 1
        session_uid=$process_uid
      fi
      group=$(_dmb_confirmation_cgroup "$proc" "$pid") || { pid=$parent; continue; }
      if ! _dmb_confirmation_group_allowed "$manifest" ssh_cgroups "$group"; then pid=$parent; continue; fi
      if socket=$(_dmb_confirmation_socket "$proc" "$pid" "$listing"); then
        [[ -n $session_uid ]] || session_uid=0
        [[ -z $audit_uid || $audit_uid == "$session_uid" ]] || return 1
        login_user=$(_dmb_confirmation_local_user "$session_uid") || return 1
        jq -e --arg user "$login_user" '.contexts|type=="array" and any(.[];.user==$user)' "$manifest" >/dev/null || return 1
        current_fields=$(_dmb_confirmation_proc_fields "$proc" "$pid") || return 1
        [[ $current_fields == "$fields" ]] || return 1
        jq -cnS --argjson socket "$socket" --arg boot "$boot" --argjson pid "$pid" --arg start "$start" --arg exe "$exe" --arg cgroup "$group" --arg user "$login_user" --argjson uid "$session_uid" \
          '$socket + {kind:"ssh",boot_id:$boot,pid:$pid,start_ticks:$start,exe:$exe,cgroup:$cgroup,login_user:$user,login_uid:$uid}'
        return $?
      fi
    fi
    pid=$parent
  done
  return 1
}
dmb_confirmation_transport() {
  _dmb_confirmation_root || return 1
  local manifest=${1:-}
  [[ -n "$manifest" ]] || manifest=$(_dmb_confirmation_manifest) || return 1
  dmb_trusted_path "$manifest" || return 1
  _dmb_confirmation_transport_at "$manifest" /proc "$BASHPID"
}
_dmb_confirmation_console_at() {
  local manifest=$1 proc=$2 pid=$3 tty_path=$4 device fields parent start exe group boot count=0 found=''
  [[ "$tty_path" == /dev/* && "$tty_path" != /dev/pts/* && "$tty_path" != /dev/tty && -c "$tty_path" && ! -L "$tty_path" ]] || return 1
  dmb_trusted_path "${tty_path%/*}" || return 1
  [[ $(stat -Lc '%u' -- "$tty_path") == 0 ]] || return 1
  device=$(stat -Lc '%t:%T' -- "$tty_path") || return 1
  jq -e --arg path "$tty_path" --arg device "$device" '.confirmation.console_devices | type=="array" and any(.[];.path==$path and .device==$device)' "$manifest" >/dev/null || return 1
  IFS= read -r boot < "$proc/sys/kernel/random/boot_id" || return 1
  while [[ "$pid" != 0 && "$pid" != 1 ]]; do
    ((count+=1)); ((count<=128)) || return 1
    fields=$(_dmb_confirmation_proc_fields "$proc" "$pid") || return 1
    IFS=' ' read -r parent start <<< "$fields"
    # A console-looking tty inside an SSH ancestry never authorizes OOB bypass.
    if _dmb_confirmation_binary "$manifest" sshd_binaries "$proc" "$pid" >/dev/null 2>&1; then return 1; fi
    if exe=$(_dmb_confirmation_binary "$manifest" console_binaries "$proc" "$pid" 2>/dev/null); then
      group=$(_dmb_confirmation_cgroup "$proc" "$pid") || return 1
      _dmb_confirmation_group_allowed "$manifest" console_cgroups "$group" || return 1
      [[ -z "$found" ]] || { pid=$parent; continue; }
      found=$(jq -cnS --arg device "$device" --arg tty "$tty_path" --arg boot "$boot" --argjson pid "$pid" --arg start "$start" --arg exe "$exe" --arg cgroup "$group" \
        '{kind:"console",device:$device,tty:$tty,boot_id:$boot,pid:$pid,start_ticks:$start,exe:$exe,cgroup:$cgroup}') || return 1
    fi
    pid=$parent
  done
  [[ -n "$found" ]] || return 1
  printf '%s\n' "$found"
}
_dmb_confirmation_controlling_tty() {
  local manifest=$1 proc=$2 pid=$3 stat_line tail encoded device major minor candidate observed found=''
  [[ $pid =~ ^[1-9][0-9]*$ && ! -L $proc/$pid ]] || return 1
  IFS= read -r stat_line < "$proc/$pid/stat" || return 1
  [[ $stat_line == "$pid ("* && $stat_line == *') '* ]] || return 1
  tail=${stat_line##*) }
  local -a stat_fields=()
  IFS=' ' read -r -a stat_fields <<< "$tail"
  [[ ${#stat_fields[@]} -ge 5 && ${stat_fields[4]} =~ ^-?[0-9]+$ ]] || return 1
  encoded=${stat_fields[4]}; ((encoded!=0)) || return 1
  # Linux tty_nr is the encoded dev_t, exposed as a signed 32-bit number.
  device=$((encoded & 0xffffffff))
  major=$(((device >> 8) & 0xfff))
  minor=$(((device & 0xff) | ((device >> 12) & 0xfff00)))
  printf -v device '%x:%x' "$major" "$minor"
  while IFS= read -r candidate; do
    [[ $candidate == /dev/* && $candidate != /dev/pts/* && $candidate != /dev/tty && -c $candidate && ! -L $candidate ]] || continue
    observed=$(stat -Lc '%t:%T' -- "$candidate") || continue
    if [[ $observed == "$device" ]]; then
      [[ -z $found || $found == "$candidate" ]] || return 1
      found=$candidate
    fi
  done < <(jq -r '.confirmation.console_devices[]?.path' "$manifest")
  [[ -n $found ]] || return 1
  printf '%s\n' "$found"
}
dmb_confirmation_console() {
  local manifest=$1 tty_path
  _dmb_confirmation_root || return 1
  # tty </dev/tty reports the alias /dev/tty on common systems; identify the
  # controlling kernel device from /proc instead of trusting that alias or env.
  tty_path=$(_dmb_confirmation_controlling_tty "$manifest" /proc "$BASHPID") || return 1
  _dmb_confirmation_console_at "$manifest" /proc "$BASHPID" "$tty_path"
}

_dmb_confirmation_identity() {
  jq -ceS 'if .kind=="ssh" then {kind,boot_id,socket_inode,local_address,local_port,peer_address,peer_port}
           elif .kind=="console" then {kind,boot_id,device,tty} else error("unsupported transport") end'
}
_dmb_confirmation_fresh() {
  local origin=$1 current=$2 old_identity new_identity
  [[ "$origin" != null && -n "$origin" ]] || return 1
  old_identity=$(printf '%s\n' "$origin" | _dmb_confirmation_identity) || return 1
  new_identity=$(printf '%s\n' "$current" | _dmb_confirmation_identity) || return 1
  [[ "$new_identity" != "$old_identity" ]]
}
_dmb_confirmation_read_challenge() {
  local value='' fd timeout_seconds=${1:-1}
  exec {fd}<>/dev/tty || return 1
  printf 'Enter the one-use confirmation challenge: ' >&"$fd"
  IFS= read -r -s -t "$timeout_seconds" -n 65 value <&"$fd" || { exec {fd}>&-; return 1; }
  printf '\n' >&"$fd"
  exec {fd}>&-
  [[ "$value" =~ ^[0-9a-f]{64}$ ]] || return 1
  printf '%s' "$value" | _dmb_confirmation_digest
  unset value
}
dmb_confirmation_prepare() {
  local txdir=$1 challenge digest fd
  _dmb_confirmation_root && dmb_trusted_path "$txdir" || return 1
  command -v jq >/dev/null && command -v od >/dev/null && command -v sha256sum >/dev/null || return 1
  exec {fd}<>/dev/tty || { _dmb_confirmation_error 'a controlling terminal is required to display the challenge'; return 1; }
  challenge=$(od -An -N32 -tx1 /dev/urandom | tr -d ' \n') || { exec {fd}>&-; return 1; }
  [[ "$challenge" =~ ^[0-9a-f]{64}$ ]] || { exec {fd}>&-; return 1; }
  digest=$(printf '%s' "$challenge" | _dmb_confirmation_digest) || { exec {fd}>&-; return 1; }
  printf '%s\n' "$digest" | dmb_atomic_write "$txdir/challenge.sha256" 0600 || { exec {fd}>&-; return 1; }
  printf '\nOne-use confirmation challenge (keep private): %s\n' "$challenge" >&"$fd"
  unset challenge
  exec {fd}>&-
}
_dmb_confirmation_context_match() {
  local txdir=$1 manifest=$2 current=$3 round=$4 contexts entry user addr laddr port canonical
  # After listener retirement use its final native sshd -T context; other
  # transactions use the explicitly enrolled connection contexts.
  contexts=$(jq -c --argjson round "$round" '
    [.steps[]? | select(.adapter=="ssh" and
      (($round==0 and (.phase//"apply")=="apply") or
       ($round>=1 and .phase=="commit")))] | last |
    if .==null then null else [.after_effective[].context] end' "$txdir/plan.json") || return 1
  [[ $contexts != null ]] || contexts=$(jq -ce '.contexts' "$manifest") || return 1
  while IFS= read -r entry; do
    user=$(jq -er .user <<< "$entry") || continue
    [[ $user == "$(jq -er .login_user <<< "$current")" ]] || continue
    addr=$(jq -er .addr <<< "$entry") || continue
    laddr=$(jq -er .laddr <<< "$entry") || continue
    port=$(jq -er .lport <<< "$entry") || continue
    canonical=$(dmb_ip_parse "$addr") || continue
    [[ $canonical == "$(dmb_ip_parse "$(jq -er .peer_address <<< "$current")")" ]] || continue
    canonical=$(dmb_ip_parse "$laddr") || continue
    [[ $canonical == "$(dmb_ip_parse "$(jq -er .local_address <<< "$current")")" ]] || continue
    [[ $port == "$(jq -er .local_port <<< "$current")" ]] || continue
    return 0
  done < <(jq -c '.[]' <<< "$contexts")
  _dmb_confirmation_error 'authenticated connection is outside the tested user/address/listener context'
}
dmb_confirmation_check() {
  local txdir=$1 mode=${2:-ssh} manifest current baseline proof digest expected generation id round remaining now deadline boot minimum_ticks intended_user
  _dmb_confirmation_root && dmb_trusted_path "$txdir" || return 1
  for proof in plan.json state.json challenge.sha256; do dmb_trusted_path "$txdir/$proof" || return 1; done
  manifest=$(_dmb_confirmation_manifest "$txdir") || return 1
  id=$(jq -er '.id|select(type=="string")' "$txdir/state.json") || return 1
  generation=$(jq -er '.generation|select(type=="number" and floor==. and .>=0)' "$txdir/state.json") || return 1
  round=$(jq -r '.confirmation_round // 0' "$txdir/state.json") || return 1
  case "$mode" in
    ssh)
      current=$(dmb_confirmation_transport "$manifest") || { _dmb_confirmation_error 'cannot prove an authenticated SSH transport from kernel state'; return 1; }
      intended_user=$(jq -er '.confirm_user // .origin_transport.login_user // empty' "$txdir/plan.json") || { _dmb_confirmation_error 'the intended confirmation user must be identified explicitly'; return 1; }
      jq -e --arg user "$intended_user" '.contexts|any(.[];.user==$user)' "$manifest" >/dev/null || return 1
      jq -e --arg user "$intended_user" '.login_user==$user and (.login_uid|type)=="number"' <<< "$current" >/dev/null || { _dmb_confirmation_error 'authenticated user differs from the intended confirmation user'; return 1; }
      _dmb_confirmation_context_match "$txdir" "$manifest" "$current" "$round" || return 1
      minimum_ticks=$(jq -er '.confirmation_min_start_ticks|select(type=="number" and floor==. and .>=0)' "$txdir/state.json") || { _dmb_confirmation_error 'missing post-application connection freshness boundary'; return 1; }
      jq -e --argjson minimum "$minimum_ticks" '(.start_ticks|tonumber)>$minimum' <<< "$current" >/dev/null || { _dmb_confirmation_error 'connection predates the latest applied policy; open a new SSH TCP connection'; return 1; }
      if (( round >= 1 )); then
        dmb_trusted_path "$txdir/proof-1.json" || return 1
        baseline=$(jq -ce '.transport' "$txdir/proof-1.json") || return 1
      else baseline=$(jq -ce '.origin_transport' "$txdir/plan.json") || return 1; fi
      _dmb_confirmation_fresh "$baseline" "$current" || { _dmb_confirmation_error 'a fresh TCP connection is required; disable SSH ControlMaster reuse'; return 1; }
      jq -e --argjson current "$current" '
        (.confirm_port // null) as $port | (.confirm_addresses // []) as $addresses |
        ($port==null or $current.local_port==$port) and
        ($addresses|length==0 or index($current.local_address)!=null or index("0.0.0.0")!=null or index("::")!=null)
      ' "$txdir/plan.json" >/dev/null || { _dmb_confirmation_error 'connection does not reach the target listener'; return 1; }
      ;;
    console)
      jq -e '.allow_console_confirmation == true' "$txdir/plan.json" >/dev/null || return 1
      jq -e '.confirmation.allow_console_confirmation == true' "$manifest" >/dev/null || return 1
      current=$(dmb_confirmation_console "$manifest") || { _dmb_confirmation_error 'cannot prove an enrolled local console'; return 1; }
      ;;
    *) return 2 ;;
  esac
  IFS= read -r expected < "$txdir/challenge.sha256" || return 1
  [[ "$expected" =~ ^[0-9a-f]{64}$ ]] || return 1
  boot=$(jq -er '.boot_id' "$txdir/state.json") || return 1
  [[ $boot == "$(cat /proc/sys/kernel/random/boot_id)" ]] || return 1
  deadline=$(jq -er '.deadline_uptime' "$txdir/state.json") || return 1
  read -r now _ < /proc/uptime || return 1
  now=${now%%.*}; remaining=$((deadline-now)); ((remaining>0)) || return 1
  digest=$(_dmb_confirmation_read_challenge "$remaining") || return 1
  [[ "$digest" == "$expected" ]] || { _dmb_confirmation_error 'challenge did not match'; return 1; }
  digest=$(printf '%s\n' "$current" | _dmb_confirmation_identity | _dmb_confirmation_digest) || return 1
  jq -cnS --arg id "$id" --arg mode "$mode" --argjson generation "$generation" --argjson transport "$current" --arg transport_id "$digest" \
    '{schema:1,transaction_id:$id,mode:$mode,generation:$generation,transport:$transport,transport_id:$transport_id,remote_access_verified:($mode=="ssh")}'
}
dmb_confirmation_verify() { dmb_confirmation_check "$@"; }

# Starting an operation from an OOB console requires its independent enrollment
# and kernel/tty identity. This does not assert external network reachability.
dmb_confirmation_origin() {
  local manifest=${1:-}
  [[ -n $manifest ]] || manifest=$(_dmb_confirmation_manifest) || return
  if dmb_confirmation_transport "$manifest" 2>/dev/null; then return 0; fi
  jq -e '.confirmation.allow_console_confirmation==true' "$manifest" >/dev/null || return 78
  dmb_confirmation_console "$manifest"
}

# Kernel process start_ticks and this boundary share CLK_TCK and boot identity.
# Uptime is monotonic across wall-clock adjustments; no external clock is used.
dmb_confirmation_now_ticks() {
  local uptime rest hz seconds fraction scale=1 i
  hz=$(getconf CLK_TCK) || return 1
  [[ $hz =~ ^[1-9][0-9]{0,5}$ ]] || return 1
  IFS=' ' read -r uptime rest < /proc/uptime || return 1
  [[ $uptime =~ ^[0-9]+[.][0-9]{1,6}$ ]] || return 1
  seconds=${uptime%.*}; fraction=${uptime#*.}
  for ((i=0;i<${#fraction};i++)); do scale=$((scale*10)); done
  printf '%s\n' "$((10#$seconds*hz + 10#$fraction*hz/scale))"
}
# END MODULE confirmation.sh

# BEGIN MODULE adapters/dns.sh
# DNS ownership adapters. Native commands only; source this module after core.
dmb_dns_error() { printf 'dns: %s\n' "$*" >&2; return 2; }
dmb_dns_iface_valid() { [[ ${1:-} =~ ^[[:alnum:]_.:-]{1,15}$ && $1 != -* ]]; }
dmb_dns_etc() { printf '%s\n' "${DMB_ETC_ROOT:-/etc}"; }
dmb_dns_lines_json() { jq -Rsc 'split("\n") | map(select(length>0))'; }
dmb_dns_provider() {
  case $1 in
    cloudflare) printf '%s\n' 1.1.1.1 1.0.0.1 2606:4700:4700::1111 2606:4700:4700::1001 ;;
    google) printf '%s\n' 8.8.8.8 8.8.4.4 2001:4860:4860::8888 2001:4860:4860::8844 ;;
    quad9) printf '%s\n' 9.9.9.9 149.112.112.112 2620:fe::fe 2620:fe::9 ;;
    *) return 2 ;;
  esac
}
dmb_dns_servers() {
  local value canonical family count=0 dns_seen='|' 
  for value in "$@"; do
    canonical=$(dmb_ip_parse "$value") || return 2
    [[ $canonical != 0.0.0.0 && $canonical != 127.* && $canonical != :: && $canonical != ::1 && $canonical != 255.255.255.255 ]] || return 2
    if [[ $canonical == *:* ]]; then
      [[ $canonical != ff* && $canonical != fe[89ab]* ]] || return 2
    else
      family=${canonical%%.*}; (( family < 224 || family > 239 )) || return 2
    fi
    [[ $dns_seen != *"|$canonical|"* ]] || return 2
    dns_seen+="$canonical|"; count=$((count+1)); ((count<=8)) || return 2
    printf '%s\n' "$canonical"
  done
  ((count>0))
}
dmb_dns_nm_list() { tr ',;' '\n\n' | sed -e 's/^[[:space:]]*//' -e 's/[[:space:]]*$//' -e '/^$/d' | dmb_dns_lines_json; }
dmb_dns_numeric_list() {
  local list=$1 family=${2:-} value
  jq -e 'type=="array" and length<=64 and all(.[]; type=="string" and length>0 and length<=64)' <<< "$list" >/dev/null || return 69
  while IFS= read -r value; do
    dmb_ip_parse "$value" "$family" >/dev/null || { dmb_dns_error 'DNS endpoint names, URLs, options or scopes require a dedicated owner adapter'; return 69; }
  done < <(jq -r '.[]' <<< "$list")
}
dmb_dns_resolved_get() {
  local iface=$1 line words
  line=$(dmb_run 8 resolvectl dns "$iface") || return
  # Strip the interface label only, never the ':' within an IPv6 address.
  words=$(printf '%s\n' "$line" | sed -E '1s/^Link[[:space:]]+[0-9]+[[:space:]]+\([^)]*\):[[:space:]]*//')
  local list
  list=$(printf '%s\n' "$words" | tr ' \t' '\n\n' | sed '/^$/d' | dmb_dns_lines_json) || return
  dmb_dns_numeric_list "$list" || return
  printf '%s\n' "$list"
}
dmb_dns_owner() {
  local iface=$1 mode=${2:-owned} etc uuid path json backend manifest process comm
  etc=$(dmb_dns_etc)
  dmb_dns_iface_valid "$iface" || return 2
  dmb_run 5 ip -j link show dev "$iface" >/dev/null || return 2
  if command -v nmcli >/dev/null 2>&1; then
    uuid=$(dmb_run 8 nmcli -g GENERAL.CON-UUID device show "$iface" 2>/dev/null) || uuid=''
    if [[ $uuid =~ ^[[:xdigit:]]{8}-[[:xdigit:]]{4}-[[:xdigit:]]{4}-[[:xdigit:]]{4}-[[:xdigit:]]{12}$ ]]; then
      # Imported generator output must be changed at its source, not adopted.
      if compgen -G "$etc/netplan/*.yaml" >/dev/null || [[ -s ${DMB_RUN_ROOT:-/run}/cloud-init/network-config.json ]]; then
        dmb_dns_error 'unsupported-owner: netplan/cloud-init generated connection'; return 2
      fi
      jq -cn --arg uuid "$uuid" '{owner:"nm",identity:$uuid}'; return
    fi
  fi
  if command -v networkctl >/dev/null 2>&1; then
    json=$(dmb_run 8 networkctl --json=short status "$iface" 2>/dev/null) || json='{}'
    path=$(jq -r '.NetworkFile // .NetworkFilePath // empty' <<< "$json" 2>/dev/null) || path=''
    if [[ $path == /*.network ]]; then
      case $path in *netplan*|*cloud-init*) dmb_dns_error 'unsupported-owner: generated networkd configuration'; return 2;; esac
      [[ $path == "$etc/systemd/network/"* || $path == /usr/lib/systemd/network/* || $path == /lib/systemd/network/* ]] || { dmb_dns_error 'unsupported-owner: transient/unknown networkd file'; return 2; }
      jq -cn --arg file "$path" '{owner:"networkd",identity:$file}'; return
    fi
  fi
  if command -v resolvconf >/dev/null 2>&1 || [[ -d ${DMB_RUN_ROOT:-/run}/resolvconf ]]; then dmb_dns_error 'unsupported-owner: resolvconf requires its native adapter'; return 2; fi
  if [[ -f $etc/alpine-release && -f $etc/network/interfaces ]] && grep -Eq "^[[:space:]]*iface[[:space:]]+${iface}[[:space:]]+inet6?[[:space:]]+dhcp([[:space:]]|$)" "$etc/network/interfaces"; then
    if command -v dhcpcd >/dev/null 2>&1 && [[ -f $etc/dhcpcd.conf ]]; then
      # dhcpcd writes a shared resolver. Refuse multi-interface ambiguity.
      backend=$(dmb_run 5 ip -j link show | jq '[.[]|select(.ifname!="lo" and (.flags|index("UP")))]|length') || return
      [[ $backend == 1 ]] || { dmb_dns_error 'unsupported-owner: shared dhcpcd resolver on multiple active links'; return 2; }
      jq -cn --arg file "$etc/dhcpcd.conf" '{owner:"dhcpcd",identity:$file}'; return
    fi
    dmb_dns_error 'unsupported-owner: udhcpc or unknown Alpine DHCP hook'; return 2
  fi
  # A running unknown manager is a conflict even when its control socket is
  # unavailable. Do not infer static ownership from an unavailable dependency.
  for process in /proc/[0-9]*/comm;do
    [[ -r $process ]] || continue
    IFS= read -r comm < "$process" || continue
    case $comm in NetworkManager|systemd-network|dhclient|dhcpcd|udhcpc|connmand|wickedd*) dmb_dns_error 'unsupported-owner: active manager could not be identified for this resolver';return 2;;esac
  done
  if [[ -f $etc/resolv.conf && ! -L $etc/resolv.conf ]]; then
    # A regular file alone does not prove ownership: known generators reject.
    if command -v dhclient >/dev/null 2>&1 || command -v dhcpcd >/dev/null 2>&1 || compgen -G "$etc/netplan/*.yaml" >/dev/null || [[ -s ${DMB_RUN_ROOT:-/run}/cloud-init/network-config.json ]]; then dmb_dns_error 'unsupported-owner: generated resolver'; return 2; fi
    if grep -Eiq 'generated|managed by|do not edit' "$etc/resolv.conf"; then dmb_dns_error 'unsupported-owner: resolver declares external ownership'; return 2; fi
    if [[ $mode != candidate ]]; then
      manifest="$DMB_STATE_DIR/enrollments/dns-$iface.json"
      dmb_trusted_path "$manifest" || { dmb_dns_error 'static resolver requires explicit local DNS enrollment';return 2; }
      jq -e --arg iface "$iface" --arg path "$etc/resolv.conf" '.schema==1 and .iface==$iface and .owner=="static" and .identity==$path' "$manifest" >/dev/null || return 2
    fi
    jq -cn --arg file "$etc/resolv.conf" '{owner:"static",identity:$file}'; return
  fi
  dmb_dns_error 'unsupported-owner: resolver symlink or unidentified manager'
}
dmb_dns_content() {
  local path=$1 owner=$2 iface=$3 servers=$4 existing=''
  [[ ! -e $path ]] || existing=$(cat -- "$path")
  case $owner in
    static)
      # Preserve search/domain/options and all non-nameserver lines.
      printf '%s\n' "$existing" | sed '/^[[:space:]]*nameserver[[:space:]]/d'
      jq -r '.[]|"nameserver "+.' <<< "$servers" ;;
    networkd)
      printf '[Network]\nDNS=\n'; jq -r '.[]|"DNS="+.' <<< "$servers"
      printf '\n[DHCPv4]\nUseDNS=no\n[DHCPv6]\nUseDNS=no\n[IPv6AcceptRA]\nUseDNS=no\n' ;;
    dhcpcd)
      printf '%s\n' "$existing" | sed "/^# BEGIN dmitbox DNS $iface$/,/^# END dmitbox DNS $iface$/d"
      printf '# BEGIN dmitbox DNS %s\ninterface %s\nstatic domain_name_servers=%s\n# END dmitbox DNS %s\n' "$iface" "$iface" "$(jq -r 'join(" ")' <<< "$servers")" "$iface" ;;
    *) return 2;;
  esac
}
# Each step changes exactly one independently observable resource. Profile
# persistence and runtime overrides are never conflated by a broad reapply.
dmb_dns_step() { jq -ce --argjson i "$2" '.steps[$i]' "$1"; }
dmb_dns_owner_check() {
  local step=$1 actual iface
  iface=$(jq -er .iface <<< "$step") || return
  actual=$(dmb_dns_owner "$iface") || return
  [[ $(jq -Sc '{owner,identity}' <<< "$actual") == "$(jq -Sc '{owner,identity}' <<< "$step")" ]] || { dmb_dns_error 'configuration owner changed';return 2; }
}
dmb_dns_nm_capture() {
  local step iface identity dns4 dns6 auto4 auto6
  step=$(dmb_dns_step "$1" "$2") || return;dmb_dns_owner_check "$step" || return
  iface=$(jq -r .iface <<< "$step");identity=$(jq -r .identity <<< "$step")
  dns4=$(dmb_run 8 nmcli -g ipv4.dns connection show uuid "$identity" | dmb_dns_nm_list) || return
  dns6=$(dmb_run 8 nmcli -g ipv6.dns connection show uuid "$identity" | dmb_dns_nm_list) || return
  dmb_dns_numeric_list "$dns4" 4 && dmb_dns_numeric_list "$dns6" 6 || return
  auto4=$(dmb_run 8 nmcli -g ipv4.ignore-auto-dns connection show uuid "$identity") || return
  auto6=$(dmb_run 8 nmcli -g ipv6.ignore-auto-dns connection show uuid "$identity") || return
  [[ $auto4 == yes || $auto4 == no ]] && [[ $auto6 == yes || $auto6 == no ]] || return 2
  jq -cnS --arg identity "$identity" --argjson dns4 "$dns4" --argjson dns6 "$dns6" --arg auto4 "$auto4" --arg auto6 "$auto6" '{identity:$identity,dns4:$dns4,dns6:$dns6,auto4:$auto4,auto6:$auto6}'
}
dmb_dns_nm_set() {
  local step state identity
  step=$(dmb_dns_step "$1" "$2") || return;dmb_dns_owner_check "$step" || return
  state=$(jq -ce --arg key "$3" '.[$key]' <<< "$step") || return;identity=$(jq -r .identity <<< "$step")
  dmb_dns_numeric_list "$(jq -ce .dns4 <<< "$state")" 4 && dmb_dns_numeric_list "$(jq -ce .dns6 <<< "$state")" 6 || return
  jq -e '(.auto4=="yes" or .auto4=="no") and (.auto6=="yes" or .auto6=="no")' <<< "$state" >/dev/null || return 69
  # nmcli modifies only these four persistent properties. Never device reapply:
  # it could activate unrelated edits staged by another administrator.
  dmb_run 15 nmcli connection modify uuid "$identity" ipv4.dns "$(jq -r '.dns4|join(",")' <<< "$state")" ipv6.dns "$(jq -r '.dns6|join(",")' <<< "$state")" ipv4.ignore-auto-dns "$(jq -r .auto4 <<< "$state")" ipv6.ignore-auto-dns "$(jq -r .auto6 <<< "$state")"
}
dmb_dns_nm_apply() { dmb_dns_nm_set "$1" "$2" after; }
dmb_dns_nm_restore() { dmb_dns_nm_set "$1" "$2" before; }
dmb_dns_nm_verify() { dmb_dns_state_equal dns_nm "$1" "$2" after; }
dmb_dns_nm_verify_restore() { dmb_dns_state_equal dns_nm "$1" "$2" before; }
dmb_dns_resolved_policy() {
  local iface=$1 kind value domains=''
  for kind in domain default-route dnssec dnsovertls; do
    value=$(dmb_run 8 resolvectl "$kind" "$iface") || return
    domains+="$kind=$value"$'\n'
  done
  printf '%s' "$domains" | sha256sum | awk '{print $1}'
}
dmb_dns_resolved_capture() {
  local step iface identity dns policy link
  step=$(dmb_dns_step "$1" "$2") || return;dmb_dns_owner_check "$step" || return
  iface=$(jq -r .iface <<< "$step");identity=$(jq -r .identity <<< "$step")
  link=$(dmb_run 5 ip -j link show dev "$iface" | jq -ce '.[0]|{ifindex,ifname,address}') || return
  dns=$(dmb_dns_resolved_get "$iface") || return
  policy=$(dmb_dns_resolved_policy "$iface") || return
  jq -cnS --arg identity "$identity" --argjson link "$link" --argjson dns "$dns" --arg policy "$policy" '{identity:$identity,link:$link,dns:$dns,other_policy_sha256:$policy}'
}
dmb_dns_resolved_set() {
  local step iface state
  step=$(dmb_dns_step "$1" "$2") || return;dmb_dns_owner_check "$step" || return
  iface=$(jq -r .iface <<< "$step");state=$(jq -ce --arg key "$3" '.[$key]' <<< "$step") || return
  dmb_dns_numeric_list "$(jq -ce .dns <<< "$state")" || return
  local -a values=()
  mapfile -t values < <(jq -r '.dns[]' <<< "$state")
  if ((${#values[@]})); then dmb_run 10 resolvectl dns "$iface" "${values[@]}"
  else dmb_run 10 resolvectl dns "$iface" ''; fi
}
dmb_dns_resolved_apply() { dmb_dns_resolved_set "$1" "$2" after; }
dmb_dns_resolved_restore() { dmb_dns_resolved_set "$1" "$2" before; }
dmb_dns_resolved_verify() { dmb_dns_state_equal dns_resolved "$1" "$2" after; }
dmb_dns_resolved_verify_restore() { dmb_dns_state_equal dns_resolved "$1" "$2" before; }
dmb_dns_state_equal() {
  local adapter=$1 plan=$2 index=$3 key=$4 actual expected
  actual=$("dmb_${adapter}_capture" "$plan" "$index" | jq -ceS .) || return
  expected=$(jq -ceS --argjson i "$index" --arg key "$key" '.steps[$i][$key]' "$plan") || return
  [[ $actual == "$expected" ]]
}
dmb_dns_file_capture() {
  local step path state
  step=$(dmb_dns_step "$1" "$2") || return;dmb_dns_owner_check "$step" || return
  path=$(dmb_dns_file_path "$1" "$2") || return
  state=$(dmb_file_state "$path") || return
  jq -cnS --argjson state "$state" '{file:$state}'
}
dmb_dns_file_path() {
  local step path owner identity expected
  step=$(dmb_dns_step "$1" "$2") || return
  owner=$(jq -er .owner <<< "$step") || return
  identity=$(jq -er .identity <<< "$step") || return
  path=$(jq -er .file <<< "$step") || return
  case $owner in
    static) expected=$identity; [[ $expected == "$(dmb_dns_etc)/resolv.conf" ]] || return 78;;
    networkd)
      [[ $identity == /*.network && $identity != *'/../'* ]] || return 78
      expected="$(dmb_dns_etc)/systemd/network/$(basename "$identity").d/90-dmitbox-dns.conf"
      [[ -f $expected && ! -L $expected ]] && grep -qx '# Managed by dmitbox-local DNS' "$expected" || return 78;;
    *) return 78;;
  esac
  [[ $path == "$expected" ]] || { dmb_dns_error 'file target is outside the enrolled DNS owner'; return 78; }
  dmb_trusted_path "$path" || return
  printf '%s\n' "$path"
}
dmb_dns_file_snapshot() {
  local path
  path=$(dmb_dns_file_path "$1" "$2") || return
  dmb_file_capture "$path" "$3/snapshots" "dns-$2"
}
dmb_dns_file_apply() {
  local path mode content expected
  path=$(dmb_dns_file_path "$1" "$2") || return
  mode=$(stat -c '%a' -- "$path") || return
  content=$(jq -er --argjson i "$2" '.steps[$i].content_b64' "$1") || return
  expected=$(jq -er --argjson i "$2" '.steps[$i].after.file.sha256' "$1") || return
  printf '%s' "$content" | base64 -d | dmb_atomic_write "$path" "$mode" "$expected" "$(jq -c --argjson i "$2" '.steps[$i].after.file' "$1")"
}
dmb_dns_file_restore() {
  local path hash
  path=$(dmb_dns_file_path "$1" "$2") || return
  hash=$(jq -cS --argjson i "$2" '.steps[$i].after.file' "$1" | sha256sum | awk '{print $1}') || return
  dmb_file_restore "$path" "$3/snapshots" "dns-$2" "$hash"
}
dmb_dns_file_verify() { dmb_dns_state_equal dns_file "$1" "$2" after; }
dmb_dns_file_verify_restore() { dmb_dns_state_equal dns_file "$1" "$2" before; }
dmb_dns_append_step() {
  local plan=$1 step=$2 before after adapter file content
  adapter=$(jq -er .adapter <<< "$step") || return
  plan=$(jq -c --argjson step "$step" '.steps=[$step]' <<< "$plan") || return
  before=$("dmb_${adapter}_capture" <(printf '%s\n' "$plan") 0) || return
  case $adapter in
    dns_nm) after=$(jq -c --argjson servers "$(jq -c .servers <<< "$step")" '.dns4=[$servers[]|select(contains(":")|not)]|.dns6=[$servers[]|select(contains(":"))]|.auto4="yes"|.auto6="yes"' <<< "$before") || return;;
    dns_resolved) after=$(jq -c --argjson servers "$(jq -c .servers <<< "$step")" '.dns=$servers' <<< "$before") || return;;
    dns_file)
      content=$(jq -er .content_b64 <<< "$step") || return
      after=$(jq -c --arg hash "$(printf '%s' "$content" | base64 -d | sha256sum | awk '{print $1}')" '.file.sha256=$hash' <<< "$before") || return;;
    *) return 2;;
  esac
  jq -c --argjson before "$before" --argjson after "$after" '.before=$before|.after=$after' <<< "$step"
}
dmb_dns_plan() {
  local iface=${1:-} provider=${2:-} scope=${3:-persistent} raw servers owner identity base step steps='[]' file content
  local -a dmb_dns_provider_values=()
  shift 3 || return 2
  dmb_need jq ip sha256sum stat base64 || return
  [[ $scope == persistent || $scope == runtime ]] || return 2
  if [[ $provider == custom ]]; then raw=$(dmb_dns_servers "$@") || return
  else (($#==0)) || return 2;raw=$(dmb_dns_provider "$provider") || return;mapfile -t dmb_dns_provider_values <<< "$raw";raw=$(dmb_dns_servers "${dmb_dns_provider_values[@]}") || return;fi
  servers=$(dmb_dns_lines_json <<< "$raw") || return
  owner=$(dmb_dns_owner "$iface") || return;identity=$(jq -r .identity <<< "$owner");owner=$(jq -r .owner <<< "$owner")
  base=$(jq -cn --arg iface "$iface" '{schema:1,adapter:"dns",resources:["dns:"+$iface],steps:[]}') || return
  if [[ $scope == persistent && $owner == nm ]]; then
    step=$(jq -cn --arg iface "$iface" --arg identity "$identity" --argjson servers "$servers" '{id:"dns-profile",adapter:"dns_nm",resource:("dns:"+$iface+":profile"),iface:$iface,owner:"nm",identity:$identity,servers:$servers}') || return
    step=$(dmb_dns_append_step "$base" "$step") || return;steps=$(jq -c --argjson step "$step" '.+[$step]' <<< "$steps") || return
  elif [[ $scope == persistent && $owner == static ]]; then
    file=$identity
    content=$(dmb_dns_content "$file" static "$iface" "$servers" | base64 -w0) || return
    step=$(jq -cn --arg iface "$iface" --arg identity "$identity" --arg file "$file" --arg content "$content" '{id:"dns-file",adapter:"dns_file",resource:("dns:"+$iface+":file"),iface:$iface,owner:"static",identity:$identity,file:$file,content_b64:$content}') || return
    step=$(dmb_dns_append_step "$base" "$step") || return;steps=$(jq -c --argjson step "$step" '.+[$step]' <<< "$steps") || return
    jq -c --argjson steps "$steps" '.steps=$steps|.resources=((.resources+[$steps[].resource])|unique)|.notes=["Persistent static resolver change. DNS search/domain/options preserved. No resolution probe has been run."]' <<< "$base";return
  elif [[ $scope == persistent && $owner == networkd ]]; then
    # Only an explicitly created DMITBox dropin is adopted. The tool does not
    # take ownership of a vendor or administrator .network file implicitly.
    file="$(dmb_dns_etc)/systemd/network/$(basename "$identity").d/90-dmitbox-dns.conf"
    [[ -f $file && ! -L $file ]] && grep -qx '# Managed by dmitbox-local DNS' "$file" || { dmb_dns_error 'create/enroll a DMITBox-owned networkd DNS dropin before persistent use';return 2; }
    content=$({ printf '# Managed by dmitbox-local DNS\n';dmb_dns_content "$file" networkd "$iface" "$servers"; } | base64 -w0) || return
    step=$(jq -cn --arg iface "$iface" --arg identity "$identity" --arg file "$file" --arg content "$content" '{id:"dns-file",adapter:"dns_file",resource:("dns:"+$iface+":file"),iface:$iface,owner:"networkd",identity:$identity,file:$file,content_b64:$content}') || return
    step=$(dmb_dns_append_step "$base" "$step") || return;steps=$(jq -c --argjson step "$step" '.+[$step]' <<< "$steps") || return
  elif [[ $scope == persistent ]]; then
    dmb_dns_error 'persistent DHCP DNS requires a tested native lease/configuration adapter; shared resolver is not overwritten';return 2
  fi
  [[ $owner == nm || $owner == networkd ]] || { dmb_dns_error 'runtime override requires an authoritative managed resolved link';return 2; }
  dmb_need resolvectl || return
  dmb_run 8 resolvectl status "$iface" >/dev/null || return
  # DNS-over-TLS strict mode can depend on authenticated server names. Plain
  # numeric replacements cannot preserve that contract across all NM versions.
  local tls_policy
  tls_policy=$(dmb_run 8 resolvectl dnsovertls "$iface") || return
  if [[ $tls_policy =~ :[[:space:]]+yes[[:space:]]*$ ]];then
    dmb_dns_error 'strict DoT server-name enrollment is required; numeric DNS replacement is refused rather than weakening TLS policy';return 2
  fi
  step=$(jq -cn --arg iface "$iface" --arg owner "$owner" --arg identity "$identity" --argjson servers "$servers" '{id:"dns-runtime",adapter:"dns_resolved",resource:("dns:"+$iface+":runtime"),iface:$iface,owner:$owner,identity:$identity,servers:$servers}') || return
  step=$(dmb_dns_append_step "$base" "$step") || return;steps=$(jq -c --argjson step "$step" '.+[$step]' <<< "$steps") || return
  jq -c --argjson steps "$steps" '.steps=$steps|.resources=((.resources+[$steps[].resource])|unique)|.notes=["DNS-only per-link override; search/routing domains, DNSSEC, DoT and default-route policy are preserved. Persistence is applied on the next native connection activation/reboot; no broad reapply or networkctl reload is issued. Resolution probes require an explicit command."]' <<< "$base"
}
dmb_dns_probe() {
  local name=${1:-} server=${2:-} type=${3:-A} result rc status answers verdict
  [[ $name =~ ^[A-Za-z0-9]([A-Za-z0-9.-]{0,251}[A-Za-z0-9])?$ && $name != *..* ]] || return 2
  [[ $type == A || $type == AAAA ]] || return 2
  [[ -z $server ]] || server=$(dmb_ip_parse "$server") || return 2
  dmb_need dig || return
  local -a args=(-r +time=4 +tries=1 +noall +comments +answer)
  [[ -z $server ]] || args+=("@$server")
  # Explicitly requested DNS query. -r ignores a user's .digrc; a blocked
  # response/timeout is distinguished from a received DNS error response.
  result=$(dmb_run 12 dig "${args[@]}" "$name" "$type");rc=$?
  status=$(sed -nE 's/.*status: ([A-Z0-9]+),.*/\1/p' <<< "$result")
  [[ $status != *$'\n'* ]] || return 3
  answers=$(awk '!/^;/ && NF>0 {print}' <<< "$result")
  case $status in
    NOERROR) if [[ -n $answers ]];then verdict=resolved;rc=0;else verdict=no-data;rc=1;fi;;
    NXDOMAIN) verdict=negative-answer;rc=1;;
    SERVFAIL|REFUSED|FORMERR|NOTIMP) verdict="dns-error-response";rc=1;;
    *) status=UNOBSERVED;verdict=inconclusive;rc=3;;
  esac
  jq -cn --arg name "$name" --arg server "$server" --arg type "$type" --arg status "$status" --arg verdict "$verdict" --arg answers "$answers" '{schema:1,name:$name,server:(if $server=="" then "system resolver" else $server end),query_type:$type,dns_status:$status,verdict:$verdict,answers:$answers,scope:"Explicit probe only; this does not prove application resolution or external SSH accessibility"}'
  return "$rc"
}
dmb_dns_enroll() {
  local iface=${1:-} owner identity state='null'
  dmb_dns_iface_valid "$iface" || return 2
  owner=$(dmb_dns_owner "$iface" candidate) || return
  identity=$(jq -er .identity <<< "$owner") || return
  if [[ $(jq -r .owner <<< "$owner") == static ]];then state=$(dmb_file_state "$identity") || return;fi
  jq -cnS --arg iface "$iface" --argjson owner "$owner" --argjson state "$state" '$owner+{schema:1,iface:$iface,enrolled_initial_state:$state,scope:"DNS fields only; no implied ownership of routes, search domains or resolver security policy"}'
}
dmb_dns_restore_plan() {
  local iface=${1:-} root tx match='' candidate state count=0 plan step actual after old newsteps='[]' i adapter content
  dmb_dns_iface_valid "$iface" || return 2
  root=$(dmb_state_root) || return
  # No timestamp ordering: clock changes must not select a historical owner.
  # Require exactly one still-current committed transaction for this interface.
  for tx in "$root/transactions/"tx-*;do
    [[ -d $tx && ! -L $tx && -f $tx/state.json && -f $tx/plan.json ]] || continue
    dmb_trusted_path "$tx" || return
    state=$(jq -r '.state' "$tx/state.json") || return
    [[ $state == COMMITTED ]] || continue
    jq -e --arg iface "$iface" '.steps|any(.[]; .iface==$iface and (.adapter=="dns_nm" or .adapter=="dns_resolved" or .adapter=="dns_file"))' "$tx/plan.json" >/dev/null || continue
    plan=$(cat "$tx/plan.json") || return
    candidate=true
    while read -r i;do
      adapter=$(jq -r --argjson i "$i" '.steps[$i].adapter' <<< "$plan") || return
      actual=$("dmb_${adapter}_capture" "$tx/plan.json" "$i" | jq -cS .) || { candidate=false;break; }
      after=$(jq -cS --argjson i "$i" '.steps[$i].after' <<< "$plan") || return
      [[ $actual == "$after" ]] || { candidate=false;break; }
    done < <(jq -r --arg iface "$iface" '.steps|to_entries[]|select(.value.iface==$iface)|.key' <<< "$plan")
    [[ $candidate == true ]] || continue
    count=$((count+1));match=$tx
  done
  ((count==1)) || { dmb_dns_error 'restore requires exactly one committed DNS transaction whose owned state is still current; select an explicit historical transaction after review';return 2; }
  plan=$(cat "$match/plan.json") || return
  while read -r i;do
    step=$(jq -ce --argjson i "$i" '.steps[$i]' <<< "$plan") || return
    adapter=$(jq -er .adapter <<< "$step") || return
    old=$(jq -c .before <<< "$step") || return
    if [[ $adapter == dns_file ]];then
      [[ -f $match/snapshots/dns-$i.raw && ! -L $match/snapshots/dns-$i.raw ]] || return 2
      # Validate raw metadata, not just its bytes, before constructing inverse.
      [[ $(dmb_file_state "$match/snapshots/dns-$i.raw" | jq -cS .) == "$(jq -cS .file <<< "$old")" ]] || return 2
      content=$(base64 -w0 "$match/snapshots/dns-$i.raw") || return
      step=$(jq -c --arg content "$content" '.content_b64=$content' <<< "$step") || return
    fi
    step=$(jq -c --argjson old "$old" '.id=("restore-"+.id)|.before=.after|.after=$old' <<< "$step") || return
    newsteps=$(jq -c --argjson step "$step" '.+[$step]' <<< "$newsteps") || return
  done < <(jq -r --arg iface "$iface" '.steps|to_entries|reverse[]|select(.value.iface==$iface)|.key' <<< "$plan")
  jq -cn --arg iface "$iface" --arg source "${match##*/}" --argjson steps "$newsteps" '{schema:1,adapter:"dns",resources:((["dns:"+$iface]+[$steps[].resource])|unique),steps:$steps,restores_transaction:$source}'
}
# END MODULE adapters/dns.sh

# BEGIN MODULE adapters/routing.sh
# Local routing inventory and narrowly scoped runtime link mutations.
# No route is selected using an unsolicited public probe.
dmb_route_error() { printf 'routing: %s\n' "$*" >&2; return 2; }
dmb_route_iface_valid() { [[ ${1:-} =~ ^[[:alnum:]_.:-]{1,15}$ && $1 != -* ]]; }
dmb_route_link() {
  dmb_route_iface_valid "$1" || return 2
  dmb_run 5 ip -j -d link show dev "$1" | jq -ce 'if length==1 then .[0] else error("ambiguous interface") end'
}
dmb_route_report() {
  local context=${1:-'{}'} links addresses r4 r6 u4 u6
  jq -e 'type=="object"' <<< "$context" >/dev/null || return 2
  dmb_need ip jq || return
  links=$(dmb_run 8 ip -j -d link show) || return
  addresses=$(dmb_run 8 ip -j address show) || return
  r4=$(dmb_run 8 ip -j -4 route show table all) || return
  r6=$(dmb_run 8 ip -j -6 route show table all) || return
  u4=$(dmb_run 8 ip -j -4 rule show) || return
  u6=$(dmb_run 8 ip -j -6 rule show) || return
  jq -cn --argjson links "$links" --argjson addresses "$addresses" --argjson r4 "$r4" --argjson r6 "$r6" --argjson u4 "$u4" --argjson u6 "$u6" --argjson context "$context" '{schema:1,context:$context,links:$links,addresses:$addresses,routes:{ipv4:$r4,ipv6:$r6},rules:{ipv4:$u4,ipv6:$u6},network_probes:false}'
}
dmb_route_context_valid() {
  local context=$1 value family
  jq -e 'type=="object" and ((keys - ["family","source","peer","table","vrf","mark","encapsulation_overhead","underlay_mtu"])|length==0) and ((.family//4)==4 or .family==6) and ((.table//254)|type=="number" and floor==. and .>=1 and .<=4294967295) and ((.mark//0)|type=="number" and floor==. and .>=0 and .<=4294967295) and ((.encapsulation_overhead//0)|type=="number" and floor==. and .>=0 and .<=65535) and (.underlay_mtu==null or (.underlay_mtu|type=="number" and floor==. and .>=68 and .<=65535))' <<< "$context" >/dev/null || return 2
  family=$(jq -r '.family//4' <<< "$context")
  for value in source peer; do
    value=$(jq -r --arg key "$value" '.[$key]//empty' <<< "$context")
    [[ -z $value ]] || dmb_ip_parse "$value" "$family" >/dev/null || return 2
  done
  value=$(jq -r '.vrf//empty' <<< "$context")
  [[ -z $value ]] || dmb_route_iface_valid "$value"
}
dmb_mtu_capture() {
  local plan=$1 index=$2 iface link enabled ns
  iface=$(jq -er --argjson i "$index" '.steps[$i].iface' "$plan") || return
  link=$(dmb_route_link "$iface") || return
  enabled=$(cat "/proc/sys/net/ipv6/conf/$iface/disable_ipv6" 2>/dev/null) || enabled=1
  ns=$(stat -Lc '%i' /proc/self/ns/net) || return
  jq -cS --arg ns "$ns" --arg disabled "$enabled" '{ifindex,ifname,mtu,address,kind:(.linkinfo.info_kind//"ether"),master:(.master//null),link_index:(.link_index//null),netns_inode:$ns,ipv6_disabled:$disabled}' <<< "$link"
}
dmb_mtu_plan() {
  local iface=${1:-} mtu=${2:-} scope=${3:-runtime} context=${4:-'{}'} before after plan kind overhead max enabled underlay parent_index parent_mtu
  dmb_need jq ip stat || return
  dmb_route_iface_valid "$iface" && [[ $mtu =~ ^[0-9]{2,5}$ ]] && ((10#$mtu>=68 && 10#$mtu<=65535)) || return 2
  [[ $scope == runtime ]] || { dmb_route_error 'persistent MTU requires a dedicated configuration-owner adapter';return 2; }
  dmb_route_context_valid "$context" || return 2
  plan=$(jq -cn --arg iface "$iface" --argjson mtu "$((10#$mtu))" --argjson context "$context" '{schema:1,adapter:"mtu",resources:["link:"+$iface],steps:[{id:"mtu",resource:("link:"+$iface),iface:$iface,mtu:$mtu,context:$context,after:{}}]}') || return
  before=$(dmb_mtu_capture <(printf '%s\n' "$plan") 0) || return
  kind=$(jq -r .kind <<< "$before");enabled=$(jq -r .ipv6_disabled <<< "$before")
  [[ $enabled == 1 ]] || ((10#$mtu>=1280)) || { dmb_route_error 'IPv6 enabled: MTU must be at least 1280';return 2; }
  # Unknown tunnel layering is not guessed from a single route.
  case $kind in ether|veth|bridge|bond|dummy) ;;
    *) overhead=$(jq -r '.encapsulation_overhead//0' <<< "$context");((overhead>0)) || { dmb_route_error 'explicit encapsulation_overhead required for this link kind';return 2; };;
  esac
  max=$(dmb_route_link "$iface" | jq -r 'if (.max_mtu//0)>0 then .max_mtu else 65535 end') || return
  overhead=$(jq -r '.encapsulation_overhead//0' <<< "$context") || return
  if ((overhead>0));then
    underlay=$(jq -r '.underlay_mtu//0' <<< "$context") || return
    parent_index=$(jq -r '.link_index//0' <<< "$before") || return
    if ((parent_index>0)) && [[ $kind != veth ]];then
      parent_mtu=$(dmb_run 5 ip -j link show | jq -er --argjson i "$parent_index" '.[]|select(.ifindex==$i)|.mtu') || return
      ((underlay>0 && underlay<parent_mtu)) || underlay=$parent_mtu
    fi
    ((underlay>overhead)) || { dmb_route_error 'provide the verified underlay_mtu for this encapsulation';return 2; }
    ((max<underlay-overhead)) || max=$((underlay-overhead))
  fi
  ((10#$mtu<=max)) || { dmb_route_error 'MTU exceeds the device/underlay limit after encapsulation overhead';return 2; }
  after=$(jq -c --argjson mtu "$((10#$mtu))" '.mtu=$mtu' <<< "$before") || return
  jq -c --argjson before "$before" --argjson after "$after" '.steps[0].before=$before|.steps[0].after=$after|.notes=["Runtime MTU only. Local readback cannot establish end-to-end PMTU; request explicit PMTU probes and confirm through a new connection."]' <<< "$plan"
}
dmb_mtu_apply() {
  local iface mtu context checked expected
  iface=$(jq -er --argjson i "$2" '.steps[$i].iface' "$1") || return
  mtu=$(jq -er --argjson i "$2" '.steps[$i].after.mtu' "$1") || return
  dmb_route_iface_valid "$iface" && [[ $mtu =~ ^[0-9]+$ ]] || return 2
  context=$(jq -ce --argjson i "$2" '.steps[$i].context // {}' "$1") || return
  # The public plan file is untrusted input. Repeat the same capability and
  # IPv6/encapsulation checks immediately before the netlink mutation.
  checked=$(dmb_mtu_plan "$iface" "$mtu" runtime "$context") || return
  expected=$(jq -cS --argjson i "$2" '.steps[$i].after' "$1") || return
  [[ $(jq -cS '.steps[0].after' <<< "$checked") == "$expected" ]] || return 76
  dmb_run 10 ip link set dev "$iface" mtu "$mtu"
}
dmb_mtu_restore() {
  local iface mtu
  iface=$(jq -er --argjson i "$2" '.steps[$i].iface' "$1") || return
  mtu=$(jq -er --argjson i "$2" '.steps[$i].before.mtu' "$1") || return
  dmb_route_iface_valid "$iface" && [[ $mtu =~ ^[0-9]+$ ]] || return 2
  dmb_run 10 ip link set dev "$iface" mtu "$mtu"
}
dmb_mtu_verify() { [[ $(dmb_mtu_capture "$1" "$2" | jq -Sc .) == "$(jq -Sc --argjson i "$2" '.steps[$i].after' "$1")" ]]; }
dmb_mtu_verify_restore() { [[ $(dmb_mtu_capture "$1" "$2" | jq -Sc .) == "$(jq -Sc --argjson i "$2" '.steps[$i].before' "$1")" ]]; }
dmb_iface_plan() {
  dmb_route_error 'link up/down can trigger DHCP/RA, remove routes, or destroy an SSH return path; no tested owner-specific recovery adapter is available'
}
dmb_pmtu_probe() {
  local target=${1:-} family=${2:-4} iface=${3:-} canonical rc
  [[ $family == 4 || $family == 6 ]] || return 2
  canonical=$(dmb_ip_parse "$target" "$family") || return 2
  [[ -z $iface ]] || dmb_route_iface_valid "$iface" || return 2
  dmb_need tracepath || return
  # This is an explicitly requested network probe. An ICMP filtering timeout is
  # inconclusive and never modifies MTU or commits a transaction.
  local -a args=("-$family" -n)
  [[ -z $iface ]] || { dmb_route_error 'tracepath cannot reliably bind this interface; use an explicit namespace/VRF tool';return 2; }
  dmb_run 25 tracepath "${args[@]}" "$canonical"; rc=$?
  ((rc==0)) || printf 'PMTU probe inconclusive (blocked responses or probe failure), exit=%s\n' "$rc" >&2
  return "$rc"
}
# END MODULE adapters/routing.sh

# BEGIN MODULE adapters/ipv6.sh
# Static IPv6 primitives use separate address, route and sysctl steps. Dynamic
# DHCP/RA and unverified native configuration owners are refused before mutation.
dmb_ipv6_error() { printf 'ipv6: %s\n' "$*" >&2; return 2; }
dmb_ipv6_inventory() {
  local iface=${1:-} link addresses routes ipv6_values='{}' key value
  dmb_route_iface_valid "$iface" && [[ $iface != all && $iface != default && $iface != lo ]] || return 2
  link=$(dmb_route_link "$iface" | jq -c '{ifindex,ifname,address,kind:(.linkinfo.info_kind//"ether"),master:(.master//null)}') || return
  addresses=$(dmb_run 5 ip -j -6 address show dev "$iface" | jq -c '[.[].addr_info[]?|select(.family=="inet6")|del(.valid_life_time,.preferred_life_time)]') || return
  routes=$(dmb_run 5 ip -j -6 route show table all dev "$iface" | jq -c 'map(del(.expires,.lastuse,.used,.cache))|sort_by([(.table//254|tostring),.dst,(.metric//0)])') || return
  for key in disable_ipv6 autoconf accept_ra addr_gen_mode;do
    [[ -f /proc/sys/net/ipv6/conf/$iface/$key && ! -L /proc/sys/net/ipv6/conf/$iface/$key ]] || return 2
    IFS= read -r value < "/proc/sys/net/ipv6/conf/$iface/$key" || return
    [[ $value =~ ^[0-9]+$ ]] || return 2
    ipv6_values=$(jq -c --arg key "$key" --argjson value "$value" '.[$key]=$value' <<< "$ipv6_values") || return
  done
  jq -cnS --argjson link "$link" --argjson addresses "$addresses" --argjson routes "$routes" --argjson sysctl "$ipv6_values" '{link:$link,addresses:$addresses,routes:$routes,sysctl:$sysctl}'
}
dmb_ipv6_unmanaged() {
  local iface=$1 json file managed comm path
  dmb_route_iface_valid "$iface" && [[ $iface != all && $iface != default && $iface != lo ]] || return 2
  if command -v nmcli >/dev/null 2>&1;then
    managed=$(dmb_run 5 nmcli -g GENERAL.NM-MANAGED device show "$iface" 2>/dev/null) || return 2
    [[ $managed == no ]] || { dmb_ipv6_error 'NetworkManager owns or ambiguously manages this link';return 2; }
  fi
  if command -v networkctl >/dev/null 2>&1;then
    json=$(dmb_run 5 networkctl --json=short status "$iface" 2>/dev/null) || return 2
    file=$(jq -r '.NetworkFile//.NetworkFilePath//empty' <<< "$json") || return
    [[ -z $file ]] || { dmb_ipv6_error 'networkd owns this link';return 2; }
  fi
  if [[ -e /etc/network/interfaces ]] && grep -Eq "^[[:space:]]*iface[[:space:]]+${iface}[[:space:]]" /etc/network/interfaces;then
    dmb_ipv6_error 'ifupdown link requires its native recovery adapter';return 2
  fi
  # Unknown DHCP clients are not treated as static ownership. A client on a
  # different link may cause a conservative refusal; no interface is guessed.
  for path in /proc/[0-9]*/comm;do
    [[ -r $path ]] || continue
    IFS= read -r comm < "$path" || continue
    case $comm in dhclient|dhcpcd|udhcpc|odhcp6c|connmand|wickedd*) dmb_ipv6_error 'active DHCP/connection manager prevents unmanaged ownership proof';return 2;;esac
  done
}
dmb_ipv6_capture() {
  local iface
  iface=$(jq -er --argjson i "$2" '.steps[$i].iface' "$1") || return
  dmb_ipv6_unmanaged "$iface" || return
  dmb_ipv6_inventory "$iface"
}
dmb_ipv6_plan() {
  local mode=${1:-} context=${2:-'{}'} iface before after value selected
  [[ $mode == enable || $mode == disable ]] || return 2
  jq -e 'type=="object" and ((keys-["iface","transaction_id"]|length)==0) and (.iface|type=="string") and (.transaction_id==null or (.transaction_id|type=="string"))' <<< "$context" >/dev/null || { dmb_ipv6_error 'select one explicit interface with {"iface":"name"}; global/default-route selection is forbidden';return 2; }
  iface=$(jq -er .iface <<< "$context") || return
  dmb_ipv6_unmanaged "$iface" || return
  if [[ -f $DMB_STATE_DIR/enrollments/ipv6-$iface.json ]];then
    selected=$(jq -r '.transaction_id//empty' <<< "$context") || return
    if [[ $mode == enable && $(cat "/proc/sys/net/ipv6/conf/$iface/disable_ipv6") == 1 ]];then dmb_ipv6_static_restore_plan "$iface" "$selected";else dmb_ipv6_static_plan "$mode" "$iface";fi;return
  fi
  before=$(dmb_ipv6_inventory "$iface") || return
  # Disabling IPv6 destroys addresses/routes. Only an already-empty unmanaged
  # link with all automatic address mechanisms disabled has a bounded inverse.
  jq -e '.addresses==[] and .routes==[] and .sysctl.autoconf==0 and .sysctl.accept_ra==0 and .sysctl.addr_gen_mode==1' <<< "$before" >/dev/null || { dmb_ipv6_error 'addressed, routed, RA, DHCP or automatic link-local interfaces are unsupported; sysctl-only restoration would lose state';return 2; }
  [[ $mode == disable ]] && value=1 || value=0
  after=$(jq -c --argjson value "$value" '.sysctl.disable_ipv6=$value' <<< "$before") || return
  jq -cn --arg iface "$iface" --argjson before "$before" --argjson after "$after" '{schema:1,adapter:"ipv6",resources:["link:"+$iface,"ipv6:"+$iface],steps:[{id:"ipv6-toggle",resource:("ipv6:"+$iface),iface:$iface,before:$before,after:$after}],notes:["Only an empty explicitly selected unmanaged interface is supported. Addressed and dynamically configured interfaces are refused before mutation."]}'
}
dmb_ipv6_set() {
  local plan=$1 index=$2 key=$3 iface value expected current
  iface=$(jq -er --argjson i "$index" '.steps[$i].iface' "$plan") || return
  expected=$(jq -cS --argjson i "$index" --arg key "$key" 'if $key=="after" then .steps[$i].before else .steps[$i].after end' "$plan") || return
  current=$(dmb_ipv6_capture "$plan" "$index" | jq -cS .) || return
  [[ $current == "$expected" ]] || return 76
  value=$(jq -er --argjson i "$index" --arg key "$key" '.steps[$i][$key].sysctl.disable_ipv6' "$plan") || return
  [[ $value == 0 || $value == 1 ]] || return 2
  dmb_trusted_path "/proc/sys/net/ipv6/conf/$iface/disable_ipv6" || return
  printf '%s\n' "$value" > "/proc/sys/net/ipv6/conf/$iface/disable_ipv6"
}
dmb_ipv6_apply() { dmb_ipv6_set "$1" "$2" after; }
dmb_ipv6_restore() {
  local actual before
  actual=$(dmb_ipv6_capture "$1" "$2" | jq -cS .) || return
  before=$(jq -cS --argjson i "$2" '.steps[$i].before' "$1") || return
  [[ $actual != "$before" ]] || return 0
  dmb_ipv6_set "$1" "$2" before
}
dmb_ipv6_state_equal() {
  local actual expected
  actual=$(dmb_ipv6_capture "$1" "$2" | jq -cS .) || return
  expected=$(jq -cS --argjson i "$2" --arg key "$3" '.steps[$i][$key]' "$1") || return
  [[ $actual == "$expected" ]]
}
dmb_ipv6_verify() { dmb_ipv6_state_equal "$1" "$2" after; }
dmb_ipv6_verify_restore() { dmb_ipv6_state_equal "$1" "$2" before; }

# Granular static-address primitives. A pending transaction owns every affected
# address/route individually; an interrupted inverse retries only missing items.
dmb_ipv6_static_validate() {
  local state=$1
  jq -e '
    .sysctl.autoconf==0 and .sysctl.accept_ra==0 and
    .link.master==null and
    all(.addresses[]; .valid_life_time==4294967295 and .preferred_life_time==4294967295 and
      (.scope=="global" or .scope=="link") and
      ((keys-["family","local","prefixlen","scope","valid_life_time","preferred_life_time","flags","noprefixroute","protocol"]|length)==0) and
      ((.flags//[])|all(.=="permanent" or .=="noprefixroute")) and
      (.protocol==null or .protocol=="kernel_ll" or .protocol=="static")) and
    all(.routes[]; ((keys-["dst","dev","gateway","table","protocol","metric","flags","pref","type","prefsrc"]|length)==0) and
      ((.flags//[])|length==0) and (.pref//"medium")=="medium" and
      (if .protocol=="kernel" then
        ((.type=="local" and .table=="local" and .metric==0) or
         (.type=="multicast" and .dst=="ff00::/8" and .table=="local" and .metric==256) or
         (.type==null and .table==null and .metric==256 and .gateway==null))
       else (.protocol=="static" or .protocol=="boot") and (.type==null or .type=="unicast") end))
  ' <<< "$state" >/dev/null
}
dmb_ipv6_inventory_full() {
  local iface=$1 base addresses
  base=$(dmb_ipv6_inventory "$iface") || return
  addresses=$(dmb_run 5 ip -j -6 address show dev "$iface" | jq -c '[.[].addr_info[]?|select(.family=="inet6")]') || return
  jq -c --argjson addresses "$addresses" '.addresses=$addresses' <<< "$base"
}
dmb_ipv6_enroll() {
  local iface=${1:-} state boot
  dmb_ipv6_unmanaged "$iface" || return
  state=$(dmb_ipv6_inventory_full "$iface") || return
  dmb_ipv6_static_validate "$state" || { dmb_ipv6_error 'only forever static addresses, ordinary kernel-derived routes and simple static routes can be enrolled';return 2; }
  boot=$(cat /proc/sys/kernel/random/boot_id) || return
  jq -cnS --arg iface "$iface" --arg boot "$boot" --argjson state "$state" '{schema:1,iface:$iface,owner:"unmanaged-static",enrolled_boot_id:$boot,identity:$state.link,initial_state:$state}'
}
dmb_ipv6_enrollment() {
  local iface=$1 manifest link expected
  manifest="$DMB_STATE_DIR/enrollments/ipv6-$iface.json"
  dmb_trusted_path "$manifest" || return
  jq -e --arg iface "$iface" '.schema==1 and .iface==$iface and .owner=="unmanaged-static"' "$manifest" >/dev/null || return
  link=$(dmb_route_link "$iface" | jq -cS '{ifindex,ifname,address,kind:(.linkinfo.info_kind//"ether"),master:(.master//null)}') || return
  expected=$(jq -cS '.identity' "$manifest") || return
  [[ $link == "$expected" ]] || { dmb_ipv6_error 'enrolled interface identity changed';return 76; }
}
dmb_ipv6_static_capture() {
  local plan=$1 index=$2 step iface kind state value selector link
  step=$(jq -ce --argjson i "$index" '.steps[$i]' "$plan") || return
  iface=$(jq -er .iface <<< "$step");kind=$(jq -er .kind <<< "$step") || return
  dmb_ipv6_unmanaged "$iface" && dmb_ipv6_enrollment "$iface" || return
  state=$(dmb_ipv6_inventory_full "$iface") || return
  link=$(jq -c .link <<< "$state") || return
  case $kind in
    sysctl)
      selector=$(jq -er .key <<< "$step") || return
      case $selector in addr_gen_mode|disable_ipv6) ;;*)return 2;;esac
      value=$(jq -ce --arg key "$selector" '.sysctl[$key]' <<< "$state") || return;;
    address)
      selector=$(jq -ce .selector <<< "$step") || return
      value=$(jq -c --argjson s "$selector" '[.addresses[]|select(.local==$s.local and .prefixlen==$s.prefixlen)|del(.tentative,.dadfailed)]|if length<=1 then . else error("duplicate address") end' <<< "$state") || return;;
    route)
      selector=$(jq -ce .selector <<< "$step") || return
      value=$(jq -c --argjson s "$selector" '[.routes[]|select(.dst==$s.dst and (.table//254)==($s.table//254) and (.metric//0)==($s.metric//0))]|if length<=1 then . else error("ambiguous route selector") end' <<< "$state") || return;;
    *) return 2;;
  esac
  jq -cnS --argjson link "$link" --argjson value "$value" '{link:$link,value:$value}'
}
dmb_ipv6_static_ip_address() {
  local iface=$1 operation=$2 address=$3 localip prefix scope canonical flag
  localip=$(jq -er .local <<< "$address");prefix=$(jq -er .prefixlen <<< "$address");scope=$(jq -er .scope <<< "$address") || return
  canonical=$(dmb_ip_parse "$localip" 6) || return
  [[ $prefix =~ ^[0-9]{1,3}$ ]] && ((prefix<=128)) && [[ $scope == link || $scope == global ]] || return 2
  local -a args=(-6 address "$operation" "$canonical/$prefix" dev "$iface")
  if [[ $operation == add ]];then
    args+=(scope "$scope" valid_lft forever preferred_lft forever)
    flag=$(jq -r '.protocol//empty' <<< "$address");[[ -z $flag ]] || args+=(proto "$flag")
    if jq -e '.noprefixroute==true or ((.flags//[])|index("noprefixroute")!=null)' <<< "$address" >/dev/null;then args+=(noprefixroute);fi
  fi
  dmb_run 10 ip "${args[@]}"
}
dmb_ipv6_static_ip_route() {
  local iface=$1 operation=$2 route=$3 value key dst table
  dst=$(jq -er .dst <<< "$route") || return
  [[ $dst == default ]] || dmb_cidr_parse "$dst" 6 >/dev/null || return 2
  local -a args=(-6 route "$operation" "$dst")
  table=$(jq -r '.table//254' <<< "$route")
  [[ $table =~ ^[1-9][0-9]{0,9}$ || $table == main ]] || return 2
  args+=(table "$table")
  value=$(jq -r '.gateway//empty' <<< "$route")
  if [[ -n $value ]];then value=$(dmb_ip_parse "$value" 6) || return;args+=(via "$value");fi
  args+=(dev "$iface")
  for key in metric protocol prefsrc;do
    value=$(jq -r --arg key "$key" '.[$key]//empty' <<< "$route")
    [[ -n $value ]] || continue
    case $key in
      metric) [[ $value =~ ^[0-9]{1,10}$ ]] || return 2;args+=(metric "$value");;
      protocol) [[ $value == static || $value == boot ]] || return 2;args+=(proto "$value");;
      prefsrc) value=$(dmb_ip_parse "$value" 6) || return;args+=(src "$value");;
    esac
  done
  dmb_run 10 ip "${args[@]}"
}
dmb_ipv6_static_set() {
  local plan=$1 index=$2 target=$3 step iface kind current expected value opposite key item
  step=$(jq -ce --argjson i "$index" '.steps[$i]' "$plan") || return
  iface=$(jq -er .iface <<< "$step");kind=$(jq -er .kind <<< "$step") || return
  current=$(dmb_ipv6_static_capture "$plan" "$index" | jq -cS .) || return
  value=$(jq -ce --arg key "$target" '.[$key].value' <<< "$step") || return
  expected=$(jq -cS --arg key "$target" '.[$key]' <<< "$step") || return
  [[ $current != "$expected" ]] || return 0
  [[ $target == after ]] && opposite=before || opposite=after
  [[ $current == "$(jq -cS --arg key "$opposite" '.[$key]' <<< "$step")" ]] || return 76
  case $kind in
    sysctl)
      key=$(jq -er .key <<< "$step") || return
      case $key in addr_gen_mode) [[ $value =~ ^[0-3]$ ]] || return 2;;disable_ipv6) [[ $value == 0 || $value == 1 ]] || return 2;;*)return 2;;esac
      dmb_trusted_path "/proc/sys/net/ipv6/conf/$iface/$key" || return
      # disable_ipv6 is last after all addressed resources were withdrawn.
      if [[ $key == disable_ipv6 && $value == 1 ]];then
        dmb_ipv6_inventory_full "$iface" | jq -e '.addresses==[] and all(.routes[];.protocol=="kernel" and .type=="multicast")' >/dev/null || return 76
      fi
      printf '%s\n' "$value" > "/proc/sys/net/ipv6/conf/$iface/$key";;
    address)
      if [[ $value == '[]' ]];then
        item=$(jq -c --arg key "$opposite" '.[$key].value[0]' <<< "$step") || return
        dmb_ipv6_static_ip_address "$iface" del "$item"
      else
        item=$(jq -c '.[0]' <<< "$value") || return
        dmb_ipv6_static_ip_address "$iface" add "$item"
      fi;;
    route)
      if [[ $value == '[]' ]];then
        item=$(jq -c --arg key "$opposite" '.[$key].value[0]' <<< "$step") || return
        dmb_ipv6_static_ip_route "$iface" del "$item"
      else item=$(jq -c '.[0]' <<< "$value") || return;dmb_ipv6_static_ip_route "$iface" add "$item";fi;;
    *)return 2;;
  esac
}
dmb_ipv6_static_apply() { dmb_ipv6_static_set "$1" "$2" after && dmb_ipv6_static_equal "$1" "$2" after; }
dmb_ipv6_static_restore() { dmb_ipv6_static_set "$1" "$2" before && dmb_ipv6_static_equal "$1" "$2" before; }
dmb_ipv6_static_equal() {
  local actual expected kind iface i tries=0 target=$3
  expected=$(jq -cS --argjson i "$2" --arg key "$target" '.steps[$i][$key]' "$1") || return
  # DAD can take time. A DAD failure or unexpected generated state never counts
  # as restoration; no nodad bypass is applied.
  while ((tries<12));do
    actual=$(dmb_ipv6_static_capture "$1" "$2" | jq -cS .) || return
    [[ $actual != "$expected" ]] || break
    tries=$((tries+1));sleep 0.2
  done
  [[ $actual == "$expected" ]] || return 1
  kind=$(jq -r --argjson i "$2" '.steps[$i].kind' "$1") || return
  if [[ $kind == address && $(jq -c .value <<< "$expected") != '[]' ]];then
    iface=$(jq -r --argjson i "$2" '.steps[$i].iface' "$1") || return
    local selector observed tentative
    selector=$(jq -c --argjson i "$2" '.steps[$i].selector' "$1") || return
    tries=0
    while ((tries<12));do
      observed=$(dmb_ipv6_inventory_full "$iface" | jq -ce --argjson s "$selector" '.addresses[]|select(.local==$s.local and .prefixlen==$s.prefixlen)') || return
      jq -e '.dadfailed!=true' <<< "$observed" >/dev/null || return 1
      tentative=$(jq -r '.tentative//false' <<< "$observed") || return
      [[ $tentative == true ]] || break
      tries=$((tries+1));sleep 0.2
    done
    [[ $tentative != true ]] || return 1
  fi
  i=$(jq -r --argjson i "$2" '.steps[$i].id' "$1") || return
  if [[ $target == after && $i == restore-ipv6-autogen ]];then
    iface=$(jq -r --argjson i "$2" '.steps[$i].iface' "$1") || return
    actual=$(dmb_ipv6_inventory_full "$iface" | jq -cS .) || return
    expected=$(jq -cS '.restore_ipv6_state' "$1") || return
    [[ $actual == "$expected" ]] || return 1
  fi
  if [[ $target == before && $i == restore-ipv6-disable ]];then
    iface=$(jq -r --argjson i "$2" '.steps[$i].iface' "$1") || return
    actual=$(dmb_ipv6_inventory_full "$iface" | jq -cS .) || return
    expected=$(jq -cS '.initial_ipv6_state' "$1") || return
    [[ $actual == "$expected" ]] || return 1
  fi
  if [[ $target == before && $i == ipv6-autogen ]];then
    iface=$(jq -r --argjson i "$2" '.steps[$i].iface' "$1") || return
    actual=$(dmb_ipv6_inventory_full "$iface" | jq -cS .) || return
    expected=$(jq -cS '.initial_ipv6_state' "$1") || return
    [[ $actual == "$expected" ]] || return 1
  fi
}
dmb_ipv6_static_verify() { dmb_ipv6_static_equal "$1" "$2" after; }
dmb_ipv6_static_verify_restore() { dmb_ipv6_static_equal "$1" "$2" before; }
dmb_ipv6_static_step() {
  local iface=$1 id=$2 kind=$3 key=$4 value=$5 desired=$6 link=$7 selector=${8:-null}
  jq -cn --arg iface "$iface" --arg id "$id" --arg kind "$kind" --arg key "$key" --argjson before "$value" --argjson after "$desired" --argjson link "$link" --argjson selector "$selector" '{id:$id,adapter:"ipv6_static",resource:("ipv6:"+$iface+":"+$id),iface:$iface,kind:$kind,key:$key,selector:$selector,before:{link:$link,value:$before},after:{link:$link,value:$after}}'
}
dmb_ipv6_static_plan() {
  local mode=$1 iface=$2 state link steps='[]' step item id count=0 value
  dmb_ipv6_unmanaged "$iface" && dmb_ipv6_enrollment "$iface" || return
  state=$(dmb_ipv6_inventory_full "$iface") || return
  dmb_ipv6_static_validate "$state" || { dmb_ipv6_error 'static interface state changed to unsupported ownership, lifetime or route shape';return 2; }
  if [[ $mode == enable || $(jq -r .sysctl.disable_ipv6 <<< "$state") == 1 ]];then
    link=$(jq -c .link <<< "$state") || return
    value=$(jq -r .sysctl.disable_ipv6 <<< "$state") || return
    step=$(dmb_ipv6_static_step "$iface" ipv6-noop sysctl disable_ipv6 "$value" "$value" "$link") || return
    jq -cn --arg iface "$iface" --argjson step "$step" --argjson initial "$state" '{schema:1,adapter:"ipv6_static",operation:"ipv6-idempotent",resources:["link:"+$iface,"ipv6:"+$iface,$step.resource],steps:[$step],initial_ipv6_state:$initial}'
    return
  fi
  link=$(jq -c .link <<< "$state") || return
  value=$(jq -r .sysctl.addr_gen_mode <<< "$state") || return
  step=$(dmb_ipv6_static_step "$iface" ipv6-autogen sysctl addr_gen_mode "$value" 1 "$link") || return
  steps=$(jq -c --argjson step "$step" '.+[$step]' <<< "$steps") || return
  while IFS= read -r item;do
    count=$((count+1));id="route-$count"
    step=$(dmb_ipv6_static_step "$iface" "$id" route '' "[$item]" '[]' "$link" "$item") || return
    steps=$(jq -c --argjson step "$step" '.+[$step]' <<< "$steps") || return
  done < <(jq -c '.routes|reverse[]|select(.protocol!="kernel")' <<< "$state")
  while IFS= read -r item;do
    count=$((count+1));id="address-$count"
    step=$(dmb_ipv6_static_step "$iface" "$id" address '' "[$item]" '[]' "$link" "$item") || return
    steps=$(jq -c --argjson step "$step" '.+[$step]' <<< "$steps") || return
  done < <(jq -c '.addresses[]' <<< "$state")
  step=$(dmb_ipv6_static_step "$iface" ipv6-disable sysctl disable_ipv6 0 1 "$link") || return
  steps=$(jq -c --argjson step "$step" '.+[$step]' <<< "$steps") || return
  ((count<=55)) || { dmb_ipv6_error 'static interface has too many independently owned resources for one bounded transaction';return 2; }
  jq -cn --arg iface "$iface" --argjson steps "$steps" --argjson initial "$state" '{schema:1,adapter:"ipv6_static",operation:"ipv6-disable",resources:((["link:"+$iface,"ipv6:"+$iface]+[$steps[].resource])|unique),steps:$steps,initial_ipv6_state:$initial,notes:["Explicit enrolled unmanaged static addresses/routes. Automatic configuration is refused. Rollback waits for DAD and compares the full original inventory; reboot interface identity changes require conflict review."]}'
}
dmb_ipv6_static_restore_plan() {
  local iface=$1 selected=${2:-} root tx candidate match='' count=0 i current expected plan steps initial
  root=$(dmb_state_root) || return
  [[ -z $selected || $selected =~ ^tx-[a-f0-9]{32}$ ]] || return 2
  for tx in "$root/transactions/"tx-*;do
    [[ -z $selected || ${tx##*/} == "$selected" ]] || continue
    [[ -d $tx && ! -L $tx && -f $tx/plan.json && -f $tx/state.json ]] || continue
    dmb_trusted_path "$tx" || return
    jq -e '.state=="COMMITTED"' "$tx/state.json" >/dev/null || continue
    jq -e --arg iface "$iface" '.operation=="ipv6-disable" and all(.steps[];.iface==$iface and .adapter=="ipv6_static")' "$tx/plan.json" >/dev/null || continue
    candidate=true
    while IFS= read -r i;do
      current=$(dmb_ipv6_static_capture "$tx/plan.json" "$i" | jq -cS .) || { candidate=false;break; }
      expected=$(jq -cS --argjson i "$i" '.steps[$i].after' "$tx/plan.json") || return
      [[ $current == "$expected" ]] || { candidate=false;break; }
    done < <(jq -r '.steps|keys[]' "$tx/plan.json")
    [[ $candidate == true ]] || continue
    count=$((count+1));match=$tx
  done
  ((count==1)) || { dmb_ipv6_error 'enable requires one still-current committed static-disable snapshot; specify transaction_id when historical ownership is ambiguous';return 2; }
  plan=$(cat "$match/plan.json") || return
  initial=$(dmb_ipv6_inventory_full "$iface") || return
  steps=$(jq -c '.steps|reverse|map(. as $s|.id=("restore-"+.id)|.before=$s.after|.after=$s.before)' <<< "$plan") || return
  jq -c --argjson steps "$steps" --argjson initial "$initial" --arg tx "${match##*/}" '.steps=$steps|.operation="ipv6-enable"|.restore_ipv6_state=.initial_ipv6_state|.initial_ipv6_state=$initial|.restores_transaction=$tx' <<< "$plan"
}
# END MODULE adapters/ipv6.sh

# BEGIN MODULE adapters/pool.sh
# Explicitly enrolled, permanent /128 members of a routed IPv6 /64. Runtime
# addresses only: no network-manager configuration is guessed or overwritten.
# External evidence is provided by the administrator's pinned verifier program;
# its honesty and separate-host placement are part of the enrollment trust model.
dmb_pool_error() { dmb_error "pool: $*"; return 69; }
dmb_pool_global() {
  local canonical words; local -a address_words
  canonical=$(dmb_ip_parse "$1" 6) || return
  words=$(dmb_ipv6_words "$canonical") || return
  IFS=' ' read -r -a address_words <<< "$words"
  ((address_words[0]>=0x2000 && address_words[0]<=0x3fff)) || return 64
  # Documentation, benchmarking and ORCHID prefixes are not delegated pools.
  ! dmb_ip_in_cidr "$canonical" 2001:db8::/32 || return 64
  ! dmb_ip_in_cidr "$canonical" 2001:2::/48 || return 64
  ! dmb_ip_in_cidr "$canonical" 2001:10::/28 || return 64
  ! dmb_ip_in_cidr "$canonical" 2001:20::/28 || return 64
}
dmb_pool_id() { [[ ${1-} =~ ^[A-Za-z0-9][A-Za-z0-9_-]{0,47}$ ]]; }
dmb_pool_manifest_path() { dmb_pool_id "$1" || return 64; printf '%s/enrollments/pool-%s.json\n' "$DMB_STATE_DIR" "$1"; }
dmb_pool_verifier_valid() {
  local config=$1 path expected actual source prefix
  jq -e '.verifier|type=="object" and (.path|type=="string" and test("^/[A-Za-z0-9_./-]+$")) and (.sha256|test("^[a-f0-9]{64}$")) and (.identity|type=="string" and test("^[A-Za-z0-9_.:-]{1,100}$")) and (.args|type=="array" and length<=32 and all(.[];type=="string" and length<=1024 and (explode|all(.[];.>=32 and .!=127)))) and (.source_address|type=="string")' <<< "$config" >/dev/null || return 64
  path=$(jq -er .verifier.path <<< "$config") || return
  expected=$(jq -er .verifier.sha256 <<< "$config") || return
  dmb_trusted_path "$path" || return
  [[ -f $path && -x $path && ! -L $path && $(stat -c %h -- "$path") == 1 ]] || return 78
  actual=$(sha256sum -- "$path") || return
  [[ ${actual%% *} == "$expected" ]] || return 76
  source=$(jq -er .verifier.source_address <<< "$config") || return
  source=$(dmb_ip_parse "$source" 6) || return
  dmb_pool_global "$source" || return
  prefix=$(jq -er .prefix <<< "$config") || return
  ! dmb_ip_in_cidr "$source" "$prefix" || return 64
}
dmb_pool_enroll() {
  local config=$1 prefix iface anchor source link addresses routes
  dmb_need jq ip sha256sum stat || return
  jq -e '.schema==1 and .prefix_authorized==true and (.owner_id|test("^[a-f0-9]{32}$")) and (.iface|type=="string") and (.prefix|type=="string") and (.anchor|type=="string")' <<< "$config" >/dev/null || return 64
  dmb_pool_id "$(jq -er .id <<< "$config")" || return 64
  iface=$(jq -er .iface <<< "$config") || return
  dmb_route_iface_valid "$iface" && [[ $iface != lo ]] || return 64
  prefix=$(dmb_cidr_parse "$(jq -er .prefix <<< "$config")" 6) || return
  [[ $prefix == */64 ]] && dmb_pool_global "${prefix%/*}" || return 64
  anchor=$(dmb_ip_parse "$(jq -er .anchor <<< "$config")" 6) || return
  dmb_pool_global "$anchor" && dmb_ip_in_cidr "$anchor" "$prefix" || return 64
  config=$(jq -cS --arg prefix "$prefix" --arg anchor "$anchor" '.prefix=$prefix|.anchor=$anchor' <<< "$config") || return
  dmb_pool_verifier_valid "$config" || return
  source=$(dmb_ip_parse "$(jq -er .verifier.source_address <<< "$config")" 6) || return
  addresses=$(dmb_run 5 ip -j -6 address show) || return
  jq -e --arg source "$source" 'all(.[].addr_info[]?;.local!=$source)' <<< "$addresses" >/dev/null || { dmb_pool_error 'external verifier source must not be an address on this host'; return; }
  config=$(jq -cS --arg source "$source" '.verifier.source_address=$source' <<< "$config") || return
  dmb_ipv6_unmanaged "$iface" || return
  link=$(dmb_route_link "$iface" | jq -ce '{ifindex,ifname,address,master:(.master//null),kind:(.linkinfo.info_kind//"ether")}') || return
  jq -e '.kind=="ether" or .kind=="veth"' <<< "$link" >/dev/null || { dmb_pool_error 'only an explicitly unmanaged Ethernet/veth link is supported'; return; }
  addresses=$(dmb_run 5 ip -j -6 address show dev "$iface") || return
  jq -e --arg anchor "$anchor" 'any(.[].addr_info[]?;.local==$anchor and .prefixlen==64 and .scope=="global" and .valid_life_time==4294967295 and .preferred_life_time==4294967295 and (.tentative//false|not) and (.dadfailed//false|not) and (.dynamic//false|not) and (.temporary//false|not))' <<< "$addresses" >/dev/null || { dmb_pool_error 'anchor must be a preferred permanent /64 address'; return; }
  routes=$(dmb_run 5 ip -j -6 route show table all dev "$iface") || return
  # Link-local dynamic routes are irrelevant to prefix delegation; nonlocal
  # dynamic/default policy must remain stable throughout this narrow backend.
  jq -cS --argjson link "$link" --arg ns "$(stat -Lc %i /proc/self/ns/net)" --argjson routes "$routes" '.+{link:$link,netns_inode:$ns,routing_snapshot:($routes|map(del(.expires,.cache,.lastuse,.used)))}' <<< "$config"
}
dmb_pool_step() {
  local step address prefix iface
  step=$(jq -ce --argjson i "$2" '.steps[$i]|select(.adapter=="pool")' "$1") || return
  iface=$(jq -er .iface <<< "$step") || return
  dmb_route_iface_valid "$iface" || return 64
  address=$(dmb_ip_parse "$(jq -er .address <<< "$step")" 6) || return
  prefix=$(dmb_cidr_parse "$(jq -er .prefix <<< "$step")" 6) || return
  [[ $prefix == */64 ]] && dmb_pool_global "$address" && dmb_ip_in_cidr "$address" "$prefix" || return 64
  dmb_pool_id "$(jq -er .enrollment <<< "$step")" || return 64
  jq -e '(.enrollment_sha256|test("^[a-f0-9]{64}$")) and (.external_probes==true) and (.link.ifindex|type=="number") and (.netns_inode|type=="string")' <<< "$step" >/dev/null || return 64
  printf '%s\n' "$step"
}
dmb_pool_capture() {
  local step iface address link ns matches observed identity protocol
  step=$(dmb_pool_step "$1" "$2") || return
  iface=$(jq -er .iface <<< "$step"); address=$(jq -er .address <<< "$step")
  link=$(dmb_route_link "$iface" | jq -ce '{ifindex,ifname,address,master:(.master//null),kind:(.linkinfo.info_kind//"ether")}') || return
  ns=$(stat -Lc %i /proc/self/ns/net) || return
  identity=$(jq -cnS --argjson link "$link" --arg ns "$ns" '{link:$link,netns_inode:$ns}') || return
  matches=$(dmb_run 5 ip -N -j -6 address show dev "$iface" | jq -c --arg address "$address" '[.[].addr_info[]?|select(.local==$address)]') || return
  [[ $(jq length <<< "$matches") == 0 ]] && { jq -cS '.+{exists:false}' <<< "$identity"; return; }
  [[ $(jq length <<< "$matches") == 1 ]] || return 76
  # DAD flags are observed separately in verify. Keeping them outside logical
  # configuration permits rollback of a failed/tentative address after SIGKILL.
  protocol=$(jq -r '.[0].protocol//"unspecified"|tostring' <<< "$matches") || return
  if [[ $protocol =~ ^0x[0-9a-fA-F]{1,2}$ ]]; then protocol=$((protocol)); fi
  observed=$(jq -cS --arg protocol "$protocol" '.[0]|{address:.local,prefixlen,scope:(if (.scope|tostring)=="0" then "global" else .scope end),protocol:$protocol,noprefixroute:(.noprefixroute//false),permanent:(.valid_life_time==4294967295 and .preferred_life_time==4294967295)}' <<< "$matches") || return
  jq -cnS --argjson identity "$identity" --argjson observed "$observed" '$identity+$observed+{exists:true}'
}
dmb_pool_generate() {
  local prefix=$1 words iid address; local -a p r
  words=$(dmb_ipv6_words "${prefix%/*}") || return
  IFS=' ' read -r -a p <<< "$words"
  iid=$(od -An -N8 -tx2 /dev/urandom) || return
  IFS=' ' read -r -a r <<< "$iid"
  ((${#r[@]}==4)) || return 74
  # Avoid subnet-router/reserved anycast IIDs; no MAC-derived identifier.
  r[0]=$((0x6000+(16#${r[0]} & 0x1fff)))
  address=$(dmb_ipv6_render "${p[0]}" "${p[1]}" "${p[2]}" "${p[3]}" "${r[0]}" "$((16#${r[1]}))" "$((16#${r[2]}))" "$((16#${r[3]}))") || return
  dmb_ip_in_cidr "$address" "$prefix" || return 64
  printf '%s\n' "$address"
}
dmb_pool_plan() {
  local config=$1 id count manifest path current hash iface prefix plan='[]' resources='[]' address before after i tries=0 pool_seen='|'
  jq -e 'type=="object" and .external_probes==true and (.count|type=="number" and floor==. and .>=1 and .<=16) and (.enrollment|type=="string")' <<< "$config" >/dev/null || { dmb_pool_error 'explicit external_probes:true and count 1..16 are required'; return; }
  id=$(jq -er .enrollment <<< "$config"); count=$(jq -er .count <<< "$config")
  path=$(dmb_pool_manifest_path "$id") || return
  dmb_trusted_path "$path" || return
  manifest=$(cat -- "$path") || return
  [[ $(jq -er .id <<< "$manifest") == "$id" ]] || return 76
  current=$(dmb_pool_enroll "$manifest") || return
  [[ $(jq -cS . <<< "$manifest") == "$(jq -cS . <<< "$current")" ]] || return 76
  hash=$(sha256sum -- "$path"); hash=${hash%% *}
  iface=$(jq -er .iface <<< "$manifest"); prefix=$(jq -er .prefix <<< "$manifest")
  resources=$(jq -cn --arg iface "$iface" --arg id "$id" '["link:"+$iface,"pool:"+$id]') || return
  for ((i=0;i<count;i++)); do
    while :; do
      tries=$((tries+1)); ((tries<=128)) || return 74
      address=$(dmb_pool_generate "$prefix") || return
      [[ $pool_seen != *"|$address|"* ]] || continue
      pool_seen+="$address|"; break
    done
    local step scratch
    step=$(jq -cn --arg id "$id" --arg index "$i" --arg address "$address" --arg iface "$iface" --arg prefix "$prefix" --arg hash "$hash" --argjson manifest "$manifest" '{id:("pool-address-"+$index),adapter:"pool",resource:("pool-address:"+$iface+":"+$address),enrollment:$id,enrollment_sha256:$hash,iface:$iface,prefix:$prefix,address:$address,link:$manifest.link,netns_inode:$manifest.netns_inode,external_probes:true,after:{}}') || return
    scratch=$(jq -cn --argjson step "$step" '{steps:[$step]}') || return
    before=$(dmb_pool_capture <(printf '%s\n' "$scratch") 0) || return
    [[ $(jq -r .exists <<< "$before") == false ]] || return 76
    after=$(jq -cS --arg address "$address" '.+{exists:true,address:$address,prefixlen:128,scope:"global",protocol:"186",noprefixroute:true,permanent:true}' <<< "$before") || return
    step=$(jq -cS --argjson before "$before" --argjson after "$after" '.before=$before|.after=$after' <<< "$step") || return
    plan=$(jq -c --argjson step "$step" '.+[$step]' <<< "$plan") || return
    resources=$(jq -c --arg resource "pool-address:$iface:$address" '.+[$resource]' <<< "$resources") || return
  done
  jq -cn --argjson steps "$plan" --argjson resources "$resources" '{schema:1,adapter:"pool",resources:$resources,steps:$steps,notes:["Runtime permanent /128 addresses only. Planning performs no network probes. Apply explicitly invokes the pinned separate-host verifier before/after mutation; verifier honesty and placement are trusted. No persistence or NAT66 is installed."]}'
}
dmb_pool_snapshot() {
  local step id path destination actual expected
  step=$(dmb_pool_step "$1" "$2") || return
  id=$(jq -er .enrollment <<< "$step"); path=$(dmb_pool_manifest_path "$id") || return
  dmb_trusted_path "$path" || return
  actual=$(sha256sum -- "$path"); actual=${actual%% *}; expected=$(jq -er .enrollment_sha256 <<< "$step")
  [[ $actual == "$expected" ]] || return 76
  destination=$3/snapshots/pool-enrollment-$id.json
  if [[ -e $destination ]]; then actual=$(sha256sum -- "$destination"); [[ ${actual%% *} == "$expected" ]] || return 76
  else dmb_atomic_write "$destination" 0600 < "$path" || return; fi
  dmb_run 5 ip -j -6 address show dev "$(jq -er .iface <<< "$step")" | dmb_atomic_write "$3/snapshots/pool-address-$2-raw.json" 0600
}
dmb_pool_verifier() {
  local plan=$1 index=$2 tx=$3 phase=$4 address=$5 step manifest id path request nonce digest response verifier proof
  local -a args
  step=$(dmb_pool_step "$plan" "$index") || return
  id=$(jq -er .enrollment <<< "$step")
  path=$tx/snapshots/pool-enrollment-$id.json
  dmb_trusted_path "$path" || return
  digest=$(sha256sum -- "$path") || return
  [[ ${digest%% *} == "$(jq -er .enrollment_sha256 <<< "$step")" ]] || return 76
  manifest=$(cat -- "$path") || return
  dmb_pool_verifier_valid "$manifest" || return
  nonce=$(od -An -N16 -tx1 /dev/urandom | tr -d ' \n') || return
  [[ $nonce =~ ^[a-f0-9]{32}$ ]] || return 74
  request=$(jq -cnS --arg nonce "$nonce" --arg phase "$phase" --arg transaction "${tx##*/}" --arg address "$address" --argjson manifest "$manifest" '{schema:1,nonce:$nonce,transaction_id:$transaction,phase:$phase,prefix:$manifest.prefix,addresses:[$address],verifier_id:$manifest.verifier.identity,expected_source:$manifest.verifier.source_address}') || return
  digest=$(printf '%s\n' "$request" | sha256sum); digest=${digest%% *}
  verifier=$(jq -er .verifier.path <<< "$manifest") || return
  mapfile -d '' -t args < <(jq -jr '.verifier.args[]|.,"\u0000"' <<< "$manifest")
  response=$(dmb_run 25 "$verifier" "${args[@]}" <<< "$request" | head -c 65537) || { dmb_pool_error 'external probe inconclusive or failed; address verification was not established'; return; }
  ((${#response}<=65536)) || return 74
  proof=$(jq -ceS --arg digest "$digest" --argjson request "$request" '. as $p|select(.schema==1 and .request_sha256==$digest and .nonce==$request.nonce and .phase==$request.phase and .verifier_id==$request.verifier_id and .prefix==$request.prefix and .location=="external" and .result=="reachable" and .source_address==$request.expected_source and (.observations|length)==($request.addresses|length) and all($request.addresses[];. as $a|any($p.observations[];.address==$a and .reachable==true and .direction=="inbound")))' <<< "$response") || { dmb_pool_error 'external verifier did not return complete matching reachability evidence'; return; }
  printf '%s\n' "$proof" | dmb_atomic_write "$tx/snapshots/pool-address-$index-$phase-proof.json" 0600
}
dmb_pool_preflight() {
  local step manifest current expected iface value key routes addresses anchor
  step=$(dmb_pool_step "$1" "$2") || return
  manifest=$(cat -- "$3/snapshots/pool-enrollment-$(jq -er .enrollment <<< "$step").json") || return
  iface=$(jq -er .iface <<< "$step")
  dmb_ipv6_unmanaged "$iface" || return
  current=$(dmb_route_link "$iface" | jq -cS '{ifindex,ifname,address,master:(.master//null),kind:(.linkinfo.info_kind//"ether")}') || return
  expected=$(jq -cS .link <<< "$manifest") || return
  [[ $current == "$expected" && $(stat -Lc %i /proc/self/ns/net) == "$(jq -er .netns_inode <<< "$manifest")" ]] || return 76
  for key in disable_ipv6 accept_dad dad_transmits; do
    read -r value < "/proc/sys/net/ipv6/conf/$iface/$key" || return
    [[ $value =~ ^[0-9]+$ ]] || return 69
    if [[ $key == disable_ipv6 ]]; then [[ $value == 0 ]] || return 69; else ((value>=1 && value<=3)) || return 69; fi
  done
  anchor=$(jq -er .anchor <<< "$manifest") || return
  addresses=$(dmb_run 5 ip -j -6 address show dev "$iface") || return
  jq -e --arg anchor "$anchor" 'any(.[].addr_info[]?;.local==$anchor and .prefixlen==64 and .scope=="global" and .valid_life_time==4294967295 and .preferred_life_time==4294967295 and (.tentative//false|not) and (.dadfailed//false|not) and (.deprecated//false|not))' <<< "$addresses" >/dev/null || { dmb_pool_error 'the enrolled prefix anchor disappeared, expired or changed during application'; return; }
  local members
  members=$(jq -c '[.steps[]|select(.adapter=="pool")|.address]' "$1") || return
  routes=$(dmb_run 5 ip -j -6 route show table all dev "$iface" | jq -cS --argjson members "$members" 'map(select((.type=="local" and (.dst|rtrimstr("/128")) as $a|$members|index($a)!=null)|not)|del(.expires,.cache,.lastuse,.used))') || return
  [[ $routes == "$(jq -cS .routing_snapshot <<< "$manifest")" ]] || return 76
  if [[ ${4:-anchor} != context ]]; then dmb_pool_verifier "$1" "$2" "$3" anchor "$anchor"; fi
}
dmb_pool_apply() {
  local step iface address expected current n data
  step=$(dmb_pool_step "$1" "$2") || return
  iface=$(jq -er .iface <<< "$step"); address=$(jq -er .address <<< "$step")
  current=$(dmb_pool_capture "$1" "$2" | jq -cS .) || return
  expected=$(jq -cS .before <<< "$step") || return
  [[ $current == "$expected" ]] || return 76
  dmb_pool_preflight "$1" "$2" "$3" || return
  dmb_run 8 ip -6 address add "$address/128" dev "$iface" proto 186 noprefixroute || return
  for ((n=0;n<12;n++)); do
    data=$(dmb_run 5 ip -j -6 address show dev "$iface") || return
    jq -e --arg address "$address" 'any(.[].addr_info[]?;.local==$address and (.dadfailed//false))' <<< "$data" >/dev/null && { dmb_pool_error 'duplicate-address detection failed'; return; }
    if jq -e --arg address "$address" 'any(.[].addr_info[]?;.local==$address and (.tentative//false|not))' <<< "$data" >/dev/null; then return 0; fi
    sleep 1
  done
  dmb_pool_error 'DAD did not reach a preferred state within the bound'
}
dmb_pool_verify() {
  local step actual expected address iface data
  step=$(dmb_pool_step "$1" "$2") || return
  actual=$(dmb_pool_capture "$1" "$2" | jq -cS .) || return
  expected=$(jq -cS .after <<< "$step") || return
  [[ $actual == "$expected" ]] || return 76
  address=$(jq -er .address <<< "$step"); iface=$(jq -er .iface <<< "$step")
  data=$(dmb_run 5 ip -j -6 address show dev "$iface") || return
  jq -e --arg address "$address" 'any(.[].addr_info[]?;.local==$address and (.tentative//false|not) and (.dadfailed//false|not) and (.deprecated//false|not))' <<< "$data" >/dev/null || return 69
  dmb_pool_preflight "$1" "$2" "$3" context || return
  dmb_pool_verifier "$1" "$2" "$3" member "$address"
}
dmb_pool_restore() {
  local step actual before after iface address
  step=$(dmb_pool_step "$1" "$2") || return
  actual=$(dmb_pool_capture "$1" "$2" | jq -cS .) || return
  before=$(jq -cS .before <<< "$step"); after=$(jq -cS .after <<< "$step")
  [[ $actual != "$before" ]] || return 0
  [[ $actual == "$after" && $(jq -r .exists <<< "$before") == false ]] || return 76
  iface=$(jq -er .iface <<< "$step"); address=$(jq -er .address <<< "$step")
  if declare -F dmb_nat66_pool_removal_check >/dev/null; then dmb_nat66_pool_removal_check "$iface" "$address" || return; fi
  dmb_run 8 ip -6 address del "$address/128" dev "$iface" || return
  dmb_pool_verify_restore "$1" "$2" "$3"
}
dmb_pool_verify_restore() {
  local actual expected
  actual=$(dmb_pool_capture "$1" "$2" | jq -cS .) || return
  expected=$(jq -cS --argjson i "$2" '.steps[$i].before' "$1") || return
  [[ $actual == "$expected" ]]
}
# END MODULE adapters/pool.sh

# BEGIN MODULE adapters/nft.sh
# shellcheck shell=bash
# Native nftables ownership adapter. Sourcing this file performs no I/O.

dmb_nft_error() { printf 'nft: %s\n' "$*" >&2; return 1; }

dmb_nft_semantic() {
  # Rule and expression order stay semantic. Normalize only libnftables aliases
  # demonstrated by native readback, then remove handles and dynamic counters.
  jq -Sc '
    walk(if type=="object" then del(.handle) |
      (if has("counter") and (.counter|type)=="object" then .counter |= del(.packets,.bytes) else . end) |
      (if .match?.op=="in" and (.match.right|type)=="object" and (.match.right|has("set")) then .match.op="==" else . end)
      else . end) |
    if has("nftables") then .nftables |= map(select(has("metainfo")|not) |
      if has("rule") then .rule.expr |= (. as $expressions | [range(0;length) as $i |
        if ($expressions[$i].match?.left.meta?.key=="l4proto" and
            $expressions[$i].match.op=="==" and
            ($expressions[$i].match.right=="tcp" or $expressions[$i].match.right=="udp") and
            $expressions[$i+1].match?.left.payload?.protocol==$expressions[$i].match.right)
        then empty else $expressions[$i] end]) else . end)
    else . end'
}

dmb_nft_native() {
  # Semantic counter:{} intentionally omits volatile values, but libnftables
  # requires anonymous counter:null when submitting a new native statement.
  jq -c 'walk(if type=="object" and .counter?=={} then .counter=null else . end)'
}

dmb_nft_selector() {
  local plan=$1 index=$2
  jq -ce --argjson i "$index" '.steps[$i].nft |
    select(type=="object" and .family=="inet" and (.owner_id|test("^[a-f0-9]{32}$")) and
      (.table|test("^[A-Za-z_][A-Za-z0-9_]{0,31}$")) and
      (.chain|test("^[A-Za-z_][A-Za-z0-9_]{0,31}$"))) |
    select((.mode=="exclusive" and .table=="dmitbox_local" and .chain=="input" and (.parent_chain==null)) or
      (.mode=="scoped" and (.chain|startswith("dmb_")) and
       (.parent_chain|type)=="string" and (.parent_chain|test("^[A-Za-z_][A-Za-z0-9_]{0,31}$")) and .parent_chain!=.chain))' "$plan" 
}

dmb_nft_enrollment_path() { printf '%s/enrollments/nft.json\n' "${DMB_STATE_DIR:-/var/lib/dmitbox-local}"; }

dmb_nft_authorize() {
  local selector=$1 manifest
  manifest=$(dmb_nft_enrollment_path) || return 1
  dmb_trusted_path "$manifest" || return 1
  jq -e --argjson expected "$selector" '.schema==1 and .nft==$expected and (.pipeline_sha256|test("^[a-f0-9]{64}$"))' "$manifest" >/dev/null ||
    dmb_nft_error 'selector does not match the enrolled nft authority'
}

# The foreign portion of an enrolled table is a prerequisite, not part of our
# rollback resource. Pin its ordering, parent hook/policy and referenced objects
# while excluding only the independently owned child and tagged jump.
dmb_nft_pipeline_hash() {
  local selector=$1 ruleset=$2
  jq -c --argjson s "$selector" '
    {nftables:[.nftables[] |
      select((.table?.family==$s.family and .table?.name==$s.table) or
        (to_entries[0].value.family==$s.family and to_entries[0].value.table==$s.table)) |
      if $s.mode=="exclusive" then empty
      elif .chain?.name==$s.chain or .rule?.chain==$s.chain or
        (.rule?.chain==$s.parent_chain and .rule?.comment==("dmitbox-local:"+$s.owner_id))
      then empty else . end]}' "$ruleset" | dmb_nft_semantic | sha256sum | cut -d' ' -f1
}
dmb_nft_pipeline_check() {
  local selector=$1 ruleset=$2 manifest expected current
  manifest=$(dmb_nft_enrollment_path) || return
  dmb_trusted_path "$manifest" || return
  expected=$(jq -er '.pipeline_sha256|select(test("^[a-f0-9]{64}$"))' "$manifest") || return 1
  current=$(dmb_nft_pipeline_hash "$selector" "$ruleset") || return
  [[ $current == "$expected" ]] || { dmb_nft_error 'enrolled foreign table pipeline changed; refusing mixed generations'; return 76; }
}

dmb_nft_ruleset() {
  # A netlink query can request kernel module autoload. Status and planning
  # must not cause that side effect; enable the native facility explicitly.
  dmb_nft_facility_ready || { dmb_nft_error 'nf_tables is not observably enabled; load/enable it explicitly outside this tool'; return 69; }
  dmb_run 15 nft -j list ruleset
}
dmb_nft_facility_ready() { [[ -d /sys/module/nf_tables ]]; }

dmb_nft_foreign_guard() {
  local selector=$1 ruleset=$2
  # A child-chain jump must be within its parent table. Other INPUT/ingress
  # chains may still drop after our accept; no ordering trick bypasses them.
  jq -e --argjson s "$selector" '
    [.nftables[] | .chain? // empty | select(.hook=="input" or .hook=="ingress") |
      select(if $s.mode=="exclusive" then
        (.family!=$s.family or .table!=$s.table)
      else (.family!=$s.family or .table!=$s.table or .name!=$s.parent_chain) end)] | length==0' "$ruleset" >/dev/null ||
    dmb_nft_error 'foreign INPUT/ingress hook exists; own accept cannot override its drop policy'
}

dmb_nft_state_from_ruleset() {
  local selector=$1 ruleset=$2
  jq -c --argjson s "$selector" '
    def owned: "dmitbox-local:"+$s.owner_id;
    if $s.mode=="exclusive" then
      [.nftables[] | select((.table?.family==$s.family and .table?.name==$s.table) or
        (to_entries[0].value.family==$s.family and to_entries[0].value.table==$s.table))] as $items |
      if ($items|length)==0 then {present:false,nftables:[]}
      elif ([$items[]|.table? // empty|select(.comment==owned)]|length)!=1 then error("unowned table name collision")
      else {present:true,nftables:$items} end
    else
      [.nftables[]|.chain? // empty|select(.family==$s.family and .table==$s.table and .name==$s.chain)] as $child |
      [.nftables[]|.rule? // empty|select(.family==$s.family and .table==$s.table and .chain==$s.parent_chain and .comment==owned)] as $jump |
      if ($child|length)==0 and ($jump|length)==0 then {present:false,nftables:[]}
      elif ($child|length)!=1 or $child[0].comment!=owned or ($jump|length)!=1 or
        $jump[0].expr!=[{jump:{target:$s.chain}}] then error("invalid scoped ownership or jump")
      else {present:true,nftables:([
        .nftables[]|select(.chain?.family==$s.family and .chain?.table==$s.table and .chain?.name==$s.chain)] +
        [.nftables[]|select(.rule?.family==$s.family and .rule?.table==$s.table and .rule?.chain==$s.chain)] +
        [.nftables[]|select(.rule?.family==$s.family and .rule?.table==$s.table and .rule?.chain==$s.parent_chain and .rule?.comment==owned)])} end
    end' "$ruleset" | dmb_nft_semantic
}

dmb_nft_capture() {
  local plan=$1 index=$2 selector ruleset state
  selector=$(dmb_nft_selector "$plan" "$index") || return 1
  dmb_nft_authorize "$selector" || return 1
  dmb_nft_manager_guard || return 1
  ruleset=$(dmb_nft_ruleset) || return 1
  dmb_nft_foreign_guard "$selector" <(printf '%s\n' "$ruleset") || return 1
  dmb_nft_pipeline_check "$selector" <(printf '%s\n' "$ruleset") || return
  state=$(dmb_nft_state_from_ruleset "$selector" <(printf '%s\n' "$ruleset")) || return
  dmb_nft_state_validate "$selector" "$state" || return
  printf '%s\n' "$state"
}

dmb_nft_state_validate() {
  local selector=$1 state=$2
  jq -e --argjson s "$selector" '
    def owner: "dmitbox-local:"+$s.owner_id;
    type=="object" and (.present|type)=="boolean" and (.nftables|type)=="array" and
    (if .present==false then .nftables==[] else
      (.nftables|length)>0 and all(.nftables[];
        if has("table") then $s.mode=="exclusive" and .table.family==$s.family and .table.name==$s.table and .table.comment==owner
        elif has("chain") then .chain.family==$s.family and .chain.table==$s.table and .chain.name==$s.chain and .chain.comment==owner and
          (if $s.mode=="exclusive" then .chain.type=="filter" and .chain.hook=="input" and .chain.prio==0 and (.chain.policy=="accept" or .chain.policy=="drop") else .chain.hook==null end)
        elif has("rule") then .rule.family==$s.family and .rule.table==$s.table and
          (if .rule.chain==$s.chain then true else .rule.chain==$s.parent_chain and .rule.comment==owner and .rule.expr==[{jump:{target:$s.chain}}] end)
        else false end)
    end)' <<< "$state" >/dev/null || dmb_nft_error 'invalid owned nft state'
}

dmb_nft_batch() {
  local selector=$1 old=$2 desired=$3 live_ruleset=$4
  dmb_nft_state_validate "$selector" "$desired" || return 1
  jq -c --argjson s "$selector" --argjson old "$old" --argjson desired "$desired" '
    def tag: "dmitbox-local:"+$s.owner_id;
    [if $old.present then
      if $s.mode=="exclusive" then {delete:{table:{family:$s.family,name:$s.table}}}
      elif $desired.present then
        {flush:{chain:{family:$s.family,table:$s.table,name:$s.chain}}}
      else
        (.nftables[]|.rule? // empty|select(.family==$s.family and .table==$s.table and .chain==$s.parent_chain and .comment==tag)|
          if .handle==null then error("missing jump handle") else {delete:{rule:{family:$s.family,table:$s.table,chain:$s.parent_chain,handle:.handle}}} end),
        {flush:{chain:{family:$s.family,table:$s.table,name:$s.chain}}},
        {delete:{chain:{family:$s.family,table:$s.table,name:$s.chain}}}
      end
    else empty end] +
    [if $desired.present then $desired.nftables[] |
      if $s.mode=="scoped" and $old.present and (has("chain") or (has("rule") and .rule.chain==$s.parent_chain)) then empty
      elif has("rule") and .rule.chain==$s.parent_chain then {insert:{rule:.rule}}
      elif has("table") or has("chain") then {create:.}
      else {add:.} end
    else empty end] | {nftables:.}' "$live_ruleset" | dmb_nft_native
}

dmb_nft_transition() {
  local plan=$1 index=$2 txdir=$3 field=$4 selector desired actual live batch expected opposite live_state
  selector=$(dmb_nft_selector "$plan" "$index") || return 1
  dmb_nft_authorize "$selector" || return 1
  desired=$(jq -ce --argjson i "$index" --arg field "$field" '.steps[$i][$field]' "$plan" | dmb_nft_semantic) || return 1
  dmb_nft_state_validate "$selector" "$desired" || return 1
  actual=$(dmb_nft_capture "$plan" "$index") || return 1
  [[ "$actual" != "$desired" ]] || return 0
  if [[ $field == after ]]; then opposite=before; else opposite=after; fi
  expected=$(jq -ce --argjson i "$index" --arg field "$opposite" '.steps[$i][$field]' "$plan" | dmb_nft_semantic) || return 1
  if [[ $actual != "$expected" ]]; then
    [[ $field == before ]] && dmb_nft_owned_reset "$plan" "$index" "$txdir" || { dmb_nft_error 'owned resource generation changed before publication'; return 76; }
  fi
  live=$(mktemp "$txdir/nft-live.XXXXXXXX") || return 1
  batch=$(mktemp "$txdir/nft-batch.XXXXXXXX") || { rm -f -- "$live"; return 1; }
  if ! dmb_nft_ruleset > "$live" || ! dmb_nft_foreign_guard "$selector" "$live" || ! dmb_nft_pipeline_check "$selector" "$live"; then rm -f -- "$live" "$batch"; return 1; fi
  live_state=$(dmb_nft_state_from_ruleset "$selector" "$live") || { rm -f -- "$live" "$batch"; return 1; }
  [[ $live_state == "$actual" ]] || { rm -f -- "$live" "$batch"; dmb_nft_error 'nft generation changed during preparation'; return 76; }
  if ! dmb_nft_batch "$selector" "$actual" "$desired" "$live" > "$batch"; then rm -f -- "$live" "$batch"; return 1; fi
  if ! dmb_run 15 nft -j -c -f "$batch" || ! dmb_run 15 nft -j -f "$batch"; then rm -f -- "$live" "$batch"; return 1; fi
  rm -f -- "$live" "$batch"
  actual=$(dmb_nft_capture "$plan" "$index") || return 1
  [[ "$actual" == "$desired" ]] || dmb_nft_error 'post-publication nft state differs from desired generation'
}

dmb_nft_apply() { dmb_nft_transition "$1" "$2" "$3" after; }
dmb_nft_restore() { dmb_nft_transition "$1" "$2" "$3" before; }
dmb_nft_verify() {
  local plan=$1 index=$2 actual desired
  actual=$(dmb_nft_capture "$plan" "$index") || return 1
  desired=$(jq -ce --argjson i "$index" '.steps[$i].after' "$plan" | dmb_nft_semantic) || return 1
  [[ "$actual" == "$desired" ]] || dmb_nft_error 'nft verification differs from planned state'
}

# Plan helpers emit data only. Enrollment is an explicit separate root action.
# Typed listener and rule values become JSON expressions, never nft command text.
dmb_nft_plan_state() {
  local selector=$1 listeners=$2 rules=${3:-'[]'} policy=${4:-drop} address
  jq -e 'type=="array" and all(.[];(.address|type)=="string")' <<< "$listeners" >/dev/null || return 2
  while IFS= read -r address; do dmb_ip_parse "$address" >/dev/null || return 2; done < <(jq -r '.[].address' <<< "$listeners")
  [[ "$policy" == drop || "$policy" == accept ]] || return 1
  jq -cen --argjson s "$selector" --argjson listeners "$listeners" --argjson rules "$rules" --arg policy "$policy" '
    def portvalid: type=="number" and floor==. and .>=1 and .<=65535;
    def addrvalid: type=="string" and (test("^[0-9.]+$") or test("^[0-9A-Fa-f:]+$") and contains(":"));
    def baseexpr($protocol;$port): [
      {match:{op:"==",left:{meta:{key:"l4proto"}},right:$protocol}},
      {match:{op:"==",left:{payload:{protocol:$protocol,field:"dport"}},right:$port}}];
    def rule($expr): {rule:{family:$s.family,table:$s.table,chain:$s.chain,expr:$expr}};
    def listener:
      select(.port|portvalid) | select(.address|addrvalid) |
      rule((if .address=="0.0.0.0" or .address=="::" then [] else
        [{match:{op:"==",left:{payload:{protocol:(if .address|contains(":") then "ip6" else "ip" end),field:"daddr"}},right:.address}}] end) +
        (if .address=="0.0.0.0" then [{match:{op:"==",left:{meta:{key:"nfproto"}},right:"ipv4"}}]
         elif .address=="::" then [{match:{op:"==",left:{meta:{key:"nfproto"}},right:"ipv6"}}] else [] end) +
        baseexpr("tcp";.port)+[{accept:null}]);
    if ($listeners|type)!="array" or any($listeners[]; (.port|portvalid|not) or (.address|addrvalid|not)) then error("invalid listener") else . end |
    if ($rules|type)!="array" or any($rules[]; (.action!="allow" and .action!="deny") or (.protocol!="tcp" and .protocol!="udp") or (.port|portvalid|not) or has("source")) then error("invalid typed rule") else . end |
    {present:true,nftables:(
      (if $s.mode=="exclusive" then [
        {table:{family:$s.family,name:$s.table,comment:("dmitbox-local:"+$s.owner_id)}},
        {chain:{family:$s.family,table:$s.table,name:$s.chain,type:"filter",hook:"input",prio:0,policy:$policy,comment:("dmitbox-local:"+$s.owner_id)}},
        rule([{match:{op:"==",left:{meta:{key:"iifname"}},right:"lo"}},{accept:null}]),
        rule([{match:{op:"in",left:{ct:{key:"state"}},right:{set:["established","related"]}}},{accept:null}]),
        rule([{match:{op:"==",left:{ct:{key:"state"}},right:"invalid"}},{drop:null}]),
        rule([{match:{op:"==",left:{meta:{key:"l4proto"}},right:{set:["icmp","ipv6-icmp"]}}},{accept:null}])]
      else [{chain:{family:$s.family,table:$s.table,name:$s.chain,comment:("dmitbox-local:"+$s.owner_id)}}] end) +
      [$listeners[]|listener] +
      [$rules[]|rule(baseexpr(.protocol;.port)+[if .action=="allow" then {accept:null} else {drop:null} end])] +
      (if $s.mode=="scoped" then [{rule:{family:$s.family,table:$s.table,chain:$s.parent_chain,comment:("dmitbox-local:"+$s.owner_id),expr:[{jump:{target:$s.chain}}]}}] else [] end))}' | dmb_nft_semantic
}

dmb_nft_plan_exclusive() {
  local owner=$1 listeners=$2 rules=${3:-'[]'} selector state
  [[ "$owner" =~ ^[a-f0-9]{32}$ ]] || return 1
  selector=$(jq -cn --arg owner "$owner" '{mode:"exclusive",family:"inet",table:"dmitbox_local",chain:"input",parent_chain:null,owner_id:$owner}') || return 1
  state=$(dmb_nft_plan_state "$selector" "$listeners" "$rules") || return 1
  jq -cn --argjson s "$selector" --argjson state "$state" '{adapter:"nft",resource:"nft-inet-dmitbox_local",nft:$s,after:$state}'
}

dmb_nft_plan_scoped() {
  local owner=$1 table=$2 parent=$3 child=$4 listeners=$5 rules=${6:-'[]'} selector state
  [[ "$owner" =~ ^[a-f0-9]{32}$ && "$table" =~ ^[A-Za-z_][A-Za-z0-9_]{0,31}$ && "$parent" =~ ^[A-Za-z_][A-Za-z0-9_]{0,31}$ && "$child" =~ ^dmb_[A-Za-z0-9_]{1,28}$ && "$parent" != "$child" ]] || return 1
  selector=$(jq -cn --arg owner "$owner" --arg table "$table" --arg parent "$parent" --arg child "$child" '{mode:"scoped",family:"inet",table:$table,chain:$child,parent_chain:$parent,owner_id:$owner}') || return 1
  state=$(dmb_nft_plan_state "$selector" "$listeners" "$rules" accept) || return 1
  jq -cn --argjson s "$selector" --argjson state "$state" '{adapter:"nft",resource:("nft-inet-"+$s.table+"-"+$s.chain),nft:$s,after:$state}'
}

dmb_nft_enroll() {
  local config=$1 selector ruleset existing pipeline
  jq -e '.schema==1 and (.nft|type)=="object"' "$config" >/dev/null || return 2
  selector=$(dmb_nft_selector <(jq '{steps:[{nft:.nft}]}' "$config") 0) || return 2
  dmb_nft_manager_guard || return 1
  ruleset=$(dmb_nft_ruleset) || return 1
  dmb_nft_foreign_guard "$selector" <(printf '%s\n' "$ruleset") || return 1
  if [[ $(jq -r .mode <<< "$selector") == scoped ]]; then
    jq -e --argjson s "$selector" '[.nftables[]|.chain? // empty|select(.family==$s.family and .table==$s.table and .name==$s.parent_chain and .type=="filter" and .hook=="input")]|length==1' <<< "$ruleset" >/dev/null || return 1
  fi
  existing=$(dmb_nft_state_from_ruleset "$selector" <(printf '%s\n' "$ruleset")) || return 1
  dmb_nft_state_validate "$selector" "$existing" || return
  pipeline=$(dmb_nft_pipeline_hash "$selector" <(printf '%s\n' "$ruleset")) || return
  jq -nSc --argjson selector "$selector" --argjson baseline "$existing" --arg pipeline "$pipeline" '{schema:1,nft:$selector,baseline:$baseline,pipeline_sha256:$pipeline}'
}

# Enrollment never grants mixed control to competing firewall managers.
# Detection is read-only. Inactive installed software alone is not a conflict.
dmb_nft_systemd_service_guard() {
  local service=$1 data load active enabled job
  case $service in ufw.service|firewalld.service|shorewall.service|nftables.service) ;; *) return 64;; esac
  data=$(dmb_run 5 systemctl show --no-pager --property=LoadState,ActiveState,UnitFileState,Job "$service") || { dmb_nft_error "cannot inspect competing manager state: $service"; return 1; }
  load=$(sed -n 's/^LoadState=//p' <<< "$data")
  active=$(sed -n 's/^ActiveState=//p' <<< "$data")
  enabled=$(sed -n 's/^UnitFileState=//p' <<< "$data")
  job=$(sed -n 's/^Job=//p' <<< "$data")
  case $load in
    not-found) [[ $active == inactive ]] || return 1;;
    loaded|masked)
      [[ $active == inactive || $active == failed ]] || { dmb_nft_error "competing manager is active/changing: $service"; return 1; }
      [[ -z $job || $job == 0 ]] || { dmb_nft_error "competing manager has a queued job: $service"; return 1; }
      case $enabled in disabled|masked|masked-runtime) ;; *) dmb_nft_error "competing manager may reload policy at boot: $service"; return 1;; esac;;
    *) dmb_nft_error "unknown competing manager state: $service"; return 1;;
  esac
}
dmb_nft_manager_guard() {
  local entry comm family save names data service
  for family in ip ip6; do
    names=/proc/net/${family}_tables_names
    [[ -r $names ]] || continue
    grep -qx filter "$names" || continue
    if [[ $family == ip ]]; then save=iptables-legacy-save; else save=ip6tables-legacy-save; fi
    command -v "$save" >/dev/null || { dmb_nft_error "legacy $family filter ownership cannot be inspected"; return 1; }
    data=$(dmb_run 5 "$save" -t filter) || return 1
    if ! grep -Eq '^:INPUT ACCEPT ' <<< "$data" || grep -Eq '^-A INPUT([[:space:]]|$)' <<< "$data"; then
      dmb_nft_error "legacy $family INPUT policy has separate ownership"; return 1
    fi
  done
  for entry in /proc/[0-9]*/comm; do
    [[ -r $entry ]] || continue
    IFS= read -r comm < "$entry" || continue
    case "$comm" in firewalld|ufw|shorewall|ferm) dmb_nft_error "competing active firewall manager: $comm"; return 1;; esac
  done
  if [[ -d /run/systemd/system ]]; then
    dmb_need systemctl || return 1
    for service in ufw.service firewalld.service shorewall.service nftables.service; do
      dmb_nft_systemd_service_guard "$service" || return
    done
  elif command -v rc-service >/dev/null; then
    local service
    for service in ufw firewalld shorewall nftables; do
      if dmb_run 5 rc-service "$service" status >/dev/null 2>&1; then
        dmb_nft_error "competing active firewall manager: $service"; return 1
      fi
    done
  fi
}

dmb_nft_plan() {
  local config=$1 manifest selector listeners rules policy state before origin
  manifest=$(dmb_nft_enrollment_path) || return 1
  dmb_trusted_path "$manifest" || return 1
  selector=$(jq -ce '.nft' "$manifest") || return 1
  jq -e --argjson s "$selector" '.schema==1 and .nft==$s' "$config" >/dev/null || return 2
  listeners=$(jq -ce '.listeners|select(type=="array")' "$config") || return 2
  rules=$(jq -ce '.rules // []' "$config") || return 2
  policy=$(jq -er '.policy // "drop"' "$config") || return 2
  local address
  while IFS= read -r address; do dmb_ip_parse "$address" >/dev/null || return 2; done < <(jq -r '.[].address' <<< "$listeners")
  state=$(dmb_nft_plan_state "$selector" "$listeners" "$rules" "$policy") || return 2
  before=$(dmb_nft_capture <(jq -cn --argjson s "$selector" '{steps:[{nft:$s}]}') 0) || return 1
  origin=$(dmb_confirmation_origin) || { dmb_nft_error 'cannot identify an authenticated origin transport'; return 78; }
  jq -cnS --argjson s "$selector" --argjson before "$before" --argjson after "$state" --argjson origin "$origin" --argjson allow_console "$(jq -c '.confirmation.allow_console_confirmation==true' "$DMB_STATE_DIR/enrollments/ssh.json")" '{schema:1,adapter:"nft",resources:[("nft-"+$s.family+"-"+$s.table)],steps:[{id:"nft-policy",resource:("nft-"+$s.family+"-"+$s.table),adapter:"nft",nft:$s,before:$before,after:$after}],requires_confirmation:true,confirmation_enrollment:"ssh",allow_console_confirmation:$allow_console,origin_transport:$origin,confirm_port:$origin.local_port}'
}

dmb_nft_snapshot() {
  local plan=$1 index=$2 txdir=$3 raw data hash authority
  raw="$txdir/snapshots/nft-$index.raw.json"
  [[ ! -e $raw ]] || return 1
  data=$(dmb_nft_ruleset) || return 1
  jq -e '.nftables|type=="array"' <<< "$data" >/dev/null || return 1
  hash=$(printf '%s\n' "$data" | sha256sum | cut -d' ' -f1) || return 1
  printf '%s\n' "$data" | dmb_atomic_write "$raw" 0600 "$hash" || return 1
  sha256sum "$raw" | dmb_atomic_write "$raw.sha256" 0600 || return
  authority=$(dmb_nft_enrollment_path) || return
  dmb_trusted_path "$authority" || return
  hash=$(sha256sum "$authority" | cut -d' ' -f1) || return
  dmb_atomic_write "$txdir/snapshots/nft-$index-authority.json" 0600 "$hash" < "$authority" || return
  printf '%s\n' "$hash" | dmb_atomic_write "$txdir/snapshots/nft-$index-authority.sha256" 0600
}

dmb_nft_boot_id() { cat /proc/sys/kernel/random/boot_id; }
# Narrow readonly proof that a fresh boot cleared an exclusively owned kernel
# table. It is not permission to repair an arbitrary missing/mismatched table.
# Scoped parents are foreign resources and are never recreated by this path.
dmb_nft_owned_reset() {
  local plan=$1 index=$2 tx=$3 selector origin boot actual authority saved hash expected raw first original observed before
  selector=$(dmb_nft_selector "$plan" "$index") || return
  [[ $(jq -er .mode <<< "$selector") == exclusive ]] || return 76
  dmb_trusted_path "$tx/state.json" || return
  origin=$(jq -er '.boot_id|select(test("^[a-f0-9-]{36}$"))' "$tx/state.json") || return
  boot=$(dmb_nft_boot_id) || return
  [[ $boot =~ ^[a-f0-9-]{36}$ && $boot != "$origin" ]] || return 76
  before=$(jq -ceS --argjson i "$index" '.steps[$i].before' "$plan") || return
  [[ $(jq -r .present <<< "$before") == true ]] || return 76
  dmb_nft_state_validate "$selector" "$before" || return
  authority=$(dmb_nft_enrollment_path) || return
  saved=$tx/snapshots/nft-$index-authority.json
  for actual in "$authority" "$saved" "$tx/snapshots/nft-$index-authority.sha256"; do dmb_trusted_path "$actual" || return; done
  IFS= read -r expected < "$tx/snapshots/nft-$index-authority.sha256" || return
  [[ $expected =~ ^[a-f0-9]{64}$ ]] || return
  hash=$(sha256sum "$saved" | cut -d' ' -f1) || return
  [[ $hash == "$expected" && $(sha256sum "$authority" | cut -d' ' -f1) == "$expected" ]] || return 76
  raw=$tx/snapshots/nft-$index.raw.json
  dmb_trusted_path "$raw" && dmb_trusted_path "$raw.sha256" || return
  read -r expected _ < "$raw.sha256" || return
  [[ $expected =~ ^[a-f0-9]{64}$ && $(sha256sum "$raw" | cut -d' ' -f1) == "$expected" ]] || return 76
  first=$(jq -er --argjson s "$selector" '[.steps|to_entries[]|select(.value.nft==$s)]|first.key' "$plan") || return
  original=$(jq -ceS --argjson i "$first" '.steps[$i].before' "$plan") || return
  [[ $(jq -r .present <<< "$original") == true ]] || return 76
  dmb_nft_state_validate "$selector" "$original" || return
  observed=$(dmb_nft_state_from_ruleset "$selector" "$raw") || return
  [[ $observed == "$original" ]] || return 76
  # capture rechecks manager ownership, foreign hooks and the enrolled pipeline.
  actual=$(dmb_nft_capture "$plan" "$index") || return
  [[ $actual == '{"nftables":[],"present":false}' ]] || return 76
}

dmb_nft_verify_restore() {
  local actual expected
  actual=$(dmb_nft_capture "$1" "$2") || return 1
  expected=$(jq -ceS --argjson i "$2" '.steps[$i].before' "$1") || return 1
  [[ $actual == "$expected" ]]
}
# END MODULE adapters/nft.sh

# BEGIN MODULE adapters/nat66.sh
# shellcheck shell=bash
# Narrow runtime NAT66 for explicitly enrolled permanent pool members. The
# original/reply direction match leaves established connections and inbound SSH
# replies outside the new-flow selector. No connection/packet marks are written.
dmb_nat66_error() { dmb_error "nat66: $*"; return 69; }
dmb_nat66_semantic() {
  dmb_nft_semantic | jq -Sc 'walk(if type=="object" and (.numgen?|type)=="object" then
    .numgen.offset=(.numgen.offset // 0) else . end)'
}
dmb_nat66_state() {
  local pool=$1 members=$2 owner iface anchor prefix
  owner=$(jq -er .owner_id <<< "$pool"); iface=$(jq -er .iface <<< "$pool")
  anchor=$(jq -er .anchor <<< "$pool"); prefix=$(jq -er .prefix <<< "$pool")
  jq -cnS --arg owner "$owner" --arg iface "$iface" --arg anchor "$anchor" --arg prefix "${prefix%/*}" --argjson members "$members" '
    ("dmitbox-local:nat66:"+$owner) as $tag |
    {present:true,nftables:[
      {table:{family:"ip6",name:"dmitbox_nat66",comment:$tag}},
      {chain:{family:"ip6",table:"dmitbox_nat66",name:"postrouting",type:"nat",hook:"postrouting",prio:100,policy:"accept",comment:$tag}},
      {rule:{family:"ip6",table:"dmitbox_nat66",chain:"postrouting",comment:$tag,expr:[
        {match:{op:"==",left:{meta:{key:"oifname"}},right:$iface}},
        {match:{op:"==",left:{ct:{key:"direction"}},right:"original"}},
        {match:{op:"in",left:{ct:{key:"state"}},right:"new"}},
        {match:{op:"==",left:{payload:{protocol:"ip6",field:"saddr"}},right:$anchor}},
        {match:{op:"!=",left:{payload:{protocol:"ip6",field:"daddr"}},right:{prefix:{addr:$prefix,len:64}}}},
        {snat:{addr:{map:{key:{numgen:{mode:"random",mod:($members|length)}},data:{set:[$members|to_entries[]|[.key,.value]]}}}}}
      ]}}
    ]}' | dmb_nat66_semantic
}
dmb_nat66_step() {
  local step pool members address expected before after operation
  step=$(jq -ce --argjson i "$2" '.steps[$i]|select(.adapter=="nat66")' "$1") || return
  jq -e '.operation=="enable" or .operation=="disable"' <<< "$step" >/dev/null || return 64
  jq -e '.nft=={family:"ip6",table:"dmitbox_nat66"} and (.pool|type)=="object" and
    (.members|type)=="array" and (.members|length)>=1 and (.members|length)<=4 and
    (.members|unique|length)==(.members|length) and
    (.pool_enrollment_sha256|test("^[a-f0-9]{64}$")) and .external_probes==true' <<< "$step" >/dev/null || return 64
  pool=$(jq -ce .pool <<< "$step"); members=$(jq -ce .members <<< "$step")
  dmb_pool_id "$(jq -er .id <<< "$pool")" || return 64
  [[ $(jq -er .owner_id <<< "$pool") =~ ^[a-f0-9]{32}$ ]] || return 64
  dmb_route_iface_valid "$(jq -er .iface <<< "$pool")" || return 64
  [[ $(jq -er .prefix <<< "$pool") == */64 && $(dmb_cidr_parse "$(jq -er .prefix <<< "$pool")" 6) == "$(jq -er .prefix <<< "$pool")" ]] || return 64
  dmb_pool_global "$(jq -er .anchor <<< "$pool")" && dmb_ip_in_cidr "$(jq -er .anchor <<< "$pool")" "$(jq -er .prefix <<< "$pool")" || return 64
  while IFS= read -r address; do
    [[ $(dmb_ip_parse "$address" 6) == "$address" ]] && dmb_pool_global "$address" &&
      dmb_ip_in_cidr "$address" "$(jq -er .prefix <<< "$pool")" && [[ $address != "$(jq -er .anchor <<< "$pool")" ]] || return 64
  done < <(jq -r '.[]' <<< "$members")
  expected=$(dmb_nat66_state "$pool" "$members") || return
  before=$(jq -cS .before <<< "$step"); after=$(jq -cS .after <<< "$step"); operation=$(jq -er .operation <<< "$step")
  if [[ $operation == enable ]]; then
    [[ $after == "$expected" && ( $before == '{"nftables":[],"present":false}' || $before == "$expected" ) ]] || return 64
  else [[ $before == "$expected" && $after == '{"nftables":[],"present":false}' ]] || return 64; fi
  printf '%s\n' "$step"
}
dmb_nat66_foreign_guard() {
  local ruleset=$1
  dmb_nft_manager_guard || return
  if [[ -r /proc/net/ip6_tables_names ]] && grep -qx nat /proc/net/ip6_tables_names; then
    dmb_nat66_error 'legacy IPv6 NAT owns a competing pipeline'; return
  fi
  jq -e '[.nftables[]|.chain? // empty|select((.family=="inet" or .family=="ip6") and .type=="nat")|
    select(.family!="ip6" or .table!="dmitbox_nat66")]|length==0' <<< "$ruleset" >/dev/null ||
      dmb_nat66_error 'another IPv6 NAT hook owns the translation pipeline'
}
dmb_nat66_from_ruleset() {
  local pool=$1 ruleset=$2 tag
  tag=dmitbox-local:nat66:$(jq -er .owner_id <<< "$pool")
  jq -ce --arg tag "$tag" '
    [.nftables[]|select((.table?.family=="ip6" and .table?.name=="dmitbox_nat66") or
       (to_entries[0].value.family=="ip6" and to_entries[0].value.table=="dmitbox_nat66"))] as $items |
    if ($items|length)==0 then {present:false,nftables:[]}
    elif [$items[]|.table? // empty|select(.comment==$tag)]|length!=1 then error("foreign NAT66 table name collision")
    else {present:true,nftables:$items} end' <<< "$ruleset" | dmb_nat66_semantic
}
dmb_nat66_capture() {
  local step ruleset
  step=$(dmb_nat66_step "$1" "$2") || return
  ruleset=$(dmb_nft_ruleset) || return
  # Recovery reads only its owned table; unrelated managers/prefix disappearance
  # must not prevent an independently executable inverse of that table.
  dmb_nat66_from_ruleset "$(jq -ce .pool <<< "$step")" "$ruleset"
}
dmb_nat66_pool_context() {
  local pool=$1 iface addresses anchor member members=$2 actual expected routes all_members
  iface=$(jq -er .iface <<< "$pool"); anchor=$(jq -er .anchor <<< "$pool")
  dmb_ipv6_unmanaged "$iface" || return
  actual=$(dmb_route_link "$iface" | jq -cS '{ifindex,ifname,address,master:(.master//null),kind:(.linkinfo.info_kind//"ether")}') || return
  expected=$(jq -cS .link <<< "$pool") || return
  [[ $actual == "$expected" && $(stat -Lc %i /proc/self/ns/net) == "$(jq -er .netns_inode <<< "$pool")" ]] || return 76
  addresses=$(dmb_run 5 ip -N -j -6 address show dev "$iface") || return
  jq -e --arg anchor "$anchor" 'any(.[].addr_info[]?;.local==$anchor and .prefixlen==64 and (.scope=="global" or .scope==0) and
    .valid_life_time==4294967295 and .preferred_life_time==4294967295 and (.tentative//false|not) and (.dadfailed//false|not) and (.deprecated//false|not))' <<< "$addresses" >/dev/null || return 76
  while IFS= read -r member; do
    jq -e --arg member "$member" 'any(.[].addr_info[]?;.local==$member and .prefixlen==128 and (.scope=="global" or .scope==0) and
      (.protocol==186 or .protocol=="186" or .protocol=="0xba") and .noprefixroute==true and
      .valid_life_time==4294967295 and .preferred_life_time==4294967295 and (.tentative//false|not) and (.dadfailed//false|not) and (.deprecated//false|not))' <<< "$addresses" >/dev/null || return 76
  done < <(jq -r '.[]' <<< "$members")
  all_members=$(jq -c '[.[].addr_info[]?|select(.prefixlen==128 and (.protocol==186 or .protocol=="186" or .protocol=="0xba"))|.local]' <<< "$addresses") || return
  routes=$(dmb_run 5 ip -j -6 route show table all dev "$iface" | jq -cS --argjson members "$all_members" 'map(select((.type=="local" and (.dst|rtrimstr("/128")) as $a|$members|index($a)!=null)|not)|del(.expires,.cache,.lastuse,.used))') || return
  [[ $routes == "$(jq -cS .routing_snapshot <<< "$pool")" ]] || return 76
}
dmb_nat66_members_committed() {
  local pool=$1 members=$2 id member tx i actual expected matches
  id=$(jq -er .id <<< "$pool") || return
  while IFS= read -r member; do
    matches=0
    for tx in "$DMB_STATE_DIR"/transactions/tx-*; do
      [[ -d $tx && -f $tx/state.json && -f $tx/plan.json ]] || continue
      dmb_trusted_path "$tx" && dmb_trusted_path "$tx/state.json" || return
      [[ $(jq -er .state "$tx/state.json") == COMMITTED ]] || continue
      while IFS= read -r i; do
        dmb_tx_integrity "$tx" || return 76
        actual=$(dmb_pool_capture "$tx/plan.json" "$i" | jq -cS .) || return
        expected=$(jq -cS --argjson i "$i" '.steps[$i].after' "$tx/plan.json") || return
        [[ $actual != "$expected" ]] || matches=$((matches+1))
      done < <(jq -r --arg id "$id" --arg member "$member" '.steps|to_entries[]|select(.value.adapter=="pool" and .value.enrollment==$id and .value.address==$member and .value.after.exists==true)|.key' "$tx/plan.json")
    done
    ((matches==1)) || { dmb_nat66_error 'each NAT member requires one still-current committed pool ownership record'; return; }
  done < <(jq -r '.[]' <<< "$members")
}
dmb_nat66_plan() {
  local config=$1 operation id path pool hash members address step before after ruleset
  dmb_need nft conntrack jq ip || return
  jq -e '.schema==1 and (.operation=="enable" or .operation=="disable") and .external_probes==true and
    (.enrollment|type)=="string" and (.members|type)=="array" and (.members|length)>=1 and (.members|length)<=4' <<< "$config" >/dev/null || return 64
  operation=$(jq -er .operation <<< "$config"); id=$(jq -er .enrollment <<< "$config")
  path=$(dmb_pool_manifest_path "$id") || return; dmb_trusted_path "$path" || return
  pool=$(cat -- "$path") || return; [[ $(jq -er .id <<< "$pool") == "$id" ]] || return 76
  hash=$(sha256sum -- "$path"); hash=${hash%% *}
  [[ $(printf '%s\n' "$pool" | sha256sum | cut -d' ' -f1) == "$hash" ]] || return 76
  members='[]'
  while IFS= read -r address; do
    address=$(dmb_ip_parse "$address" 6) || return
    members=$(jq -c --arg a "$address" '.+[$a]' <<< "$members") || return
  done < <(jq -r '.members[]' <<< "$config")
  ruleset=$(dmb_nft_ruleset) || return
  dmb_nat66_foreign_guard "$ruleset" || return
  before=$(dmb_nat66_from_ruleset "$pool" "$ruleset") || return
  if [[ $operation == enable ]]; then
    dmb_pool_verifier_valid "$pool" && dmb_nat66_pool_context "$pool" "$members" && dmb_nat66_members_committed "$pool" "$members" || return
    after=$(dmb_nat66_state "$pool" "$members") || return
  else after='{"nftables":[],"present":false}'; fi
  step=$(jq -cnS --arg operation "$operation" --arg iface "$(jq -er .iface <<< "$pool")" --arg hash "$hash" --argjson pool "$pool" --argjson members "$members" --argjson before "$before" --argjson after "$after" '{id:"nat66-policy",adapter:"nat66",resource:"nft:ip6:dmitbox_nat66",nft:{family:"ip6",table:"dmitbox_nat66"},iface:$iface,operation:$operation,pool:$pool,pool_enrollment_sha256:$hash,members:$members,external_probes:true,before:$before,after:$after}') || return
  dmb_nat66_step <(jq -cn --argjson step "$step" '{steps:[$step]}') 0 >/dev/null || return
  jq -cnS --arg id "$id" --argjson step "$step" '{schema:1,adapter:"nat66",timeout_seconds:180,resources:["nft:ip6:dmitbox_nat66",("pool:"+$id),("link:"+$step.iface)],steps:[$step],notes:["Runtime NAT66 only; only new original-direction flows from the enrolled anchor are selected. Existing conntracks and all pool addresses remain. Disable waits bounded for translated flows to drain; a timeout is a failed verification and restores policy. Explicit external probes run only during apply/verify."]}'
}
dmb_nat66_snapshot() {
  local step path hash raw
  step=$(dmb_nat66_step "$1" "$2") || return
  path=$(dmb_pool_manifest_path "$(jq -er .pool.id <<< "$step")") || return
  dmb_trusted_path "$path" || return
  hash=$(sha256sum -- "$path"); hash=${hash%% *}
  [[ $hash == "$(jq -er .pool_enrollment_sha256 <<< "$step")" ]] || return 76
  [[ $(jq -cS . "$path") == "$(jq -cS .pool <<< "$step")" ]] || return 76
  dmb_atomic_write "$3/snapshots/nat66-$2-pool.json" 0600 "$hash" < "$path" || return
  raw=$(dmb_nft_ruleset) || return
  printf '%s\n' "$raw" | dmb_atomic_write "$3/snapshots/nat66-$2-raw.json" 0600
}
dmb_nat66_verifier() {
  local step pool phase=$4 request nonce digest response program proof actual
  local -a verifier_args
  step=$(dmb_nat66_step "$1" "$2") || return; pool=$(jq -ce .pool <<< "$step") || return
  dmb_pool_verifier_valid "$pool" || return
  nonce=$(od -An -N16 -tx1 /dev/urandom | tr -d ' \n') || return
  request=$(jq -cnS --arg nonce "$nonce" --arg phase "$phase" --arg transaction "${3##*/}" --argjson step "$step" '{schema:1,nonce:$nonce,transaction_id:$transaction,phase:$phase,prefix:$step.pool.prefix,anchor:$step.pool.anchor,members:$step.members,verifier_id:$step.pool.verifier.identity,expected_source:$step.pool.verifier.source_address}') || return
  digest=$(printf '%s\n' "$request" | sha256sum); digest=${digest%% *}
  program=$(jq -er .verifier.path <<< "$pool") || return
  mapfile -d '' -t verifier_args < <(jq -jr '.verifier.args[]|.,"\u0000"' <<< "$pool")
  response=$(dmb_run 20 "$program" "${verifier_args[@]}" <<< "$request" | head -c 65537) || { dmb_nat66_error 'external NAT probe failed or was blocked; evidence inconclusive'; return; }
  ((${#response}<=65536)) || return 74
  proof=$(jq -ceS --argjson request "$request" --arg digest "$digest" '
    . as $proof | select(.schema==1 and .request_sha256==$digest and .nonce==$request.nonce and .phase==$request.phase and
      .verifier_id==$request.verifier_id and .prefix==$request.prefix and .source_address==$request.expected_source and
      .location=="external" and .result=="reachable" and
      (.observations|type)=="array" and (.observations|length)==($request.members|length) and
      all($request.members[];. as $member|any($proof.observations[];.address==$member and .reachable==true and
        (if $request.phase=="nat66-outbound" then .direction=="outbound" and .observed_source==$member else .direction=="inbound" end))))' <<< "$response") || { dmb_nat66_error 'external evidence did not prove every selected member'; return; }
  actual=$(printf '%s\n' "$proof" | sha256sum); actual=${actual%% *}
  printf '%s\n' "$proof" | dmb_atomic_write "$3/snapshots/nat66-$2-$phase-proof.json" 0600 "$actual"
}
dmb_nat66_transition() {
  local plan=$1 index=$2 tx=$3 target=$4 step current desired expected ruleset live batch pool raw hash
  step=$(dmb_nat66_step "$plan" "$index") || return
  pool=$(jq -ce .pool <<< "$step") || return
  current=$(dmb_nat66_capture "$plan" "$index") || return
  desired=$(jq -cS --arg target "$target" '.[$target]' <<< "$step") || return
  [[ $current != "$desired" ]] || return 0
  if [[ $target == after ]]; then expected=$(jq -cS .before <<< "$step"); else expected=$(jq -cS .after <<< "$step"); fi
  [[ $current == "$expected" ]] || return 76
  ruleset=$(dmb_nft_ruleset) || return
  # Apply refuses mixed ownership. An inverse does not globally adopt any of
  # those resources; it changes only its own known generation.
  [[ $target != after ]] || dmb_nat66_foreign_guard "$ruleset" || return
  live=$(dmb_nat66_from_ruleset "$pool" "$ruleset") || return
  [[ $live == "$current" ]] || return 76
  batch=$(jq -cn --argjson current "$current" --argjson desired "$desired" '{nftables:([
    if $current.present then {delete:{table:{family:"ip6",name:"dmitbox_nat66"}}} else empty end] +
    [if $desired.present then $desired.nftables[]|if has("table") then {create:.} else {add:.} end else empty end])}') || return
  raw=$tx/nat66-$index-batch.json
  hash=$(printf '%s\n' "$batch" | sha256sum); hash=${hash%% *}
  printf '%s\n' "$batch" | dmb_atomic_write "$raw" 0600 "$hash" || return
  dmb_run 8 nft -j -c -f "$raw" && dmb_run 8 nft -j -f "$raw" || return
  [[ $(dmb_nat66_capture "$plan" "$index") == "$desired" ]]
}
dmb_nat66_apply() {
  local step pool path hash marker marker_data
  step=$(dmb_nat66_step "$1" "$2") || return
  pool=$(jq -ce .pool <<< "$step") || return
  if [[ $(jq -er .operation <<< "$step") == enable ]]; then
    path=$(dmb_pool_manifest_path "$(jq -er .id <<< "$pool")") || return
    hash=$(sha256sum -- "$path"); hash=${hash%% *}
    [[ $hash == "$(jq -er .pool_enrollment_sha256 <<< "$step")" ]] || return 76
    [[ $(jq -cS . "$path") == "$(jq -cS .pool <<< "$step")" ]] || return 76
    dmb_nat66_pool_context "$pool" "$(jq -ce .members <<< "$step")" || return
    dmb_nat66_members_committed "$pool" "$(jq -ce .members <<< "$step")" || return
    dmb_nat66_verifier "$1" "$2" "$3" nat66-preflight || return
    # Retained before publication, even if a later probe fails. Conntrack NAT
    # mappings outlive policy deletion; address removal must know this history.
    dmb_trusted_path "$DMB_STATE_DIR/nat66-used" allow_missing || return
    mkdir -p -- "$DMB_STATE_DIR/nat66-used" && chmod 0700 "$DMB_STATE_DIR/nat66-used" || return
    marker=$DMB_STATE_DIR/nat66-used/${3##*/}-$2.json
    marker_data=$(jq -cS '{schema:1,iface:.pool.iface,anchor:.pool.anchor,members:.members}' <<< "$step") || return
    hash=$(printf '%s\n' "$marker_data" | sha256sum); hash=${hash%% *}
    jq -cS --arg hash "$hash" '.+{sha256:$hash}' <<< "$marker_data" | dmb_atomic_write "$marker" 0600 || return
  fi
  dmb_nat66_transition "$1" "$2" "$3" after
}
# Parse two strictly validated direction tuples, never substring-match an IP.
dmb_nat66_flow_count() {
  local anchor=$1 members=$2 text line token src dst original_source reply_destination total=0 src_count dst_count
  local nat66_reported_count='' nat66_parsed_count=0
  text=$(dmb_run 5 conntrack -L -f ipv6 -o extended 2>&1) || return 69
  while IFS= read -r line; do
    [[ -n $line ]] || continue
    if [[ $line =~ ^conntrack\ v[0-9][^:]*:\ ([0-9]+)\ flow\ entries\ have\ been\ shown\.$ ]]; then
      [[ -z $nat66_reported_count ]] || return 69
      nat66_reported_count=${BASH_REMATCH[1]}
      continue
    fi
    src_count=0; dst_count=0; original_source=''; reply_destination=''
    local -a tokens; IFS=' ' read -r -a tokens <<< "$line"
    for token in "${tokens[@]}"; do
      case $token in
        src=*) src=$(dmb_ip_parse "${token#src=}" 6) || return 69; ((src_count+=1)); ((src_count!=1)) || original_source=$src;;
        dst=*) dst=$(dmb_ip_parse "${token#dst=}" 6) || return 69; ((dst_count+=1)); ((dst_count!=2)) || reply_destination=$dst;;
      esac
    done
    ((src_count==2 && dst_count==2)) || return 69
    nat66_parsed_count=$((nat66_parsed_count+1))
    if [[ $original_source == "$anchor" ]] && jq -e --arg address "$reply_destination" 'index($address)!=null' <<< "$members" >/dev/null; then total=$((total+1)); fi
  done <<< "$text"
  [[ -n $nat66_reported_count && $nat66_reported_count == "$nat66_parsed_count" ]] || return 69
  printf '%s\n' "$total"
}
dmb_nat66_verify() {
  local step actual desired pool count start now
  step=$(dmb_nat66_step "$1" "$2") || return
  actual=$(dmb_nat66_capture "$1" "$2") || return; desired=$(jq -cS .after <<< "$step") || return
  [[ $actual == "$desired" ]] || return 76
  pool=$(jq -ce .pool <<< "$step") || return
  if [[ $(jq -er .operation <<< "$step") == enable ]]; then
    dmb_nat66_pool_context "$pool" "$(jq -ce .members <<< "$step")" || return
    dmb_nat66_verifier "$1" "$2" "$3" nat66-outbound
  else
    start=$(dmb_tx_uptime) || return
    while :; do
      count=$(dmb_nat66_flow_count "$(jq -er .anchor <<< "$pool")" "$(jq -ce .members <<< "$step")") || return
      ((count!=0)) || return 0
      now=$(dmb_tx_uptime) || return
      ((now-start<12)) || { dmb_nat66_error 'translated connections remain; keep pool addresses and retry after natural drain'; return; }
      sleep 1
    done
  fi
}
dmb_nat66_restore() { dmb_nat66_transition "$1" "$2" "$3" before; }
dmb_nat66_verify_restore() {
  local current expected
  current=$(dmb_nat66_capture "$1" "$2") || return
  expected=$(jq -cS --argjson i "$2" '.steps[$i].before' "$1") || return
  [[ $current == "$expected" ]]
}
dmb_nat66_pool_removal_check() {
  local iface=$1 address=$2 history count ruleset expected actual
  for history in "$DMB_STATE_DIR"/nat66-used/*.json; do
    [[ -f $history ]] || continue
    dmb_trusted_path "$history" || return
    jq -e '.schema==1 and (.iface|type)=="string" and (.anchor|type)=="string" and (.members|type)=="array" and all(.members[];type=="string") and (.sha256|test("^[a-f0-9]{64}$"))' "$history" >/dev/null || return 76
    expected=$(jq -er .sha256 "$history") || return
    actual=$(jq -cS 'del(.sha256)' "$history" | sha256sum); actual=${actual%% *}
    [[ $actual == "$expected" ]] || return 76
    jq -e --arg iface "$iface" --arg address "$address" '.iface==$iface and (.members|index($address)!=null)' "$history" >/dev/null || continue
    dmb_need nft conntrack || return
    ruleset=$(dmb_nft_ruleset) || return
    if jq -e '.nftables[]|.table? // empty|select(.family=="ip6" and .name=="dmitbox_nat66")' <<< "$ruleset" >/dev/null; then dmb_nat66_error 'disable and drain NAT66 before removing a pool address'; return; fi
    count=$(dmb_nat66_flow_count "$(jq -er .anchor "$history")" "$(jq -cn --arg address "$address" '[$address]')") || return
    ((count==0)) || { dmb_nat66_error 'pool address is retained by translated connections'; return; }
  done
}
# END MODULE adapters/nat66.sh

# BEGIN MODULE adapters/ssh.sh
# SSH service adapter. Only an explicitly enrolled, Port-only include is owned.
# Include/Match files remain byte-for-byte untouched. Socket activation is not
# approximated: enrollment rejects it until a dedicated backend is verified.
# shellcheck shell=bash

dmb_ssh_error() { printf 'ssh: %s\n' "$*" >&2; return 1; }
dmb_ssh_manifest_path() { printf '%s/enrollments/ssh.json\n' "$DMB_STATE_DIR"; }
dmb_ssh_manifest() {
  local IFS=$' \t\n'
  local path; path=$(dmb_ssh_manifest_path) || return 1
  dmb_trusted_path "$path" || return 1
  jq -e '.schema==1 and (.driver=="systemd-service" or .driver=="openrc-service")' "$path" >/dev/null 2>&1 || return 1
  printf '%s\n' "$path"
}
dmb_ssh_config_valid() {
  local IFS=$' \t\n'
  local manifest=$1 config fragment owner driver service binary context
  jq -e '.schema==1 and (.owner_id|test("^[a-f0-9]{32}$")) and
    (.driver=="systemd-service" or .driver=="openrc-service") and
    (.config|type=="string") and (.fragment|type=="string") and
    (.sshd|type=="string") and (.contexts|type=="array" and length>0 and length<=32) and
    all(.contexts[]; (.user|test("^[A-Za-z_][A-Za-z0-9_.-]{0,31}[$]?$")) and
       (.host|test("^[A-Za-z0-9_.:-]+$")) and (.addr|type=="string") and (.laddr|type=="string") and
       (.lport|type=="number" and floor==. and .>0 and .<=65535)) and
    (.confirmation|type=="object")' "$manifest" >/dev/null || return 2
  config=$(jq -er .config "$manifest"); fragment=$(jq -er .fragment "$manifest")
  binary=$(jq -er .sshd "$manifest"); driver=$(jq -er .driver "$manifest"); service=$(jq -er .service "$manifest")
  [[ $config == /etc/ssh/* && $fragment == /etc/ssh/* && $fragment != "$config" ]] || return 2
  dmb_trusted_path "$config" && dmb_trusted_path "$fragment" && dmb_trusted_path "$binary" || return 1
  [[ -f $config && -f $fragment && -x $binary ]] || return 1
  if [[ $driver == systemd-service ]]; then dmb_valid_unit "$service" && [[ $service == *.service ]] || return 2
  else [[ $service =~ ^[A-Za-z0-9_-]{1,64}$ ]] || return 2; fi
  while IFS= read -r context; do
    dmb_ip_parse "$(jq -er .addr <<< "$context")" >/dev/null || return 2
    dmb_ip_parse "$(jq -er .laddr <<< "$context")" >/dev/null || return 2
  done < <(jq -c '.contexts[]' "$manifest")
}
# Conservative Include parser is used only to establish a complete version
# inventory. Native sshd still parses and checks all policy semantics. Ambiguous
# escaping, quoted include paths and relative includes are refused pre-write.
_dmb_ssh_inventory_walk() {
  local IFS=$' \t\n'
  local path=$1 fragment=$2 depth=$3 line key rest pattern found child raw hash mode
  ((depth<32)) || return 78
  [[ ! -v DMB_SSH_VISITED[$path] ]] || return 0
  DMB_SSH_VISITED[$path]=1; ((${#DMB_SSH_VISITED[@]}<=256)) || return 78
  dmb_trusted_path "$path" || return 1
  [[ -f $path ]] || return 1
  if [[ $path != "$fragment" ]]; then
    raw=$(sha256sum "$path") || return 1; hash=${raw%% *}
    mode=$(stat -c '%u:%g:%a' "$path") || return 1
    jq -cn --arg path "$path" --arg hash "$hash" --arg metadata "$mode" '{path:$path,sha256:$hash,metadata:$metadata}' || return 1
  fi
  while IFS= read -r line || [[ -n $line ]]; do
    line=${line%%#*}; read -r key rest <<< "$line"
    [[ ${key,,} == include ]] || continue
    [[ -n $rest && $rest != *[\"\'\\]* ]] || return 78
    local -a patterns=(); read -r -a patterns <<< "$rest"
    for pattern in "${patterns[@]}"; do
      [[ $pattern == /etc/ssh/* && $pattern != *'/../'* && $pattern != */.. ]] || return 78
      # shellcheck disable=SC2053 # Pattern comparison detects wildcard overlap.
      if [[ $fragment == $pattern && $pattern != "$fragment" ]]; then
        dmb_ssh_error 'owned include is also matched by another Include pattern'; return 78
      fi
      found=$(compgen -G "$pattern" | LC_ALL=C sort) || :
      [[ -n $found ]] || continue
      while IFS= read -r child; do _dmb_ssh_inventory_walk "$child" "$fragment" "$((depth+1))" || return; done <<< "$found"
    done
  done < "$path"
}
dmb_ssh_inventory() {
  local IFS=$' \t\n'
  local manifest=$1 config fragment lines
  config=$(jq -er .config "$manifest") || return 1; fragment=$(jq -er .fragment "$manifest") || return 1
  local -A DMB_SSH_VISITED=()
  lines=$(_dmb_ssh_inventory_walk "$config" "$fragment" 0) || return 1
  printf '%s\n' "$lines" | jq -scS 'sort_by(.path)'
}
dmb_ssh_ports() {
  local IFS=$' \t\n'
  local fragment=$1 owner=$2 line key value marker=0 ports='[]'
  while IFS= read -r line || [[ -n $line ]]; do
    [[ $line == "# dmitbox-local:$owner" ]] && marker=$((marker+1))
    line=${line%%#*}; read -r key value <<< "$line"
    [[ -n $key ]] || continue
    [[ ${key,,} == port && $value =~ ^[0-9]{1,5}$ ]] || return 78
    ((10#$value>0 && 10#$value<=65535)) || return 78
    ports=$(jq -c --argjson p "$((10#$value))" '.+[$p]' <<< "$ports") || return 1
  done < "$fragment"
  ((marker==1)) || return 78
  jq -ce 'select(length>0 and length<=16 and (unique|length)==length)|sort' <<< "$ports"
}
dmb_ssh_service_pid() {
  local IFS=$' \t\n'
  local manifest=$1 driver service pid pidfile binary exe hash expected
  driver=$(jq -er .driver "$manifest"); service=$(jq -er .service "$manifest")
  binary=$(jq -er .sshd "$manifest")
  if [[ $driver == systemd-service ]]; then
    pid=$(dmb_run 5 systemctl show "$service" -p MainPID --value) || return
  else
    pidfile=$(jq -er '.pidfile|select(type=="string")' "$manifest") || return 78
    [[ $pidfile == /run/* ]] && dmb_trusted_path "$pidfile" || return 78
    IFS= read -r pid < "$pidfile" || return
  fi
  [[ $pid =~ ^[1-9][0-9]*$ && -d /proc/$pid ]] || return 78
  exe=$(readlink "/proc/$pid/exe") || return
  [[ $exe == "$binary" ]] || { dmb_ssh_error 'enrolled service does not own the SSH daemon'; return 78; }
  hash=$(sha256sum "/proc/$pid/exe"); hash=${hash%% *}
  expected=$(sha256sum "$binary"); expected=${expected%% *}
  [[ $hash == "$expected" ]] || return 76
  printf '%s\n' "$pid"
}
dmb_ssh_service_guard() {
  local IFS=$' \t\n'
  local manifest=$1 driver service triggers
  driver=$(jq -er .driver "$manifest"); service=$(jq -er .service "$manifest")
  if [[ $driver == systemd-service ]]; then
    [[ -d /run/systemd/system ]] || return 78
    dmb_need systemctl || return
    triggers=$(dmb_run 5 systemctl show "$service" -p TriggeredBy --value) || return 1
    [[ -z $triggers ]] || { dmb_ssh_error 'socket-triggered SSH requires an independently verified socket backend'; return 78; }
    dmb_run 5 systemctl -q is-active "$service" || return 1
  else
    [[ ! -d /run/systemd/system ]] && command -v rc-service >/dev/null || return 78
    dmb_run 5 rc-service "$service" status >/dev/null || return 1
    local path comm
    for path in /proc/[0-9]*/comm; do IFS= read -r comm < "$path" || continue
      case $comm in inetd|xinetd) dmb_ssh_error 'inetd-style SSH ownership is unsupported'; return 78;; esac
    done
  fi
  dmb_ssh_service_pid "$manifest" >/dev/null
}

dmb_ssh_effective() {
  local IFS=$' \t\n'
  local manifest=$1 config=$2 context=$3 binary args
  binary=$(jq -er .sshd "$manifest") || return 1
  args=$(jq -er '"user="+.user+",host="+.host+",addr="+.addr+",laddr="+.laddr+",lport="+(.lport|tostring)' <<< "$context") || return 1
  dmb_run 10 "$binary" -T -f "$config" -C "$args"
}
dmb_ssh_effective_policy() {
  local IFS=$' \t\n'
  # Port and ListenAddress change intentionally. All authentication/Match policy
  # must remain identical for each explicitly enrolled connection context.
  LC_ALL=C sed '/^port /d;/^listenaddress /d' | sha256sum | cut -d' ' -f1
}
dmb_ssh_effective_endpoints() {
  local IFS=$' \t\n'
  local output=$1 line key value endpoint address port result='[]'
  while IFS=' ' read -r key value; do
    [[ $key == listenaddress ]] || continue
    endpoint=$(_dmb_confirmation_endpoint "$value") || return 1
    IFS=$'\t' read -r address port <<< "$endpoint"
    address=$(dmb_ip_parse "$address") || return 1
    result=$(jq -c --arg a "$address" --argjson p "$port" '.+[{address:$a,port:$p}]' <<< "$result") || return 1
  done <<< "$output"
  jq -ce 'unique|sort_by(.address,.port)|select(length>0)' <<< "$result"
}
# Native policy simulation changes exactly one explicit anchor in a private copy.
dmb_ssh_simulate() {
  local IFS=$' \t\n'
  local manifest=$1 content=$2 config fragment private line key rest anchors=0 effective context ports policy='' endpoints='' candidate
  config=$(jq -er .config "$manifest"); fragment=$(jq -er .fragment "$manifest")
  private=$(dmb_scratch_tmp) || return 1
  if ! printf '%s' "$content" | base64 -d > "$private/ports.conf"; then rm -rf -- "$private"; return 1; fi
  while IFS= read -r line || [[ -n $line ]]; do
    read -r key rest <<< "${line%%#*}"
    if [[ ${key,,} == include && $rest == "$fragment" ]]; then
      anchors=$((anchors+1)); printf 'Include %s/ports.conf\n' "$private"
    else printf '%s\n' "$line"; fi
  done < "$config" > "$private/sshd_config"
  if ((anchors!=1)); then rm -rf -- "$private"; dmb_ssh_error 'one explicit owned Include anchor in main config is required'; return 78; fi
  local results='[]'
  while IFS= read -r context; do
    effective=$(dmb_ssh_effective "$manifest" "$private/sshd_config" "$context") || { rm -rf -- "$private"; return 1; }
    # The kernel proves peer IP, not a DNS-derived client hostname. In the
    # supported UseDNS=no case sshd uses that numeric peer as Match Host.
    # Refuse a hypothetical hostname context that could hide LocalPort policy.
    if [[ $(awk '$1=="usedns" {print $2}' <<< "$effective") != no ||
          $(jq -er .host <<< "$context") != "$(jq -er .addr <<< "$context")" ]]; then
      rm -rf -- "$private"
      dmb_ssh_error 'port migration requires UseDNS no and a numeric peer-IP Host context; DNS-derived Match Host is unsupported'
      return 78
    fi
    ports=$(awk '$1=="port" {print $2}' <<< "$effective" | jq -sc 'sort|unique') || { rm -rf -- "$private"; return 1; }
    policy=$(dmb_ssh_effective_policy <<< "$effective") || { rm -rf -- "$private"; return 1; }
    endpoints=$(dmb_ssh_effective_endpoints "$effective") || { rm -rf -- "$private"; return 1; }
    candidate=$(jq -cn --argjson c "$context" --argjson p "$ports" --arg hash "$policy" --argjson e "$endpoints" '{context:$c,ports:$p,policy_sha256:$hash,endpoints:$e}') || return 1
    results=$(jq -c --argjson row "$candidate" '.+[$row]' <<< "$results") || return 1
  done < <(jq -c '.contexts[]' "$manifest")
  rm -rf -- "$private" || return 1
  printf '%s\n' "$results"
}
dmb_ssh_enroll() {
  local IFS=$' \t\n'
  local config=$1 inventory owner fragment ports content simulation binary hash pid group binaries helper
  dmb_ssh_config_valid "$config" && dmb_ssh_service_guard "$config" || return
  inventory=$(dmb_ssh_inventory "$config") || return 1
  owner=$(jq -er .owner_id "$config"); fragment=$(jq -er .fragment "$config")
  ports=$(dmb_ssh_ports "$fragment" "$owner") || return 78
  content=$(base64 -w0 "$fragment") || return 1
  simulation=$(dmb_ssh_simulate "$config" "$content") || return
  jq -e --argjson ports "$ports" 'all(.[];.ports==$ports)' <<< "$simulation" >/dev/null || { dmb_ssh_error 'effective Ports are also owned elsewhere'; return 78; }
  binary=$(jq -er .sshd "$config"); hash=$(sha256sum "$binary"); hash=${hash%% *}
  pid=$(dmb_ssh_service_pid "$config") || return
  group=$(_dmb_confirmation_cgroup /proc "$pid") || { dmb_ssh_error 'cannot enroll daemon cgroup identity'; return 78; }
  binaries=$(jq -cn --arg path "$binary" --arg hash "$hash" '[{path:$path,sha256:$hash}]') || return
  # OpenSSH 9.8+ splits authenticated sessions into root-owned native helpers.
  # Pin only known installed paths, never caller-provided arbitrary executables.
  for helper in /usr/lib/openssh/sshd-session /usr/lib/openssh/sshd-auth /usr/lib/ssh/sshd-session /usr/lib/ssh/sshd-auth /usr/libexec/sshd-session /usr/libexec/sshd-auth; do
    [[ -e $helper ]] || continue
    dmb_trusted_path "$helper" && [[ -f $helper && -x $helper ]] || return 78
    hash=$(sha256sum "$helper"); hash=${hash%% *}
    binaries=$(jq -c --arg path "$helper" --arg hash "$hash" '.+[{path:$path,sha256:$hash}]' <<< "$binaries") || return
  done
  hash=$(sha256sum "$binary"); hash=${hash%% *}
  jq -cS --argjson inventory "$inventory" --argjson effective "$simulation" --arg hash "$hash" --arg group "$group" --argjson binaries "$binaries" '. + {inventory:$inventory,effective:$effective,sshd_sha256:$hash} |
    .confirmation.sshd_binaries=$binaries | .confirmation.ssh_cgroups=[$group]' "$config"
}
dmb_ssh_guard() {
  local IFS=$' \t\n'
  local manifest=$1 inventory hash binary
  dmb_ssh_config_valid "$manifest" && dmb_ssh_service_guard "$manifest" || return
  binary=$(jq -er .sshd "$manifest"); hash=$(sha256sum "$binary"); hash=${hash%% *}
  [[ $hash == "$(jq -er .sshd_sha256 "$manifest")" ]] || return 76
  inventory=$(dmb_ssh_inventory "$manifest") || return 1
  [[ $inventory == "$(jq -cS .inventory "$manifest")" ]] || { dmb_ssh_error 'unowned SSH configuration version changed'; return 76; }
}
dmb_ssh_capture() {
  local IFS=$' \t\n'
  local manifest path; manifest=$(dmb_ssh_manifest) || return
  dmb_ssh_guard "$manifest" || return
  path=$(jq -er .fragment "$manifest") || return
  dmb_file_state "$path"
}
dmb_ssh_snapshot() {
  local IFS=$' \t\n'
  local manifest path id
  manifest=$(dmb_ssh_manifest) || return; path=$(jq -er .fragment "$manifest"); id=$(jq -er --argjson i "$2" '.steps[$i].id' "$1")
  dmb_ssh_plan_shape "$1" || return
  if [[ $2 == 1 ]]; then
    dmb_ssh_payload_check "$1" 1 "$manifest" || return
    dmb_ssh_payload_check "$1" 2 "$manifest" || return
    dmb_ssh_firewall_check "$1" "$manifest" || return
  fi
  dmb_file_capture "$path" "$3/snapshots" "$id"
}
dmb_ssh_plan_shape() {
  jq -e '.adapter=="ssh" and .requires_confirmation==true and
    (.confirm_port|type=="number" and floor==. and .>=1 and .<=65535) and
    (.steps|length)==4 and
    [.steps[].adapter]==["nft","ssh","ssh","nft"] and
    (.steps[0].phase//"apply")=="apply" and (.steps[1].phase//"apply")=="apply" and
    .steps[2].phase=="commit" and .steps[3].phase=="commit" and
    .steps[0].resource==.steps[3].resource and .steps[1].resource==.steps[2].resource and
    .steps[0].after==.steps[3].before and .steps[1].after==.steps[2].before and
    .steps[0].nft==.steps[3].nft' "$1" >/dev/null || return 64
}
dmb_ssh_payload_check() (
  local plan=$1 index=$2 manifest=$3 temp field expected contexts native content before_policy after_policy
  dmb_ssh_plan_shape "$plan" || return
  [[ $index == 1 || $index == 2 ]] || return 64
  temp=$(dmb_scratch_tmp) || return
  trap 'rm -rf -- "$temp"' EXIT
  for field in before after; do
    if [[ $index == 1 && $field == before ]]; then contexts=$(jq -c '.contexts' "$manifest") || return
    else contexts=$(jq -c --argjson port "$(jq -r .confirm_port "$plan")" '.contexts|map(.lport=$port)' "$manifest") || return; fi
    expected=$(jq -ceS --argjson i "$index" --arg field "$field" '.steps[$i][($field+"_effective")]' "$plan") || return
    [[ $(jq -cS '[.[].context]' <<< "$expected") == "$(jq -cS . <<< "$contexts")" ]] || return 76
    jq -c --argjson contexts "$contexts" '.contexts=$contexts' "$manifest" > "$temp/context.json" || return
    if [[ $field == before ]]; then content=$(jq -er --argjson i "$index" '.steps[$i].before_content_b64' "$plan") || return
    else content=$(jq -er --argjson i "$index" '.steps[$i].content_b64' "$plan") || return; fi
    native=$(dmb_ssh_simulate "$temp/context.json" "$content" | jq -ceS .) || return
    [[ $native == "$expected" ]] || return 76
    if [[ $field == before ]]; then before_policy=$(jq -c '[.[].policy_sha256]' <<< "$native")
    else after_policy=$(jq -c '[.[].policy_sha256]' <<< "$native"); fi
  done
  [[ $before_policy == "$after_policy" ]] || { dmb_ssh_error 'port payload changes authentication policy for the enrolled context'; return 76; }
  if [[ $index == 2 ]]; then
    jq -e --argjson port "$(jq -r .confirm_port "$plan")" 'all(.[];.ports==[$port] and all(.endpoints[];.port==$port))' <<< "$native" >/dev/null || return 76
  fi
)
dmb_ssh_firewall_check() {
  local plan=$1 manifest=$2 selector before owner endpoints expected actual
  selector=$(jq -ce .steps[0].nft "$plan") || return
  dmb_nft_authorize "$selector" || return
  before=$(jq -ce .steps[0].before "$plan") || return
  owner=$(jq -er .owner_id "$manifest") || return
  local index
  for index in 0 3; do
    if [[ $index == 0 ]]; then endpoints=$(jq -ce '.steps[1].after_effective|map(.endpoints)|unique|select(length==1)|.[0]' "$plan") || return
    else endpoints=$(jq -ce '.steps[2].after_effective|map(.endpoints)|unique|select(length==1)|.[0]' "$plan") || return; fi
    expected=$(dmb_ssh_nft_desired "$selector" "$before" "$endpoints" "$owner" | jq -ceS .) || return
    actual=$(jq -ceS --argjson i "$index" '.steps[$i].after' "$plan") || return
    [[ $actual == "$expected" ]] || return 76
  done
}
dmb_ssh_reload() {
  local IFS=$' \t\n'
  local manifest=$1 driver service binary config
  driver=$(jq -er .driver "$manifest"); service=$(jq -er .service "$manifest")
  binary=$(jq -er .sshd "$manifest"); config=$(jq -er .config "$manifest")
  dmb_run 10 "$binary" -t -f "$config" || return
  if [[ $driver == systemd-service ]]; then dmb_run 15 systemctl reload "$service"
  else dmb_run 15 rc-service "$service" reload; fi
}
dmb_ssh_step_validate() {
  local IFS=$' \t\n'
  local plan=$1 index=$2 manifest=$3 path owner field content state hash temp ports
  dmb_ssh_payload_check "$plan" "$index" "$manifest" || return
  dmb_ssh_firewall_check "$plan" "$manifest" || return
  path=$(jq -er --argjson i "$index" '.steps[$i].path' "$plan") || return 2
  [[ $path == "$(jq -er .fragment "$manifest")" ]] || return 76
  owner=$(jq -er .owner_id "$manifest") || return 2
  jq -e --argjson i "$index" '.steps[$i] | .before.exists==true and .after.exists==true and
    (.before|del(.sha256))==(.after|del(.sha256))' "$plan" >/dev/null || return 2
  temp=$(dmb_scratch_tmp) || return
  for field in before after; do
    if [[ $field == before ]]; then content=$(jq -er --argjson i "$index" '.steps[$i].before_content_b64' "$plan")
    else content=$(jq -er --argjson i "$index" '.steps[$i].content_b64' "$plan"); fi
    if ! printf '%s' "$content" | base64 -d > "$temp/ports"; then rm -rf -- "$temp"; return 2; fi
    ports=$(dmb_ssh_ports "$temp/ports" "$owner") || { rm -rf -- "$temp"; return 2; }
    hash=$(sha256sum "$temp/ports"); hash=${hash%% *}
    state=$(jq -er --argjson i "$index" --arg field "$field" '.steps[$i][$field].sha256' "$plan") || { rm -rf -- "$temp"; return 2; }
    [[ $hash == "$state" ]] || { rm -rf -- "$temp"; return 76; }
    # A typed port-only payload cannot silently weaken auth policy. Policy
    # readback still compares each explicitly enrolled Match context afterward.
  done
  rm -rf -- "$temp"
}
dmb_ssh_apply() {
  local IFS=$' \t\n'
  local manifest; manifest=$(dmb_ssh_manifest) || return
  dmb_ssh_guard "$manifest" || return
  dmb_ssh_step_validate "$1" "$2" "$manifest" || return
  dmb_fs_apply "$@" || return
  dmb_ssh_reload "$manifest"
}
dmb_ssh_verify_field() {
  local IFS=$' \t\n'
  local plan=$1 index=$2 field=$3 manifest expected context effective hash ports endpoints wanted state
  manifest=$(dmb_ssh_manifest) || return; dmb_ssh_guard "$manifest" || return
  expected=$(jq -ceS --argjson i "$index" --arg field "$field" '.steps[$i][$field]' "$plan") || return
  state=$(dmb_ssh_capture "$plan" "$index" | jq -cS .) || return
  [[ $state == "$expected" ]] || return 76
  local config binary
  config=$(jq -er .config "$manifest"); binary=$(jq -er .sshd "$manifest")
  dmb_run 10 "$binary" -t -f "$config" || return
  while IFS= read -r wanted; do
    context=$(jq -ce .context <<< "$wanted")
    effective=$(dmb_ssh_effective "$manifest" "$config" "$context") || return
    hash=$(dmb_ssh_effective_policy <<< "$effective") || return
    ports=$(awk '$1=="port" {print $2}' <<< "$effective" | jq -sc 'sort|unique') || return
    endpoints=$(dmb_ssh_effective_endpoints "$effective") || return
    [[ $hash == "$(jq -er .policy_sha256 <<< "$wanted")" && $ports == "$(jq -c .ports <<< "$wanted")" && $endpoints == "$(jq -c .endpoints <<< "$wanted")" ]] || return 76
  done < <(jq -c --argjson i "$index" --arg field "$field" '.steps[$i][($field+"_effective")][]' "$plan")
  # Effective settings and local listeners are local postconditions only; the
  # transaction remains pending until the separate fresh-login proof succeeds.
  dmb_ssh_listener_check "$manifest" "$endpoints"
}
dmb_ssh_listener_check() {
  local IFS=$' \t\n'
  local manifest=$1 expected=$2 listing state _recv _send local_ep _peer rest endpoint address port observed_endpoints='[]' pid link binary hash enrolled_hash service_pid
  listing=$(dmb_run 5 ss -H -l -n -t -p -O) || return
  binary=$(jq -er .sshd "$manifest"); enrolled_hash=$(jq -er .sshd_sha256 "$manifest")
  service_pid=$(dmb_ssh_service_pid "$manifest") || return
  while IFS= read -r line; do
    read -r state _recv _send local_ep _peer rest <<< "$line"
    [[ $state == LISTEN && $rest == *'"sshd"'* ]] || continue
    [[ $rest =~ pid=([0-9]+) ]] || return 1; pid=${BASH_REMATCH[1]}
    [[ $pid == "$service_pid" ]] || return 76
    link=$(readlink "/proc/$pid/exe") || return
    [[ $link == "$binary" ]] || return 76
    hash=$(sha256sum "/proc/$pid/exe"); hash=${hash%% *}; [[ $hash == "$enrolled_hash" ]] || return 76
    endpoint=$(_dmb_confirmation_endpoint "$local_ep") || return
    IFS=$'\t' read -r address port <<< "$endpoint"; address=$(dmb_ip_parse "$address") || return
    observed_endpoints=$(jq -c --arg a "$address" --argjson p "$port" '.+[{address:$a,port:$p}]' <<< "$observed_endpoints") || return
  done <<< "$listing"
  observed_endpoints=$(jq -c 'unique|sort_by(.address,.port)' <<< "$observed_endpoints") || return
  [[ $observed_endpoints == "$expected" ]] || { dmb_ssh_error 'local SSH socket inventory differs from the intended listeners'; return 76; }
}
dmb_ssh_verify() { dmb_ssh_verify_field "$1" "$2" after; }
dmb_ssh_verify_restore() { dmb_ssh_verify_field "$1" "$2" before; }
dmb_ssh_restore() {
  local IFS=$' \t\n'
  local plan=$1 index=$2 manifest path before current content mode
  manifest=$(dmb_ssh_manifest) || return; dmb_ssh_guard "$manifest" || return
  dmb_ssh_step_validate "$plan" "$index" "$manifest" || return
  path=$(jq -er .fragment "$manifest"); before=$(jq -ceS --argjson i "$index" '.steps[$i].before' "$plan") || return
  current=$(dmb_file_state "$path" | jq -cS .) || return
  if [[ $current != "$before" ]]; then
    [[ $current == "$(jq -ceS --argjson i "$index" '.steps[$i].after' "$plan")" ]] || return 76
    content=$(jq -er --argjson i "$index" '.steps[$i].before_content_b64' "$plan") || return
    mode=$(jq -er '.mode' <<< "$before") || return
    printf '%s' "$content" | base64 -d | dmb_atomic_write "$path" "$mode" "$(jq -er '.sha256' <<< "$before")" "$before" || return
  fi
  dmb_ssh_reload "$manifest" || return
  dmb_ssh_verify_restore "$@"
}

dmb_ssh_nft_desired() {
  local IFS=$' \t\n'
  local selector=$1 current=$2 endpoints=$3 owner=$4 fresh tag
  fresh=$(dmb_nft_plan_state "$selector" "$endpoints" '[]' accept) || return
  tag="dmitbox-local:ssh:$owner"
  jq -cnS --argjson s "$selector" --argjson current "$current" --argjson fresh "$fresh" --arg tag "$tag" '
    [$fresh.nftables[]|.rule? // empty|select(.chain==$s.chain and any(.expr[]; .match?.left.payload?.field=="dport"))|{rule:(.+{comment:$tag})}] as $permits |
    {present:true,nftables:([$current.nftables[]|select(has("table") or has("chain"))]+$permits+
      [$current.nftables[]|select((has("table") or has("chain"))|not)|select(.rule?.comment!=$tag)])}'
}
dmb_ssh_plan_port() {
  local IFS=$' \t\n'
  local port=$1 manifest nft_manifest old_ports stage_ports owner fragment before_content stage_content final_content
  local before stage final before_effective stage_effective final_effective selector nft_before nft_stage nft_final origin endpoints context_dir
  [[ $port =~ ^[0-9]{1,5}$ ]] && ((10#$port>0 && 10#$port<=65535)) || return 64
  port=$((10#$port)); manifest=$(dmb_ssh_manifest) || return
  dmb_ssh_guard "$manifest" || return
  # A separate ban manager may synthesize its own netfilter ownership and port
  # policy. Do not silently leave that policy on the retired listener.
  local proc comm
  for proc in /proc/[0-9]*/comm; do IFS= read -r comm < "$proc" || continue
    [[ $comm != fail2ban-server ]] || { dmb_ssh_error 'active fail2ban requires a dedicated coordinated jail adapter'; return 78; }
  done
  owner=$(jq -er .owner_id "$manifest"); fragment=$(jq -er .fragment "$manifest")
  old_ports=$(dmb_ssh_ports "$fragment" "$owner") || return
  jq -e --argjson p "$port" 'index($p)==null' <<< "$old_ports" >/dev/null || { dmb_ssh_error 'requested port is already configured'; return 64; }
  before_content=$(base64 -w0 "$fragment") || return
  stage_ports=$(jq -c --argjson p "$port" '.+[$p]|sort' <<< "$old_ports") || return
  stage_content=$({ printf '# dmitbox-local:%s\n' "$owner"; jq -r '.[]|"Port "+tostring' <<< "$stage_ports"; } | base64 -w0) || return
  final_content=$(printf '# dmitbox-local:%s\nPort %s\n' "$owner" "$port" | base64 -w0) || return
  before=$(dmb_file_state "$fragment" | jq -cS .) || return
  before_effective=$(dmb_ssh_simulate "$manifest" "$before_content") || return
  context_dir=$(dmb_scratch_tmp) || return
  if ! jq --argjson port "$port" '.contexts |= map(.lport=$port)' "$manifest" > "$context_dir/manifest.json"; then rm -rf -- "$context_dir"; return 1; fi
  stage_effective=$(dmb_ssh_simulate "$context_dir/manifest.json" "$stage_content") || { rm -rf -- "$context_dir"; return 1; }
  final_effective=$(dmb_ssh_simulate "$context_dir/manifest.json" "$final_content") || { rm -rf -- "$context_dir"; return 1; }
  rm -rf -- "$context_dir" || return
  jq -e --argjson old "$before_effective" --argjson stage "$stage_ports" --argjson p "$port" '
    all(to_entries[]; . as $entry | .value.ports==[$p] and
      .value.policy_sha256==$old[$entry.key].policy_sha256 and
      all(.value.endpoints[];.port==$p))' <<< "$final_effective" >/dev/null || { dmb_ssh_error 'final effective policy/listeners cannot be proven to preserve the enrolled context'; return 78; }
  jq -e --argjson old "$before_effective" --argjson ports "$stage_ports" 'all(to_entries[];. as $e|.value.ports==$ports and .value.policy_sha256==$old[$e.key].policy_sha256)' <<< "$stage_effective" >/dev/null || return 78
  endpoints=$(jq -ce 'map(.endpoints)|unique|select(length==1)|.[0]' <<< "$stage_effective") || return 78
  # Any listener already in use by another service prevents mutation. Existing
  # SSH listeners are allowed only if they are part of enrolled effective state.
  dmb_ssh_listener_check "$manifest" "$(jq -ce 'map(.endpoints)|unique|select(length==1)|.[0]' <<< "$before_effective")" || return
  local occupied
  occupied=$(dmb_run 5 ss -H -l -n -t -O "sport = :$port") || return
  [[ -z $occupied ]] || { dmb_ssh_error 'target port is already bound'; return 78; }
  stage=$(jq -cnS --argjson before "$before" --arg hash "$(printf '%s' "$stage_content" | base64 -d | sha256sum | cut -d' ' -f1)" '$before+{sha256:$hash}') || return
  final=$(jq -cnS --argjson before "$before" --arg hash "$(printf '%s' "$final_content" | base64 -d | sha256sum | cut -d' ' -f1)" '$before+{sha256:$hash}') || return
  nft_manifest=$(dmb_nft_enrollment_path) || return; dmb_trusted_path "$nft_manifest" || return
  selector=$(jq -ce '.nft' "$nft_manifest") || return
  nft_before=$(dmb_nft_capture <(jq -cn --argjson s "$selector" '{steps:[{nft:$s}]}') 0) || return
  [[ $(jq -r .present <<< "$nft_before") == true ]] || { dmb_ssh_error 'enroll and establish a scoped nft policy before migrating SSH'; return 78; }
  nft_stage=$(dmb_ssh_nft_desired "$selector" "$nft_before" "$endpoints" "$owner") || return
  nft_final=$(dmb_ssh_nft_desired "$selector" "$nft_before" "$(jq -ce '.[0].endpoints' <<< "$final_effective")" "$owner") || return
  origin=$(dmb_confirmation_origin "$manifest") || { dmb_ssh_error 'start from a provable authenticated SSH transport or explicitly enrolled OOB console'; return 78; }
  jq -cnS --argjson s "$selector" --arg path "$fragment" --argjson before "$before" --argjson stage "$stage" --argjson final "$final" \
    --arg bc "$before_content" --arg sc "$stage_content" --arg fc "$final_content" --argjson be "$before_effective" --argjson se "$stage_effective" --argjson fe "$final_effective" \
    --argjson nb "$nft_before" --argjson ns "$nft_stage" --argjson nf "$nft_final" --argjson origin "$origin" --argjson port "$port" --argjson allow_console "$(jq -c '.confirmation.allow_console_confirmation==true' "$manifest")" '
    ("nft-"+$s.family+"-"+$s.table) as $nr |
    {schema:1,adapter:"ssh",resources:["ssh-service",$nr],timeout_seconds:300,origin_transport:$origin,confirm_port:$port,confirmation_enrollment:"ssh",requires_confirmation:true,allow_console_confirmation:$allow_console,
    steps:[
      {id:"ssh-firewall-stage",adapter:"nft",resource:$nr,nft:$s,before:$nb,after:$ns,restore_rank:-10},
      {id:"ssh-listener-stage",adapter:"ssh",resource:"ssh-service",path:$path,before:$before,after:$stage,before_content_b64:$bc,content_b64:$sc,before_effective:$be,after_effective:$se,restore_rank:10},
      {id:"ssh-listener-final",phase:"commit",adapter:"ssh",resource:"ssh-service",path:$path,before:$stage,after:$final,before_content_b64:$sc,content_b64:$fc,before_effective:$se,after_effective:$fe,restore_rank:10},
      {id:"ssh-firewall-final",phase:"commit",adapter:"nft",resource:$nr,nft:$s,before:$ns,after:$nf,restore_rank:-10}]}'
}
# END MODULE adapters/ssh.sh

# BEGIN MODULE adapters/runtime.sh
# shellcheck shell=bash
# Opt-in runtime tuning and local maintenance. No command installs dependencies.
dmb_tcp_report() {
  dmb_need jq sysctl || return
  local current available qdisc
  current=$(dmb_run 3 sysctl -n net.ipv4.tcp_congestion_control) || return
  available=$(dmb_run 3 sysctl -n net.ipv4.tcp_available_congestion_control) || return
  qdisc=$(dmb_run 3 sysctl -n net.core.default_qdisc) || return
  jq -cn --arg current "$current" --arg available "$available" --arg qdisc "$qdisc" '{schema:1,current:$current,available:($available|split(" ")|map(select(length>0))),default_qdisc:$qdisc,performance:"unmeasured"}'
}
dmb_tcp_measure_request() {
  local file=$1 target port seconds
  [[ -f $file && ! -L $file ]] || return 64
  jq -e '.schema==1 and .requested==true and (.target|type=="string") and (.port|type=="number" and floor==. and .>=1 and .<=65535) and (.seconds|type=="number" and floor==. and .>=2 and .<=10) and ((.min_bits_per_second // 0)|type=="number" and .>=0)' "$file" >/dev/null || return 64
  target=$(jq -er .target "$file") || return
  # A numeric target prevents implicit DNS requests and shell/option ambiguity.
  target=$(dmb_ip_parse "$target") || return 64
  port=$(jq -r .port "$file"); seconds=$(jq -r .seconds "$file")
  jq -cS --arg target "$target" '.target=$target|{schema,requested,target,port,seconds,min_bits_per_second:(.min_bits_per_second // 0)}' "$file"
}
dmb_tcp_persistent_owner_free() {
  local own=$1 file
  [[ ! -e $own && ! -L $own ]] || { dmb_error 'Existing TCP profile needs explicit ownership enrollment'; return 78; }
  for file in /etc/sysctl.conf /etc/sysctl.d/*.conf /run/sysctl.d/*.conf /usr/local/lib/sysctl.d/*.conf /usr/lib/sysctl.d/*.conf /lib/sysctl.d/*.conf; do
    [[ -f $file ]] || continue
    if LC_ALL=C grep -Eq '^[[:space:]]*-?net[./]ipv4[./]tcp_congestion_control[[:space:]]*=' "$file"; then dmb_error "Competing persistent TCP owner: $file"; return 78; fi
  done
}
dmb_tcp_plan() {
  local profile=${1-} request_file=${2-} scope=${3:-runtime} request value current step steps conf content desired
  dmb_need jq sysctl iperf3 || return
  [[ $scope == runtime || $scope == persistent ]] || return 64
  case "$profile" in bbr) value=bbr;; cubic) value=cubic;; *) dmb_error 'Supported measured TCP profiles: bbr, cubic'; return 64;; esac
  request=$(dmb_tcp_measure_request "$request_file") || return
  current=$(dmb_run 3 sysctl -n net.ipv4.tcp_available_congestion_control) || return
  [[ " $current " == *" $value "* ]] || { dmb_error 'Requested algorithm is not already available; load modules explicitly outside this tool'; return 78; }
  step=$(jq -cn --arg value "$value" --argjson request "$request" '{id:"tcp-congestion-control",adapter:"tcp",resource:"sysctl:net.ipv4.tcp_congestion_control",key:"net.ipv4.tcp_congestion_control",measurement:$request,after:{value:$value}}') || return
  steps=$(jq -cn --argjson step "$step" '[$step]') || return
  if [[ $scope == persistent ]]; then
    conf=/etc/sysctl.d/90-dmitbox-local-tcp.conf
    dmb_tcp_persistent_owner_free "$conf" || return
    # Build in a private local workspace only when persistent planning is explicit.
    # No privileged config is written; the resulting fs step owns its new file.
    dmb_require_root || return
    dmb_trusted_path /etc/sysctl.d || return
    content=$(mktemp) || return
    printf '# dmitbox-local profile schema=1\nnet.ipv4.tcp_congestion_control = %s\n' "$value" > "$content" || { rm -f -- "$content"; return 74; }
    desired=$(dmb_file_desired "$conf" "$content" 600) || { rm -f -- "$content"; return; }
    local encoded
    encoded=$(base64 -w0 -- "$content") || { rm -f -- "$content"; return 74; }
    rm -f -- "$content" || return
    steps=$(jq -cn --argjson step "$step" --arg path "$conf" --arg content "$encoded" --argjson desired "$desired" '[{id:"tcp-persistent",adapter:"fs",purpose:"tcp-profile",resource:("file:"+$path),path:$path,content_b64:$content,after:$desired},$step]') || return
  fi
  jq -cn --argjson steps "$steps" --arg scope "$scope" '{schema:1,adapter:"tcp",scope:$scope,timeout_seconds:300,resources:[$steps[].resource],steps:$steps}'
}
dmb_tcp_step() { jq -ce --argjson i "$2" '.steps[$i]|select(.key=="net.ipv4.tcp_congestion_control")' "$1"; }
dmb_tcp_capture() {
  local step key value
  step=$(dmb_tcp_step "$1" "$2") || return 64
  key=$(jq -r .key <<< "$step")
  value=$(dmb_run 3 sysctl -n "$key") || return
  [[ $value =~ ^[A-Za-z0-9_-]{1,32}$ ]] || return 78
  jq -cn --arg value "$value" '{value:$value}'
}
dmb_tcp_probe() {
  local request=$1 target port seconds result min
  [[ $(jq -r '.requested' <<< "$request") == true ]] || return 64
  target=$(jq -er .target <<< "$request") || return
  target=$(dmb_ip_parse "$target") || return 64
  port=$(jq -er .port <<< "$request") || return
  seconds=$(jq -er .seconds <<< "$request") || return
  [[ $port =~ ^[0-9]+$ && $seconds =~ ^[0-9]+$ ]] && ((port>=1 && port<=65535 && seconds>=2 && seconds<=10)) || return 64
  result=$(dmb_run "$((seconds+8))" iperf3 -J -c "$target" -p "$port" -t "$seconds" --connect-timeout 3000) || { dmb_error 'Requested throughput probe failed or was blocked; performance is inconclusive'; return 69; }
  min=$(jq -r '.min_bits_per_second // 0' <<< "$request") || return
  jq -ce --argjson minimum "$min" 'select(.error==null)|.end.sum_received.bits_per_second as $rate|select(($rate|type)=="number" and $rate>0 and $rate>=$minimum)|{schema:1,bits_per_second:$rate,source:"iperf3",minimum:$minimum}' <<< "$result" || { dmb_error 'Throughput postcondition was not proved'; return 69; }
}
dmb_tcp_snapshot() {
  local step result
  step=$(dmb_tcp_step "$1" "$2") || return
  result=$(dmb_tcp_probe "$(jq -c .measurement <<< "$step")") || return
  printf '%s\n' "$result" | dmb_atomic_write "$3/snapshots/tcp-$2-baseline.json" 0600
}
dmb_tcp_set() {
  local key=$1 value=$2 available
  [[ $key == net.ipv4.tcp_congestion_control && $value =~ ^[A-Za-z0-9_-]{1,32}$ ]] || return 64
  available=$(dmb_run 3 sysctl -n net.ipv4.tcp_available_congestion_control) || return
  [[ " $available " == *" $value "* ]] || return 78
  dmb_run 3 sysctl -w "$key=$value" >/dev/null
}
dmb_tcp_apply() {
  local step before current
  step=$(dmb_tcp_step "$1" "$2") || return
  before=$(jq -cS .before <<< "$step"); current=$(dmb_tcp_capture "$1" "$2" | jq -cS .) || return
  [[ $current == "$before" ]] || return 76
  dmb_tcp_set "$(jq -r .key <<< "$step")" "$(jq -r .after.value <<< "$step")"
}
dmb_tcp_verify() {
  local step current expected result baseline
  step=$(dmb_tcp_step "$1" "$2") || return
  current=$(dmb_tcp_capture "$1" "$2" | jq -cS .) || return
  expected=$(jq -cS .after <<< "$step"); [[ $current == "$expected" ]] || return 76
  result=$(dmb_tcp_probe "$(jq -c .measurement <<< "$step")") || return
  baseline=$(jq -ce . "$3/snapshots/tcp-$2-baseline.json") || return
  jq -cn --argjson baseline "$baseline" --argjson after "$result" '{schema:1,baseline:$baseline,after:$after,ratio:($after.bits_per_second/$baseline.bits_per_second),claim:"Measured throughput for the requested target; no general performance guarantee"}' | dmb_atomic_write "$3/snapshots/tcp-$2-after.json" 0600
}
dmb_tcp_restore() {
  local step current before after
  step=$(dmb_tcp_step "$1" "$2") || return
  current=$(dmb_tcp_capture "$1" "$2" | jq -cS .) || return
  before=$(jq -cS .before <<< "$step"); after=$(jq -cS .after <<< "$step")
  [[ $current != "$before" ]] || return 0
  [[ $current == "$after" ]] || return 76
  dmb_tcp_set "$(jq -r .key <<< "$step")" "$(jq -r .before.value <<< "$step")" || return
  [[ $(dmb_tcp_capture "$1" "$2" | jq -cS .) == "$before" ]]
}

# Swap creation never overwrites a resource. Private staging and the final hard
# link must reside on the same ext4/XFS filesystem; activation is a separate step.
dmb_swap_report() {
  dmb_need swapon jq || return
  local report
  report=$(dmb_run 3 swapon --show --json --bytes --output NAME,TYPE,SIZE,USED,PRIO) || return
  jq -ceS 'select((.swapdevices|type)=="array" and all(.swapdevices[]; (.name|type)=="string" and (.prio|type)=="number" and (.prio|floor)==.prio))' <<< "$report"
}
dmb_swap_step() {
  jq -ce --argjson i "$2" '.steps[$i]|select(
    (.operation=="create" or .operation=="activate") and
    (.owner_id|type=="string" and test("^[a-f0-9]{32}$")) and
    (.path|type=="string" and startswith("/") and (test("[[:space:]]")|not)) and
    (.filesystem=="ext4" or .filesystem=="xfs") and
    (.after.exists==true and .after.type=="file" and .after.uid==0 and .after.gid==0 and .after.mode=="600" and .after.nlink==1) and
    (.after.size_bytes|type=="number" and floor==. and .>=16777216 and .<=1099511627776 and .%1048576==0) and
    (.after.swap_uuid|type=="string" and test("^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$")) and
    (if .operation=="create" then .after.active==false and .after.priority==null else .after.active==true and (.after.priority|type=="number" and floor==. and .>=0 and .<=32767) end)
  )' "$1"
}
dmb_swap_path_valid() {
  local path=${1-} parent
  [[ $path == /* && $path != / && $path != */ && $path != *[[:space:]]* && $path != *'//'* && $path != *'/../'* && $path != */.. && $path != *'/./'* && $path != */. ]] || return 64
  parent=${path%/*}; [[ -n $parent ]] || parent=/
  dmb_trusted_path "$parent" || return
  [[ ! -L $path ]] || return 78
}
dmb_swap_filesystem() {
  local path=$1 json fstype options
  json=$(dmb_run 3 findmnt --json --target "$path" --output FSTYPE,OPTIONS) || return
  [[ $(jq '.filesystems|length' <<< "$json") == 1 ]] || return 78
  fstype=$(jq -er '.filesystems[0].fstype' <<< "$json") || return
  options=$(jq -er '.filesystems[0].options' <<< "$json") || return
  [[ $fstype == ext4 || $fstype == xfs ]] || { dmb_error 'Swap creation supports verified local ext4/XFS only'; return 78; }
  [[ ,$options, != *,ro,* ]] || return 78
  printf '%s\n' "$fstype"
}
dmb_swap_capacity() {
  local path=$1 bytes=$2 blocks blocksize data
  data=$(dmb_run 3 stat -f -c '%a %S' -- "$path") || return
  read -r blocks blocksize <<< "$data"
  [[ $blocks =~ ^[0-9]{1,15}$ && $blocksize =~ ^[1-9][0-9]{0,8}$ ]] || return 78
  ((blocks <= 9223372036854775807 / blocksize)) || return 78
  # Reserve room for recovery journals; concurrent writes can still exhaust a
  # filesystem, so rollback first removes verified private staging allocations.
  ((blocks*blocksize >= bytes+67108864)) || { dmb_error 'Insufficient free space plus recovery reserve'; return 78; }
}
dmb_swap_plan_create() {
  local path=${1-} mib=${2-} priority=${3-} parent filesystem owner uuid bytes logical
  dmb_need jq findmnt stat fallocate mkswap swapon swapoff blkid ln sync || return
  dmb_require_root || return
  dmb_swap_path_valid "$path" || return
  [[ ! -e $path && ! -L $path ]] || { dmb_error 'Refusing pre-existing swap path'; return 78; }
  [[ $mib =~ ^[1-9][0-9]{0,6}$ && $priority =~ ^[0-9]{1,5}$ ]] && ((mib>=16 && mib<=1048576 && priority<=32767)) || return 64
  parent=${path%/*}; [[ -n $parent ]] || parent=/
  filesystem=$(dmb_swap_filesystem "$parent") || return
  owner=$(od -An -N16 -tx1 /dev/urandom | tr -d ' \n') || return
  uuid=${owner:0:8}-${owner:8:4}-${owner:12:4}-${owner:16:4}-${owner:20:12}
  bytes=$((mib*1024*1024))
  dmb_swap_capacity "$parent" "$bytes" || return
  logical=$(jq -cn --arg uuid "$uuid" --argjson bytes "$bytes" '{exists:true,type:"file",size_bytes:$bytes,uid:0,gid:0,mode:"600",nlink:1,swap_uuid:$uuid,active:false,priority:null}') || return
  jq -cn --arg path "$path" --arg owner "$owner" --arg fs "$filesystem" --argjson logical "$logical" --argjson priority "$priority" '{schema:1,adapter:"swap",scope:"runtime",timeout_seconds:300,resources:[("swap:"+$path)],steps:[{id:"swap-create",resource:("swap:"+$path),adapter:"swap",operation:"create",path:$path,owner_id:$owner,filesystem:$fs,after:$logical},{id:"swap-activate",resource:("swap:"+$path),adapter:"swap",operation:"activate",path:$path,owner_id:$owner,filesystem:$fs,after:($logical+{active:true,priority:$priority})}],limitations:["Runtime activation only; no fstab editing","Creation requires transaction state and target on the same filesystem","Swapoff can fail under memory pressure; such rollback is reported failed"]}'
}
dmb_swap_capture() {
  local step path uuid active=false priority=null row size uid gid mode nlink
  step=$(dmb_swap_step "$1" "$2") || return
  path=$(jq -er .path <<< "$step") || return
  dmb_swap_path_valid "$path" || return
  if [[ ! -e $path ]]; then printf '{"exists":false}\n'; return; fi
  [[ -f $path && ! -L $path ]] || return 78
  size=$(stat -c %s -- "$path"); uid=$(stat -c %u -- "$path"); gid=$(stat -c %g -- "$path"); mode=$(stat -c %a -- "$path"); nlink=$(stat -c %h -- "$path")
  uuid=$(dmb_run 3 blkid -p -s UUID -o value -- "$path") || return 78
  [[ $(dmb_run 3 blkid -p -s TYPE -o value -- "$path") == swap ]] || return 78
  row=$(dmb_swap_report | jq -c --arg path "$path" '[.swapdevices[]?|select(.name==$path)]') || return
  [[ $(jq length <<< "$row") -le 1 ]] || return 78
  if [[ $(jq length <<< "$row") == 1 ]]; then active=true; priority=$(jq -r '.[0].prio' <<< "$row"); [[ $priority =~ ^-?[0-9]+$ ]] || return 78; fi
  jq -cn --argjson size "$size" --argjson uid "$uid" --argjson gid "$gid" --arg mode "$mode" --argjson nlink "$nlink" --arg uuid "$uuid" --argjson active "$active" --argjson priority "$priority" '{exists:true,type:"file",size_bytes:$size,uid:$uid,gid:$gid,mode:$mode,nlink:$nlink,swap_uuid:$uuid,active:$active,priority:$priority}'
}
dmb_swap_record_path() { local step; step=$(dmb_swap_step "$1" "$2") || return; printf '%s/snapshots/swap-%s.json\n' "$3" "$(jq -er .owner_id <<< "$step")"; }
dmb_swap_identity_check() {
  local path=$1 record=$2 expected actual
  dmb_trusted_path "$record" || return
  expected=$(jq -er .identity "$record") || return
  [[ -f $path && ! -L $path && $(stat -c '%u:%g:%a' -- "$path") == 0:0:600 ]] || return 76
  actual=$(stat -c '%d:%i' -- "$path") || return
  [[ $actual == "$expected" ]] || return 76
}
dmb_swap_apply() {
  local plan=$1 i=$2 tx=$3 step path parent operation before current record stage identity bytes filesystem context
  step=$(dmb_swap_step "$plan" "$i") || return
  path=$(jq -er .path <<< "$step"); operation=$(jq -er .operation <<< "$step")
  parent=${path%/*}; [[ -n $parent ]] || parent=/
  current=$(dmb_swap_capture "$plan" "$i" | jq -cS .) || return
  before=$(jq -cS .before <<< "$step"); [[ $current == "$before" ]] || return 76
  record=$(dmb_swap_record_path "$plan" "$i" "$tx") || return
  if [[ $operation == activate ]]; then
    dmb_swap_identity_check "$path" "$record" || return
    dmb_run 10 swapon --priority "$(jq -r .after.priority <<< "$step")" -- "$path"
    return
  fi
  [[ $(jq -r '.before.exists' <<< "$step") == false ]] || return 78
  dmb_trusted_path "$tx/snapshots" || return
  [[ $(stat -c %d -- "$parent") == "$(stat -c %d -- "$tx/snapshots")" ]] || { dmb_error 'Swap staging and target must share a filesystem'; return 78; }
  filesystem=$(dmb_swap_filesystem "$parent") || return
  [[ $filesystem == "$(jq -r .filesystem <<< "$step")" ]] || return 76
  bytes=$(jq -r .after.size_bytes <<< "$step")
  dmb_swap_capacity "$parent" "$bytes" || return
  stage="$tx/snapshots/swap-$(jq -r .owner_id <<< "$step").stage"
  # The engine owns this private directory from PREPARED; an unexpected stage
  # is never truncated. A killed write remains confined to this known slot.
  [[ ! -e $stage && ! -L $stage && ! -e $record ]] || return 76
  ( umask 077; set -o noclobber; : > "$stage" ) || return
  identity=$(stat -c '%d:%i' -- "$stage") || return
  jq -cn --arg identity "$identity" --arg path "$path" --arg stage "$stage" --arg owner "$(jq -r .owner_id <<< "$step")" '{schema:1,identity:$identity,path:$path,stage:$stage,owner_id:$owner}' | dmb_atomic_write "$record" 0600 || return
  bytes=$(jq -r .after.size_bytes <<< "$step")
  [[ $bytes =~ ^[0-9]+$ ]] && ((bytes>=16777216 && bytes<=1099511627776)) || return 64
  dmb_run 15 fallocate -l "$bytes" -- "$stage" || return
  [[ $(stat -c %s -- "$stage") == "$bytes" ]] || return 74
  (( $(stat -c %b -- "$stage") * 512 >= bytes )) || { dmb_error 'Swap allocation contains holes'; return 78; }
  dmb_run 5 mkswap --uuid "$(jq -r .after.swap_uuid <<< "$step")" -- "$stage" >/dev/null || return
  # A security label must match the final path before the inode is linked.
  if command -v getenforce >/dev/null 2>&1 && [[ $(getenforce) != Disabled ]]; then
    dmb_need matchpathcon chcon || return
    context=$(matchpathcon -n -- "$path") || return
    dmb_run 3 chcon "$context" "$stage" || return
    [[ $(stat -c %C -- "$stage") == "$context" ]] || return 78
  fi
  sync -f "$stage" || return
  # Atomic no-replace creation; unrelated files and links are never overwritten.
  ln -T -- "$stage" "$path" || return
  rm -- "$stage" || return
  sync -f "$parent" || return
  dmb_swap_identity_check "$path" "$record"
}
dmb_swap_verify() {
  local current expected record path
  current=$(dmb_swap_capture "$1" "$2" | jq -cS .) || return
  expected=$(jq -cS --argjson i "$2" '.steps[$i].after' "$1") || return
  [[ $current == "$expected" ]] || return 76
  record=$(dmb_swap_record_path "$1" "$2" "$3") || return
  path=$(jq -er --argjson i "$2" '.steps[$i].path' "$1") || return
  dmb_swap_identity_check "$path" "$record"
}
dmb_swap_restore() {
  local step current before after path parent operation record
  step=$(dmb_swap_step "$1" "$2") || return
  path=$(jq -er .path <<< "$step"); operation=$(jq -er .operation <<< "$step")
  parent=${path%/*}; [[ -n $parent ]] || parent=/
  current=$(dmb_swap_capture "$1" "$2" | jq -cS .) || return
  before=$(jq -cS .before <<< "$step"); after=$(jq -cS .after <<< "$step")
  [[ $current != "$before" ]] || return 0
  [[ $current == "$after" ]] || return 76
  record=$(dmb_swap_record_path "$1" "$2" "$3") || return
  dmb_swap_identity_check "$path" "$record" || return
  if [[ $operation == activate ]]; then dmb_run 15 swapoff -- "$path" || return
  else
    [[ $(jq -r .active <<< "$current") == false && $(stat -c %h -- "$path") == 1 ]] || return 76
    rm -- "$path" || return
    sync -f "$parent" || return
  fi
  [[ $(dmb_swap_capture "$1" "$2" | jq -cS .) == "$before" ]]
}
dmb_swap_cleanup() {
  local step stage record path
  step=$(dmb_swap_step "$1" "$2") || return
  [[ $(jq -r .operation <<< "$step") == create ]] || return 0
  stage="$3/snapshots/swap-$(jq -r .owner_id <<< "$step").stage"
  record=$(dmb_swap_record_path "$1" "$2" "$3") || return
  [[ -e $stage || -L $stage ]] || return 0
  # The stage is always inside the private engine-owned snapshot directory.
  # If a crash preceded the identity record, only an empty regular slot with
  # one link and no activation can be discarded; larger unknown files conflict.
  if [[ ! -e $record ]]; then
    [[ -f $stage && ! -L $stage && $(stat -c '%s:%h:%u:%a' -- "$stage") == 0:1:0:600 ]] || return 76
  else
    [[ $(jq -er .path "$record") == "$(jq -r .path <<< "$step")" && $(jq -er .stage "$record") == "$stage" && $(jq -er .owner_id "$record") == "$(jq -r .owner_id <<< "$step")" ]] || return 76
    dmb_swap_identity_check "$stage" "$record" || return
  fi
  local active_name encoded active_identity stage_identity swap_report
  swap_report=$(dmb_swap_report) || return
  stage_identity=$(stat -c '%d:%i' -- "$stage") || return
  while IFS= read -r encoded; do
    active_name=$(printf '%s' "$encoded" | base64 -d) || return
    active_identity=$(stat -c '%d:%i' -- "$active_name") || return 76
    [[ $active_identity != "$stage_identity" ]] || return 76
  done < <(jq -r '.swapdevices[]|.name|@base64' <<< "$swap_report")
  path=$(jq -er .path <<< "$step") || return
  if [[ -e $path && $(stat -c '%d:%i' -- "$path") == "$(stat -c '%d:%i' -- "$stage")" ]]; then
    # Complete the interrupted link/unlink boundary only while inactive and
    # exactly matching our recorded UUID. Never unlink an active swap inode.
    [[ $(dmb_swap_report | jq --arg path "$path" '[.swapdevices[]?|select(.name==$path)]|length') == 0 ]] || return 76
    [[ $(dmb_run 3 blkid -p -s UUID -o value -- "$path") == "$(jq -r .after.swap_uuid <<< "$step")" ]] || return 76
    rm -- "$path" || return
  fi
  rm -- "$stage" || return
  sync -f "$3/snapshots"
}

# Explicit package maintenance is intentionally outside compensating network
# transactions: package upgrades have no honest generic inverse.
dmb_runtime_capture() {
  local seconds=$1 executable=$2 output rc=0; shift 2
  if ! command -v "$executable" >/dev/null 2>&1; then jq -cn --arg name "$executable" '{available:false,command:$name,exit_code:69,output:"Missing dependency; no installation attempted"}'; return; fi
  output=$(dmb_run "$seconds" "$executable" "$@" 2>&1) || rc=$?
  jq -cn --arg name "$executable" --arg output "$output" --argjson rc "$rc" '{available:true,command:$name,exit_code:$rc,output:$output}'
}
dmb_maintenance_report() {
  dmb_need jq || return
  local family=${1:-system} manager=none name first second third
  case "$family" in
    system)
      for name in apt-get dnf yum pacman apk; do if command -v "$name" >/dev/null 2>&1; then manager=$name; break; fi; done
      jq -cn --arg kernel "$(uname -r)" --arg machine "$(uname -m)" --arg manager "$manager" --arg uptime "$(cut -d' ' -f1 /proc/uptime)" '{schema:1,kernel:$kernel,machine:$machine,package_manager:$manager,uptime_seconds:$uptime,network_probes:false}';;
    resources)
      first=$(dmb_runtime_capture 5 free -b) || return
      second=$(dmb_runtime_capture 5 df -P -B1) || return
      third=$(dmb_runtime_capture 5 ps -eo pid,user,pcpu,pmem,comm) || return
      jq -cn --argjson memory "$first" --argjson filesystems "$second" --argjson processes "$third" '{schema:1,family:"resources",memory:$memory,filesystems:$filesystems,processes:$processes,network_probes:false}';;
    ports)
      first=$(dmb_runtime_capture 5 ss -lntup) || return
      second=$(dmb_runtime_capture 5 ss -s) || return
      jq -cn --argjson listeners "$first" --argjson sockets "$second" '{schema:1,family:"ports",listeners:$listeners,sockets:$sockets,external_accessibility:"unverified",network_probes:false}';;
    security)
      first=$(dmb_runtime_capture 5 fail2ban-client status) || return
      second=$(dmb_runtime_capture 5 fail2ban-client status sshd) || return
      third=$(dmb_runtime_capture 5 ss -lntp) || return
      jq -cn --argjson f2b "$first" --argjson jail "$second" --argjson sockets "$third" '{schema:1,family:"security",fail2ban:$f2b,sshd_jail:$jail,listeners:$sockets,authentication_policy:"Use enrolled SSH context report",external_accessibility:"unverified",network_probes:false}';;
    guest)
      first=$(dmb_runtime_capture 5 systemd-detect-virt) || return
      second=$(dmb_runtime_capture 5 systemctl show qemu-guest-agent.service cloud-init.service --property=Id,LoadState,ActiveState,UnitFileState) || return
      jq -cn --argjson virtualization "$first" --argjson services "$second" '{schema:1,family:"guest",virtualization:$virtualization,systemd_services:$services,cloud_init_installation:"Unsupported until configuration ownership is explicitly enrolled",network_probes:false}';;
    cleanup)
      first=$(dmb_runtime_capture 5 du -sk /var/cache/apt/archives /var/cache/pacman/pkg /var/cache/apk) || return
      second=$(dmb_runtime_capture 5 journalctl --disk-usage) || return
      jq -cn --argjson cache "$first" --argjson journal "$second" '{schema:1,family:"cleanup",package_cache:$cache,journal:$journal,mutations:false,network_probes:false}';;
    time)
      first=$(dmb_runtime_capture 5 timedatectl show --property=Timezone,NTP,NTPSynchronized,LocalRTC) || return
      second=$(dmb_runtime_capture 5 date --iso-8601=seconds) || return
      jq -cn --argjson manager "$first" --argjson clock "$second" '{schema:1,family:"time",manager:$manager,clock:$clock,network_probes:false}';;
    *) return 64;;
  esac
}
dmb_runtime_snapshot() {
  local root dir source slot state link identity xattrs_before xattrs_after snapshot_manifest='[]'
  root=$(dmb_state_root)/snapshots
  dmb_trusted_path "$root" allow_missing || return
  if [[ ! -e $root ]]; then mkdir -m 0700 -- "$root" || return; fi
  dmb_trusted_path "$root" || return
  dir=$(mktemp -d "$root/local.XXXXXXXXXXXX") || return
  chmod 700 "$dir" || return
  dmb_maintenance_report system | dmb_atomic_write "$dir/system.json" 0600 || return
  dmb_maintenance_report resources | dmb_atomic_write "$dir/resources.json" 0600 || return
  for source in /etc/sysctl.conf /etc/gai.conf /etc/fstab /etc/ssh/sshd_config /etc/resolv.conf; do
    [[ -e $source || -L $source ]] || continue
    slot=${source//\//_}; slot=${slot#_}
    dmb_trusted_path "${source%/*}" || return
    if [[ -L $source ]]; then
      # Copy the link itself, never its referent or an arbitrary manager path.
      dmb_need getfattr || return
      link=$(readlink -- "$source") || return
      xattrs_before=$(LC_ALL=C getfattr --no-dereference --absolute-names --encoding=hex -d -m - -- "$source" | sed '/^#/d;/^$/d' | LC_ALL=C sort | base64 -w0) || return
      identity=$(stat -c '%d:%i:%u:%g:%a' -- "$source") || return
      cp -a -- "$source" "$dir/$slot.link" || return
      [[ $(readlink -- "$dir/$slot.link") == "$link" && $(stat -c '%u:%g:%a' -- "$dir/$slot.link") == "$(stat -c '%u:%g:%a' -- "$source")" && $(stat -c '%d:%i:%u:%g:%a' -- "$source") == "$identity" ]] || return 76
      xattrs_after=$(LC_ALL=C getfattr --no-dereference --absolute-names --encoding=hex -d -m - -- "$dir/$slot.link" | sed '/^#/d;/^$/d' | LC_ALL=C sort | base64 -w0) || return
      [[ $xattrs_before == "$xattrs_after" ]] || return 76
      state=$(jq -cn --arg path "$source" --arg target "$link" --arg identity "$identity" --arg attrs "$xattrs_before" '{path:$path,type:"symlink",target:$target,identity:$identity,xattrs_b64:$attrs}') || return
    else
      dmb_file_capture "$source" "$dir" "$slot" || return
      state=$(jq -c --arg path "$source" '.+{path:$path}' "$dir/$slot.json") || return
    fi
    snapshot_manifest=$(jq -c --argjson state "$state" '.+[$state]' <<< "$snapshot_manifest") || return
  done
  jq -cn --argjson files "$snapshot_manifest" '{schema:1,files:$files,restoration:"Manual review required; this is not a bootable backup and does not include private keys or credentials"}' | dmb_atomic_write "$dir/manifest.json" 0600 || return
  sync -f "$dir" || return
  printf '%s\n' "$dir"
}
dmb_runtime_timezone() {
  local zone=${1-} before after
  [[ $zone =~ ^[A-Za-z0-9_+-]+(/[A-Za-z0-9_+-]+)*$ && $zone != posix/* && $zone != right/* ]] || return 64
  [[ -f /usr/share/zoneinfo/$zone ]] || return 78
  dmb_need timedatectl || return
  before=$(dmb_run 5 timedatectl show --property=Timezone --value) || return
  dmb_run 5 timedatectl set-timezone "$zone" || return
  after=$(dmb_run 5 timedatectl show --property=Timezone --value) || return
  [[ $after == "$zone" ]] || { dmb_error 'Timezone readback differs; inspect manager state'; return 76; }
  jq -cn --arg before "$before" --arg after "$after" '{schema:1,before:$before,after:$after,readback_verified:true}'
}
dmb_maintenance_run() (
  local action=${1-} parameter=${2-} manager=none name fd state rc=0 output
  dmb_require_root || return
  case "$action" in update-packages|clean-package-cache|snapshot|set-timezone|enable-time-sync|clean-journal) ;; *) dmb_error 'Maintenance actions: update-packages, clean-package-cache, snapshot, set-timezone ZONE, enable-time-sync, clean-journal SIZE'; return 64;; esac
  # Maintenance can update running services. Refuse while a pending protected
  # operation exists and hold the global lock so no new operation starts.
  dmb_tx_init || return
  dmb_tx_lock_path "$(dmb_lock_root)/global.lock" || return
  exec {fd}>"$(dmb_lock_root)/global.lock" || return
  flock -w 2 -x "$fd" || return 75
  DMB_LOCK_FDS+=("$fd")
  for state in "$(dmb_state_root)"/transactions/tx-*/state.json; do
    [[ -e $state ]] || continue
    case $(jq -er .state "$state") in COMMITTED|ROLLED_BACK) ;; *) dmb_error 'Resolve pending or failed transactions before maintenance'; return 75;; esac
  done
  dmb_audit maintenance-start "$(jq -cn --arg action "$action" '{action:$action,rollback:false}')" || return
  case "$action" in
    snapshot) dmb_runtime_snapshot; rc=$?;;
    set-timezone) dmb_runtime_timezone "$parameter"; rc=$?;;
    enable-time-sync)
      dmb_need timedatectl systemctl || return
      dmb_run 5 systemctl is-active --quiet systemd-timesyncd.service || { dmb_error 'No already active systemd-timesyncd owner; use your enrolled time manager'; return 78; }
      dmb_run 5 timedatectl set-ntp true && output=$(dmb_run 5 timedatectl show --property=NTP --value) && [[ $output == yes ]]; rc=$?;;
    clean-journal)
      [[ $parameter =~ ^[1-9][0-9]{0,5}[KMGT]$ ]] || return 64
      dmb_need journalctl || return
      dmb_run 30 journalctl --vacuum-size="$parameter"; rc=$?;;
    update-packages|clean-package-cache)
      for name in apt-get dnf yum pacman apk; do if command -v "$name" >/dev/null 2>&1; then manager=$name; break; fi; done
      [[ $manager != none ]] || return 69
      case "$manager:$action" in
        apt-get:update-packages) dmb_run 900 apt-get update && dmb_run 3600 apt-get upgrade; rc=$?;;
        apt-get:clean-package-cache) dmb_run 300 apt-get clean; rc=$?;;
        dnf:update-packages) dmb_run 3600 dnf upgrade; rc=$?;;
        dnf:clean-package-cache) dmb_run 300 dnf clean packages; rc=$?;;
        yum:update-packages) dmb_run 3600 yum update; rc=$?;;
        yum:clean-package-cache) dmb_run 300 yum clean packages; rc=$?;;
        pacman:update-packages) dmb_run 3600 pacman -Syu; rc=$?;;
        pacman:clean-package-cache) dmb_run 300 pacman -Sc; rc=$?;;
        apk:update-packages) dmb_run 900 apk update && dmb_run 3600 apk upgrade; rc=$?;;
        apk:clean-package-cache) dmb_run 300 apk cache clean; rc=$?;;
      esac;;
  esac
  dmb_audit maintenance-end "$(jq -cn --arg action "$action" --argjson code "$rc" '{action:$action,exit_code:$code,rollback:false}')" || return
  return "$rc"
)
# END MODULE adapters/runtime.sh

# BEGIN MODULE transaction.sh
# Durable, compensating transactions. Storage/firmware failures can defeat flush
# guarantees; no Bash transaction can promise recovery from arbitrary I/O loss.

dmb_tx_id_valid() { [[ ${1-} =~ ^tx-[a-f0-9]{32}$ ]]; }
dmb_tx_adapter_valid() {
  case ${1-} in dns|routing|dns_file|dns_nm|dns_networkd|dns_resolved|dns_ifupdown|mtu|iface|ipv6|ipv6_static|pool|nat66|ssh|nft|tcp|swap|maintenance|fs|f2b) return 0;; *) return 1;; esac
}
dmb_tx_dir() {
  dmb_tx_id_valid "${1-}" || return 2
  printf '%s/transactions/%s\n' "$(dmb_state_root)" "$1"
}
dmb_tx_namespace_check() {
  local namespace current_namespace init_namespace
  # Init launches the independent worker in its own namespaces. Capturing a
  # different namespace would arm recovery for a different resource universe.
  for namespace in mnt net pid user; do
    current_namespace=$(readlink "/proc/self/ns/$namespace") || return 78
    init_namespace=$(readlink "/proc/1/ns/$namespace") || return 78
    [[ $current_namespace == "$init_namespace" ]] || { printf 'Recovery cannot supervise a different %s namespace\n' "$namespace" >&2; return 78; }
  done
}
dmb_tx_init() {
  dmb_require_root || return 1
  dmb_need bash jq flock sha256sum mktemp timeout setsid readlink stat sync od tr awk cat mkdir chmod rm || return 1
  dmb_tx_namespace_check || return
  local base locks
  base=$(dmb_state_root); locks=$(dmb_lock_root)
  dmb_trusted_path "$base" allow_missing || return 1
  dmb_trusted_path "$locks" allow_missing || return 1
  # Each state directory is chmodded below after trusted-parent validation.
  # shellcheck disable=SC2174
  mkdir -p -m 700 -- "$base/transactions" "$base/reservations" "$locks" || return 1
  chmod 700 -- "$base" "$base/transactions" "$base/reservations" "$locks" || return 1
  dmb_trusted_path "$base/transactions" || return 1
  dmb_trusted_path "$base/reservations" || return 1
}
dmb_tx_canon() { jq -ceS .; }
dmb_tx_hash() { sha256sum | awk '{print $1}'; }
dmb_tx_uptime() { local n rest; read -r n rest < /proc/uptime || return 1; printf '%s\n' "${n%%.*}"; }
dmb_tx_boot_id() { cat /proc/sys/kernel/random/boot_id; }
dmb_tx_lock_path() {
  local path=$1
  dmb_trusted_path "$path" allow_missing || return 1
  # A symlink could truncate its target at redirection; a FIFO could block
  # before flock's timeout even begins. The private parent prevents untrusted
  # writers racing this check; root writers remain outside that guarantee.
  [[ ! -L $path ]] || return 1
  if [[ -e $path ]]; then [[ -f $path && $(stat -c %h -- "$path") == 1 ]] || return 1; fi
}
dmb_tx_confirmation_capability() {
  local ticks
  if declare -F dmb_confirmation_now_ticks >/dev/null; then
    ticks=$(dmb_confirmation_now_ticks) || return 69
    [[ $ticks =~ ^[0-9]+$ ]] || return 69
  fi
}
dmb_tx_state_write() {
  local tx=$1 next=$2 extra=${3:-'{}'} old generation payload
  case "$next" in PREPARED|ARMED|APPLIED|VERIFIED|COMMITTED|ROLLED_BACK|CONFLICT|ROLLBACK_FAILED) ;; *) return 2;; esac
  old=$(cat "$tx/state.json") || return 1
  local prior
  prior=$(jq -er '.state' <<< "$old") || return 1
  case "$prior:$next" in
    PREPARED:PREPARED|PREPARED:ARMED|PREPARED:ROLLED_BACK|PREPARED:CONFLICT|PREPARED:ROLLBACK_FAILED|ARMED:APPLIED|ARMED:ROLLED_BACK|ARMED:CONFLICT|ARMED:ROLLBACK_FAILED|APPLIED:VERIFIED|APPLIED:ROLLED_BACK|APPLIED:CONFLICT|APPLIED:ROLLBACK_FAILED|VERIFIED:VERIFIED|VERIFIED:COMMITTED|VERIFIED:ROLLED_BACK|VERIFIED:CONFLICT|VERIFIED:ROLLBACK_FAILED|CONFLICT:CONFLICT|CONFLICT:ROLLED_BACK|CONFLICT:ROLLBACK_FAILED|ROLLBACK_FAILED:ROLLBACK_FAILED|ROLLBACK_FAILED:CONFLICT|ROLLBACK_FAILED:ROLLED_BACK) ;;
    *) printf 'Invalid transaction transition: %s -> %s\n' "$prior" "$next" >&2; return 2;;
  esac
  generation=$(jq -er '.generation + 1' <<< "$old") || return 1
  payload=$(jq -ce --arg state "$next" --argjson generation "$generation" --argjson extra "$extra" '. + $extra + {state:$state,generation:$generation}' <<< "$old") || return 1
  printf '%s\n' "$payload" | dmb_atomic_write "$tx/state.json" 0600
}
dmb_tx_plan_validate() {
  local plan=$1 adapter op i count
  jq -e '
    .schema == 1 and (.steps|type=="array" and length>0 and length<=128) and
    (.resources|type=="array" and length>0 and length<=512) and
    all(.resources[]; type=="string" and test("^[A-Za-z0-9][A-Za-z0-9_./:-]{0,511}$")) and
    ((.resources|unique|length)==(.resources|length)) and
    ([.steps[].id]|unique|length)==(.steps|length) and
    all(.steps[]; (.id|type=="string" and test("^[A-Za-z0-9][A-Za-z0-9_.:-]{0,99}$")) and
      has("after") and ((.phase // "apply")=="apply" or .phase=="commit") and
      ((.restore_rank // 0)|type=="number" and floor==. and .>=-100000 and .<=100000)) and
    (. as $p | all(.steps[]; .resource as $r | $p.resources|index($r)!=null)) and
    ((.timeout_seconds // 180)|type=="number" and floor==. and .>=60 and .<=3600)
  ' "$plan" >/dev/null || return 2
  jq -e '. as $p | all(.steps|to_entries[]; . as $s | if (($s.value.adapter // $p.adapter)=="fs") then
      ([ $p.steps[:$s.key][] | select(.resource==$s.value.resource) ]|length)==0
      else true end)' "$plan" >/dev/null || return 2
  count=$(jq '.steps|length' "$plan") || return 1
  for ((i=0;i<count;i++)); do
    adapter=$(jq -er --argjson i "$i" '.steps[$i].adapter // .adapter' "$plan") || return 2
    dmb_tx_adapter_valid "$adapter" || return 2
    if [[ $adapter == ssh ]]; then dmb_ssh_plan_shape "$plan" || return 2; fi
    for op in capture apply verify restore; do declare -F "dmb_${adapter}_${op}" >/dev/null || return 2; done
    if [[ $adapter == fs ]] && declare -F dmb_fs_plan_validate >/dev/null; then
      dmb_fs_plan_validate "$plan" "$i" || return 2
    fi
  done
}
# Resource labels are user-facing, not authority. Derive extra lock keys from
# actual adapter targets, so choosing a different label cannot evade ownership.
dmb_tx_expand_resources() {
  local plan=$1 result i count field value canonical key adapter family table identity
  result=$(jq -cS . "$plan") || return 1
  count=$(jq '.steps|length' "$plan") || return 1
  for ((i=0;i<count;i++)); do
    adapter=$(jq -er --argjson i "$i" '.steps[$i].adapter // .adapter' "$plan") || return 2
    for field in path file fragment; do
      value=$(jq -er --argjson i "$i" --arg f "$field" '.steps[$i][$f] // empty' "$plan") || continue
      [[ $value == /* ]] || return 2
      dmb_trusted_path "$value" allow_missing || return 1
      canonical=$(readlink -m -- "$value") || return 1
      key="owned:file:$(printf '%s' "$canonical" | dmb_tx_hash)"
      result=$(jq -cS --arg key "$key" '.resources=([.resources[],$key]|unique)' <<< "$result") || return 1
    done
    value=$(jq -r --argjson i "$i" '.steps[$i].iface // empty' "$plan") || return 1
    if [[ -n $value ]]; then
      [[ $value =~ ^[A-Za-z0-9_.:-]{1,15}$ ]] || return 2
      key="owned:link:$value"
      result=$(jq -cS --arg key "$key" '.resources=([.resources[],$key]|unique)' <<< "$result") || return 1
    fi
    value=$(jq -r --argjson i "$i" '.steps[$i].key // empty' "$plan") || return 1
    if [[ -n $value ]]; then
      [[ $value =~ ^[A-Za-z0-9_.-]{1,255}$ ]] || return 2
      key="owned:sysctl:$value"
      result=$(jq -cS --arg key "$key" '.resources=([.resources[],$key]|unique)' <<< "$result") || return 1
    fi
    if [[ $adapter == nft || $adapter == nat66 ]]; then
      family=$(jq -er --argjson i "$i" '.steps[$i].nft.family' "$plan") || return 2
      table=$(jq -er --argjson i "$i" '.steps[$i].nft.table' "$plan") || return 2
      [[ $family =~ ^(inet|ip|ip6)$ && $table =~ ^[A-Za-z_][A-Za-z0-9_]{0,63}$ ]] || return 2
      key="owned:nft:$family:$table"
      result=$(jq -cS --arg key "$key" '.resources=([.resources[],$key]|unique)' <<< "$result") || return 1
    fi
    if [[ $adapter == ssh || $adapter == f2b ]]; then
      result=$(jq -cS '.resources=([.resources[],"owned:ssh-service"]|unique)' <<< "$result") || return 1
    fi
    if [[ $adapter == dns_nm ]]; then
      identity=$(jq -er --argjson i "$i" '.steps[$i].identity' "$plan") || return 2
      key="owned:nm:$(printf '%s' "$identity" | dmb_tx_hash)"
      result=$(jq -cS --arg key "$key" '.resources=([.resources[],$key]|unique)' <<< "$result") || return 1
    fi
  done
  printf '%s\n' "$result"
}
dmb_tx_adapter_capture() {
  local plan=$1 i=$2 adapter
  adapter=$(jq -er --argjson i "$i" '.steps[$i].adapter // .adapter' "$plan") || return 2
  dmb_tx_adapter_valid "$adapter" || return 2
  "dmb_${adapter}_capture" "$plan" "$i" | dmb_tx_canon
}
# Only the pinned worker may dispatch adapter operations. Every native adapter
# command must itself be bounded; the outer worker also has a process-group cap.
dmb_tx_adapter_dispatch() {
  local op=$1 id=$2 i=$3 tx adapter
  dmb_require_root || return 1
  case "$op" in capture|apply|verify|restore|verify_restore|owned_reset|cleanup|snapshot) ;; *) return 2;; esac
  tx=$(dmb_tx_dir "$id") || return 2
  dmb_trusted_path "$tx" || return 1
  [[ $i =~ ^[0-9]+$ ]] || return 2
  adapter=$(jq -er --argjson i "$i" '.steps[$i].adapter // .adapter' "$tx/plan.json") || return 2
  dmb_tx_adapter_valid "$adapter" || return 2
  if [[ $op == snapshot ]] && ! declare -F "dmb_${adapter}_snapshot" >/dev/null; then return 0; fi
  "dmb_${adapter}_${op}" "$tx/plan.json" "$i" "$tx"
}
# /proc stat command names may contain spaces and closing parentheses.
dmb_tx_proc_fields() {
  local pid=$1 data
  [[ $pid =~ ^[1-9][0-9]*$ && -r /proc/$pid/stat ]] || return 1
  IFS= read -r data < "/proc/$pid/stat" || return 1
  data=${data##*) }
  local -a fields
  read -r -a fields <<< "$data"
  (( ${#fields[@]} >= 20 )) || return 1
  printf '%s %s\n' "${fields[2]}" "${fields[19]}"
}
dmb_tx_close_locks() {
  local fd
  for fd in "${dmb_tx_resource_fds[@]-}" "${dmb_tx_lock_fd-}" "${dmb_tx_global_fd-}" "${DMB_LOCK_FDS[@]-}"; do
    [[ $fd =~ ^[0-9]+$ ]] && exec {fd}>&-
  done
  return 0
}
# Child waits for a durable, authenticated gate. It cannot mutate before its
# process group is recorded, allowing an independent watcher to cancel it.
dmb_tx_adapter_guarded() {
  local op=$1 id=$2 i=$3 nonce=$4 tx started now
  dmb_require_root || return 1
  [[ $nonce =~ ^[a-f0-9]{32}$ ]] || return 2
  tx=$(dmb_tx_dir "$id") || return 2
  started=$(dmb_tx_uptime) || return 1
  while :; do
    if [[ -f $tx/active-gate.json ]] && jq -e --arg nonce "$nonce" '.nonce==$nonce' "$tx/active-gate.json" >/dev/null 2>&1; then break; fi
    now=$(dmb_tx_uptime) || return 1
    (( now-started < 8 )) || return 1
    sleep 0.1
  done
  dmb_tx_integrity "$tx" || return 1
  case $op in apply|verify|restore|verify_restore|owned_reset|cleanup) ;; *) return 2;; esac
  dmb_tx_journal_valid "$tx" "$i" INTENT || return 1
  jq -e --arg nonce "$nonce" --arg op "$op" --argjson i "$i" '.nonce==$nonce and .operation==$op and .step==$i' "$tx/active.json" >/dev/null || return 1
  local group ticks parent own_pid=$BASHPID
  read -r group ticks < <(dmb_tx_proc_fields "$own_pid") || return 1
  parent=$(jq -er '.pgid' "$tx/active.json") || return 1
  [[ $group == "$parent" ]] || return 1
  if [[ $op == apply ]]; then
    local state
    state=$(jq -er '.state' "$tx/state.json") || return 1
    [[ $state == ARMED || $state == VERIFIED ]] || return 1
    dmb_tx_deadline_ok "$tx" || return 1
    dmb_recovery_ready "$id" "$tx" || return 1
  fi
  dmb_tx_adapter_dispatch "$op" "$id" "$i"
}
dmb_tx_group_running() {
  local target=$1 entry stat tail
  local -a fields
  [[ $target =~ ^[1-9][0-9]*$ ]] || return 2
  for entry in /proc/[0-9]*/stat; do
    IFS= read -r stat 2>/dev/null < "$entry" || continue
    tail=${stat##*) }; read -r -a fields <<< "$tail"
    [[ ${fields[2]:-} == "$target" && ${fields[0]:-Z} != Z && ${fields[0]:-X} != X ]] && return 0
  done
  return 1
}
dmb_tx_active_cancel() {
  local tx=$1 pid pgid ticks actualgroup actualticks nonce boot now
  [[ -f $tx/active.json ]] || return 0
  dmb_trusted_path "$tx/active.json" || return 1
  pid=$(jq -er '.pid' "$tx/active.json") || return 1
  pgid=$(jq -er '.pgid' "$tx/active.json") || return 1
  ticks=$(jq -er '.start_ticks' "$tx/active.json") || return 1
  boot=$(jq -er '.boot_id' "$tx/active.json") || return 1
  [[ $pid =~ ^[1-9][0-9]*$ && $pgid == "$pid" && $ticks =~ ^[0-9]+$ ]] || return 1
  [[ $boot == "$(dmb_tx_boot_id)" ]] || return 0
  if read -r actualgroup actualticks < <(dmb_tx_proc_fields "$pid"); then
    [[ $actualgroup == "$pgid" && $actualticks == "$ticks" ]] || return 1
  else
    # A killed group leader can leave descendants. A still-existing group with
    # no leader PID cannot have been newly created using that absent PID.
    [[ ! -e /proc/$pid ]] || return 1
  fi
  dmb_tx_group_running "$pgid" || return 0
  kill -TERM -- "-$pgid" 2>/dev/null || return 1
  now=$(dmb_tx_uptime) || return 1
  local until=$((now+3))
  while dmb_tx_group_running "$pgid"; do
    now=$(dmb_tx_uptime) || return 1
    if (( now >= until )); then
      kill -KILL -- "-$pgid" 2>/dev/null || return 1
      sleep 0.1
      dmb_tx_group_running "$pgid" && return 1
      break
    fi
    sleep 0.1
  done
  return 0
}
dmb_tx_adapter_run() {
  local op=$1 tx=$2 i=$3 id expected actual nonce pid group ticks result=0 tries
  id=${tx##*/}
  if [[ -f $tx/worker.sh && -f $tx/recovery.json ]]; then
    expected=$(jq -er '.worker_sha256' "$tx/recovery.json") || return 1
    actual=$(sha256sum "$tx/worker.sh" | awk '{print $1}') || return 1
    [[ $expected == "$actual" ]] || return 1
    nonce=$(od -An -N16 -tx1 /dev/urandom | tr -d ' \n') || return 1
    rm -f -- "$tx/active-gate.json" || return 1
    ( dmb_tx_close_locks; exec setsid timeout --signal=TERM --kill-after=3 30 bash "$tx/worker.sh" --internal-adapter-guarded "$op" "$id" "$i" "$nonce" ) &
    pid=$!
    for ((tries=0;tries<30;tries++)); do
      if read -r group ticks < <(dmb_tx_proc_fields "$pid") && [[ $group == "$pid" ]]; then break; fi
      sleep 0.01
    done
    if [[ ${group:-} != "$pid" || ! ${ticks:-} =~ ^[0-9]+$ ]]; then kill "$pid" 2>/dev/null || :; wait "$pid" 2>/dev/null || :; return 1; fi
    if ! jq -cn --argjson pid "$pid" --argjson pgid "$group" --arg ticks "$ticks" --arg boot "$(dmb_tx_boot_id)" --arg op "$op" --argjson i "$i" --arg nonce "$nonce" '{pid:$pid,pgid:$pgid,start_ticks:$ticks,boot_id:$boot,operation:$op,step:$i,nonce:$nonce}' | dmb_atomic_write "$tx/active.json" 0600; then
      kill -TERM -- "-$pid" 2>/dev/null || :; wait "$pid" 2>/dev/null || :; return 1
    fi
    if ! jq -cn --arg nonce "$nonce" '{nonce:$nonce}' | dmb_atomic_write "$tx/active-gate.json" 0600; then
      dmb_tx_active_cancel "$tx" || :; wait "$pid" 2>/dev/null || :; return 1
    fi
    wait "$pid" || result=$?
    rm -f -- "$tx/active.json" "$tx/active-gate.json" || return 1
    sync -f "$tx" || return 1
    return "$result"
  else
    [[ $op == snapshot ]] || return 1
    dmb_tx_adapter_dispatch "$op" "$id" "$i"
  fi
}
dmb_tx_resources_lock() {
  local plan=$1 key hash fd
  dmb_tx_resource_fds=()
  while IFS= read -r key; do
    hash=$(printf '%s' "$key" | dmb_tx_hash) || return 1
    dmb_tx_lock_path "$(dmb_lock_root)/resource-$hash.lock" || return 1
    exec {fd}>"$(dmb_lock_root)/resource-$hash.lock" || return 1
    if ! flock -w 2 -x "$fd"; then exec {fd}>&-; return 75; fi
    dmb_tx_resource_fds+=("$fd")
  done < <(jq -r '.resources|sort|.[]' "$plan")
}
dmb_tx_resources_unlock() { local fd; for fd in "${dmb_tx_resource_fds[@]-}"; do [[ $fd =~ ^[0-9]+$ ]] && exec {fd}>&-; done; dmb_tx_resource_fds=(); }
dmb_tx_reserve() {
  local tx=$1 id=${1##*/} key hash owner path
  while IFS= read -r key; do
    hash=$(printf '%s' "$key" | dmb_tx_hash) || return 1
    path=$(dmb_state_root)/reservations/$hash.json
    if [[ -e $path ]]; then
      dmb_trusted_path "$path" || return 1
      owner=$(jq -er '.transaction_id' "$path") || return 1
      if [[ $owner != "$id" ]] && dmb_tx_id_valid "$owner"; then
        local oldtx oldstate
        oldtx=$(dmb_tx_dir "$owner") || return 1
        if [[ -f $oldtx/state.json ]]; then
          dmb_trusted_path "$oldtx/state.json" || return 1
          oldstate=$(jq -er '.state' "$oldtx/state.json") || return 1
          if [[ $oldstate == COMMITTED || $oldstate == ROLLED_BACK ]]; then
            rm -f -- "$path" || return 1
            continue
          fi
        fi
      fi
      [[ $owner == "$id" ]] || { printf 'Resource reserved: %s (%s)\n' "$key" "$owner" >&2; return 75; }
    fi
  done < <(jq -r '.resources[]' "$tx/plan.json")
  while IFS= read -r key; do
    hash=$(printf '%s' "$key" | dmb_tx_hash) || return 1
    jq -cn --arg id "$id" --arg resource "$key" '{transaction_id:$id,resource:$resource}' | dmb_atomic_write "$(dmb_state_root)/reservations/$hash.json" 0600 || return 1
  done < <(jq -r '.resources[]' "$tx/plan.json")
}
dmb_tx_release() {
  local tx=$1 id=${1##*/} key hash path owner
  while IFS= read -r key; do
    hash=$(printf '%s' "$key" | dmb_tx_hash) || return 1
    path=$(dmb_state_root)/reservations/$hash.json
    [[ -e $path ]] || continue
    owner=$(jq -er '.transaction_id' "$path") || return 1
    [[ $owner == "$id" ]] || continue
    rm -f -- "$path" || return 1
  done < <(jq -r '.resources[]' "$tx/plan.json")
  sync -f "$(dmb_state_root)/reservations"
}
dmb_tx_reap_preparations() {
  local tx id pid ticks group actual boot
  for tx in "$(dmb_state_root)"/transactions/tx-*; do
    [[ -d $tx && ! -f $tx/state.json && -f $tx/preparation.json ]] || continue
    id=${tx##*/}; dmb_tx_id_valid "$id" || return 1
    dmb_trusted_path "$tx/preparation.json" || return 1
    jq -e --arg id "$id" '.id==$id and (.pid|type=="number") and (.start_ticks|type=="string") and (.boot_id|type=="string")' "$tx/preparation.json" >/dev/null || return 1
    [[ ! -e $tx/journal/0000-INTENT.json ]] || return 1
    pid=$(jq -r '.pid' "$tx/preparation.json"); ticks=$(jq -r '.start_ticks' "$tx/preparation.json"); boot=$(jq -r '.boot_id' "$tx/preparation.json")
    if [[ $boot == "$(dmb_tx_boot_id)" ]] && read -r group actual < <(dmb_tx_proc_fields "$pid") && [[ $actual == "$ticks" ]]; then continue; fi
    # No mutation can precede state.json, recovery READY, ARMED and INTENT.
    # Release reservation metadata only; retain snapshots and failure evidence.
    dmb_tx_release "$tx" || return 1
  done
}
dmb_tx_prepare_cleanup() {
  local tx=${1:-}
  [[ -n $tx && -f $tx/plan.json && ! -f $tx/state.json ]] || return 0
  dmb_tx_release "$tx" || { printf 'Preparation failed; retained reservation evidence: %s\n' "$tx" >&2; return 1; }
}
dmb_tx_prepare() (
  dmb_tx_init || exit 1
  local source=$1 tx id plan capture resource previous provided i count now limit boot
  dmb_trusted_path "$source" || exit 1
  dmb_tx_plan_validate "$source" || exit 2
  dmb_tx_confirmation_capability || exit $?
  dmb_tx_lock_path "$(dmb_lock_root)/global.lock" || exit 1
  exec {dmb_tx_global_fd}>"$(dmb_lock_root)/global.lock" || exit 1
  flock -w 2 -x "$dmb_tx_global_fd" || exit 75
  dmb_tx_reap_preparations || exit 1
  id="tx-$(od -An -N16 -tx1 /dev/urandom | tr -d ' \n')"
  dmb_tx_id_valid "$id" || exit 1
  tx=$(dmb_tx_dir "$id") || exit 1
  mkdir -m 700 -- "$tx" "$tx/journal" "$tx/snapshots" || exit 1
  trap 'rc=$?; dmb_tx_prepare_cleanup "$tx" || :; dmb_tx_resources_unlock; exit "$rc"' EXIT
  local prep_pid=$BASHPID prep_ticks
  read -r _ prep_ticks < <(dmb_tx_proc_fields "$prep_pid") || exit 1
  jq -cn --arg id "$id" --argjson pid "$prep_pid" --arg ticks "$prep_ticks" --arg boot "$(dmb_tx_boot_id)" '{id:$id,pid:$pid,start_ticks:$ticks,boot_id:$boot}' | dmb_atomic_write "$tx/preparation.json" 0600 || exit 1
  plan=$(dmb_tx_expand_resources "$source") || exit 1
  printf '%s\n' "$plan" | dmb_atomic_write "$tx/plan.json" 0600 || exit 1
  dmb_tx_plan_validate "$tx/plan.json" || exit 2
  dmb_tx_reserve "$tx" || exit $?
  dmb_tx_resources_lock "$tx/plan.json" || exit $?
  count=$(jq '.steps|length' "$tx/plan.json") || exit 1
  for ((i=0;i<count;i++)); do
    resource=$(jq -r --argjson i "$i" '.steps[$i].resource' "$tx/plan.json") || exit 1
    previous=$(jq -cS --argjson i "$i" --arg r "$resource" '[.steps[:$i][]|select(.resource==$r)]|last|if .==null then {found:false} else {found:true,value:.after} end' "$tx/plan.json") || exit 1
    if [[ $(jq -r '.found' <<< "$previous") == true ]]; then
      capture=$(jq -cS '.value' <<< "$previous") || exit 1
    else
      capture=$(dmb_tx_adapter_capture "$tx/plan.json" "$i") || exit 1
    fi
    if jq -e --argjson i "$i" '.steps[$i]|has("before")' "$tx/plan.json" >/dev/null; then
      provided=$(jq -cS --argjson i "$i" '.steps[$i].before' "$tx/plan.json") || exit 1
      [[ $provided == "$capture" ]] || { printf 'Expected resource version changed before prepare: %s\n' "$resource" >&2; exit 76; }
    fi
    plan=$(jq -cS --argjson i "$i" --argjson before "$capture" '.steps[$i].before=$before' "$tx/plan.json") || exit 1
    printf '%s\n' "$plan" | dmb_atomic_write "$tx/plan.json" 0600 || exit 1
    dmb_tx_adapter_run snapshot "$tx" "$i" || exit 1
  done
  now=$(dmb_tx_uptime); limit=$(jq -r '.timeout_seconds // 180' "$tx/plan.json"); boot=$(dmb_tx_boot_id)
  jq -cn --arg hash "$(sha256sum "$tx/plan.json" | awk '{print $1}')" '{sha256:$hash}' | dmb_atomic_write "$tx/plan-hash.json" 0600 || exit 1
  if declare -F dmb_confirmation_prepare >/dev/null; then dmb_confirmation_prepare "$tx" || exit 1; fi
  jq -cn --arg id "$id" --arg boot "$boot" --argjson deadline "$((now+limit))" '{schema:1,id:$id,state:"PREPARED",generation:1,boot_id:$boot,deadline_uptime:$deadline,confirmation_round:0,error:null}' | dmb_atomic_write "$tx/state.json" 0600 || exit 1
  printf '%s\n' "$id"
)
dmb_tx_integrity() {
  local tx=$1 expected actual
  dmb_trusted_path "$tx" || return 1
  local file
  for file in plan.json plan-hash.json state.json; do dmb_trusted_path "$tx/$file" || return 1; done
  dmb_tx_plan_validate "$tx/plan.json" || return 1
  expected=$(jq -er '.sha256' "$tx/plan-hash.json") || return 1
  actual=$(sha256sum "$tx/plan.json" | awk '{print $1}') || return 1
  [[ $expected == "$actual" ]]
}
dmb_tx_deadline_ok() {
  local tx=$1 boot deadline now
  boot=$(jq -er '.boot_id' "$tx/state.json") || return 1
  [[ $boot == "$(dmb_tx_boot_id)" ]] || return 1
  deadline=$(jq -er '.deadline_uptime' "$tx/state.json") || return 1
  now=$(dmb_tx_uptime) || return 1
  (( now < deadline ))
}
dmb_tx_journal() {
  local tx=$1 i=$2 phase=$3 payload
  payload=$(jq -cS --argjson i "$i" --arg phase "$phase" '{step:$i,event:$phase,resource:.steps[$i].resource,before:.steps[$i].before,after:.steps[$i].after}' "$tx/plan.json") || return 1
  printf '%s\n' "$payload" | dmb_atomic_write "$tx/journal/$(printf '%04d' "$i")-$phase.json" 0600
}
dmb_tx_journal_valid() {
  local tx=$1 i=$2 phase=$3 actual expected path
  path=$tx/journal/$(printf '%04d' "$i")-$phase.json
  dmb_trusted_path "$path" || return 1
  actual=$(jq -cS . "$path") || return 1
  expected=$(jq -cS --argjson i "$i" --arg phase "$phase" '{step:$i,event:$phase,resource:.steps[$i].resource,before:.steps[$i].before,after:.steps[$i].after}' "$tx/plan.json") || return 1
  [[ $actual == "$expected" ]]
}
dmb_tx_step() {
  local tx=$1 i=$2 before after current
  before=$(jq -cS --argjson i "$i" '.steps[$i].before' "$tx/plan.json") || return 1
  after=$(jq -cS --argjson i "$i" '.steps[$i].after' "$tx/plan.json") || return 1
  current=$(dmb_tx_adapter_capture "$tx/plan.json" "$i") || return 1
  if [[ $current != "$before" ]]; then
    dmb_tx_state_write "$tx" CONFLICT '{"error":"Resource changed before apply"}' || :
    return 76
  fi
  dmb_recovery_ready "${tx##*/}" "$tx" || return 1
  dmb_tx_deadline_ok "$tx" || return 1
  dmb_tx_journal "$tx" "$i" INTENT || return 1
  dmb_tx_adapter_run apply "$tx" "$i" || return 1
  current=$(dmb_tx_adapter_capture "$tx/plan.json" "$i") || return 1
  [[ $current == "$after" ]] || return 1
  dmb_tx_adapter_run verify "$tx" "$i" || return 1
  dmb_tx_deadline_ok "$tx" || return 1
  dmb_tx_journal "$tx" "$i" DONE
}
dmb_tx_apply() (
  dmb_tx_init || exit 1
  local id=$1 tx state i count phase rc=0
  tx=$(dmb_tx_dir "$id") || exit 2
  dmb_tx_integrity "$tx" || exit 1
  dmb_tx_lock_path "$(dmb_lock_root)/$id.lock" || exit 1
  exec {dmb_tx_lock_fd}>"$(dmb_lock_root)/$id.lock" || exit 1
  flock -w 2 -x "$dmb_tx_lock_fd" || exit 75
  state=$(jq -r '.state' "$tx/state.json") || exit 1
  [[ $state == PREPARED ]] || { printf 'Cannot apply transaction in %s\n' "$state" >&2; exit 2; }
  dmb_tx_confirmation_capability || exit $?
  dmb_tx_resources_lock "$tx/plan.json" || exit $?
  trap 'dmb_tx_resources_unlock' EXIT
  # Reservations were created under the global lock in prepare. Validate ownership
  # without creating anything while holding resource locks.
  dmb_tx_reservation_check "$tx" || exit $?
  local actor_ticks actor_pid=$BASHPID
  read -r _ actor_ticks < <(dmb_tx_proc_fields "$actor_pid") || exit 1
  dmb_tx_state_write "$tx" PREPARED "$(jq -cn --argjson pid "$actor_pid" --arg ticks "$actor_ticks" '{actor_pid:$pid,actor_start_ticks:$ticks}')" || exit 1
  dmb_recovery_arm "$id" "$tx" || exit 1
  dmb_recovery_ready "$id" "$tx" || exit 1
  dmb_tx_deadline_ok "$tx" || exit 1
  dmb_tx_state_write "$tx" ARMED || exit 1
  count=$(jq '.steps|length' "$tx/plan.json") || exit 1
  for ((i=0;i<count;i++)); do
    phase=$(jq -r --argjson i "$i" '.steps[$i].phase // "apply"' "$tx/plan.json") || exit 1
    [[ $phase == apply ]] || continue
    dmb_tx_deadline_ok "$tx" || { rc=1; break; }
    dmb_tx_step "$tx" "$i" || { rc=$?; break; }
  done
  if (( rc==0 )); then
    dmb_tx_deadline_ok "$tx" || rc=1
  fi
  if (( rc==0 )); then
    local threshold='{}' confirmation_ticks
    if declare -F dmb_confirmation_now_ticks >/dev/null; then
      confirmation_ticks=$(dmb_confirmation_now_ticks) || exit 1
      [[ $confirmation_ticks =~ ^[0-9]+$ ]] || exit 1
      threshold=$(jq -cn --argjson ticks "$confirmation_ticks" '{confirmation_min_start_ticks:$ticks}') || exit 1
    fi
    dmb_tx_state_write "$tx" APPLIED && dmb_tx_state_write "$tx" VERIFIED "$threshold" || exit 1
    printf '%s\n' "$id"
  else
    # Drop locks before invoking the same independently usable recovery path.
    dmb_tx_resources_unlock; exec {dmb_tx_lock_fd}>&-
    dmb_tx_rollback "$id" || :
    exit "$rc"
  fi
)
dmb_tx_confirm() (
  dmb_tx_init || exit 1
  local id=$1 mode=${2:-ssh} tx state proof round i count phase commits=0 rc=0 observed_generation
  tx=$(dmb_tx_dir "$id") || exit 2
  dmb_tx_integrity "$tx" || exit 1
  [[ $(jq -er '.state' "$tx/state.json") == VERIFIED ]] || exit 2
  observed_generation=$(jq -er '.generation' "$tx/state.json") || exit 1
  dmb_tx_deadline_ok "$tx" || exit 1
  # The user may take time to authenticate/type. No transaction or resource
  # lock is held across that interaction; the watchdog remains independent.
  proof=$(dmb_confirmation_check "$tx" "$mode" | dmb_tx_canon) || exit 1
  dmb_tx_lock_path "$(dmb_lock_root)/$id.lock" || exit 1
  exec {dmb_tx_lock_fd}>"$(dmb_lock_root)/$id.lock" || exit 1
  flock -w 2 -x "$dmb_tx_lock_fd" || exit 75
  state=$(jq -r '.state' "$tx/state.json") || exit 1
  [[ $state == VERIFIED ]] || exit 2
  [[ $(jq -er '.generation' "$tx/state.json") == "$observed_generation" ]] || exit 76
  jq -e --arg id "$id" --argjson generation "$observed_generation" '.transaction_id==$id and .generation==$generation' <<< "$proof" >/dev/null || exit 76
  dmb_tx_deadline_ok "$tx" || exit 1
  dmb_tx_resources_lock "$tx/plan.json" || exit $?
  trap 'dmb_tx_resources_unlock' EXIT
  round=$(jq -r '.confirmation_round // 0' "$tx/state.json") || exit 1
  printf '%s\n' "$proof" | dmb_atomic_write "$tx/proof-$((round+1)).json" 0600 || exit 1
  count=$(jq '.steps|length' "$tx/plan.json") || exit 1
  if (( round==0 )); then
    for ((i=0;i<count;i++)); do
      phase=$(jq -r --argjson i "$i" '.steps[$i].phase // "apply"' "$tx/plan.json") || exit 1
      [[ $phase == commit ]] || continue
      commits=$((commits+1))
      dmb_tx_deadline_ok "$tx" || { rc=1; break; }
      dmb_tx_step "$tx" "$i" || { rc=$?; break; }
    done
    if (( rc!=0 )); then
      dmb_tx_resources_unlock; exec {dmb_tx_lock_fd}>&-
      dmb_tx_rollback "$id" || :
      exit "$rc"
    fi
    if (( commits>0 )); then
      local threshold='{"confirmation_round":1}' confirmation_ticks
      if declare -F dmb_confirmation_now_ticks >/dev/null; then
        confirmation_ticks=$(dmb_confirmation_now_ticks) || exit 1
        [[ $confirmation_ticks =~ ^[0-9]+$ ]] || exit 1
        threshold=$(jq -cn --argjson ticks "$confirmation_ticks" '{confirmation_round:1,confirmation_min_start_ticks:$ticks}') || exit 1
      fi
      dmb_tx_state_write "$tx" VERIFIED "$threshold" || exit 1
      dmb_confirmation_prepare "$tx" || exit 1
      printf 'Final policy applied; reconnect and confirm again before the original deadline: %s\n' "$id"
      exit 0
    fi
  else
    [[ $(jq -r '.transport_id' "$tx/proof-1.json") != "$(jq -r '.transport_id' <<< "$proof")" || $mode == console ]] || exit 1
  fi
  # Compare the final expected state for each resource, not superseded stages.
  while IFS= read -r i; do
    local current expected
    current=$(dmb_tx_adapter_capture "$tx/plan.json" "$i") || exit 1
    expected=$(jq -cS --argjson i "$i" '.steps[$i].after' "$tx/plan.json") || exit 1
    [[ $current == "$expected" ]] || { dmb_tx_state_write "$tx" CONFLICT '{"error":"Resource changed before confirmation"}'; exit 76; }
    dmb_tx_adapter_run verify "$tx" "$i" || exit 1
  done < <(jq -r '.steps|to_entries|group_by(.value.resource)|.[]|last|.key' "$tx/plan.json")
  dmb_tx_deadline_ok "$tx" || exit 1
  dmb_tx_state_write "$tx" COMMITTED || exit 1
  dmb_recovery_disarm "$id" || printf 'Committed, but recovery unit cleanup needs inspection: %s\n' "$id" >&2
  dmb_tx_resources_unlock
  dmb_tx_lock_path "$(dmb_lock_root)/global.lock" || exit 1
  exec {dmb_tx_global_fd}>"$(dmb_lock_root)/global.lock" || exit 1
  flock -w 2 -x "$dmb_tx_global_fd" || exit 75
  dmb_tx_release "$tx" || exit 1
  printf 'COMMITTED %s\n' "$id"
)
dmb_tx_cleanup_step() {
  local adapter
  adapter=$(jq -er --argjson i "$2" '.steps[$i].adapter // .adapter' "$1/plan.json") || return 1
  dmb_tx_adapter_valid "$adapter" || return 1
  if declare -F "dmb_${adapter}_cleanup" >/dev/null; then dmb_tx_adapter_run cleanup "$1" "$2" || return $?; fi
  return 0
}
dmb_tx_has_restore_verify() {
  local adapter
  adapter=$(jq -er --argjson i "$2" '.steps[$i].adapter // .adapter' "$1/plan.json") || return 1
  dmb_tx_adapter_valid "$adapter" && declare -F "dmb_${adapter}_verify_restore" >/dev/null
}
dmb_tx_has_owned_reset() {
  local adapter
  adapter=$(jq -er --argjson i "$2" '.steps[$i].adapter // .adapter' "$1/plan.json") || return 1
  dmb_tx_adapter_valid "$adapter" && declare -F "dmb_${adapter}_owned_reset" >/dev/null
}
dmb_tx_reservation_check() {
  local tx=$1 key path hash
  while IFS= read -r key; do
    hash=$(printf '%s' "$key" | dmb_tx_hash) || return 1
    path=$(dmb_state_root)/reservations/$hash.json
    dmb_trusted_path "$path" || return 1
    jq -e --arg id "${tx##*/}" --arg key "$key" '.transaction_id==$id and .resource==$key' "$path" >/dev/null || return 76
  done < <(jq -r '.resources[]' "$tx/plan.json")
}
dmb_tx_rollback() (
  dmb_tx_init || exit 1
  local id=$1 tx state i current before after rc=0 failed=0 conflict=0
  tx=$(dmb_tx_dir "$id") || exit 2
  dmb_tx_integrity "$tx" || exit 1
  dmb_tx_lock_path "$(dmb_lock_root)/$id.lock" || exit 1
  exec {dmb_tx_lock_fd}>"$(dmb_lock_root)/$id.lock" || exit 1
  flock -w 2 -x "$dmb_tx_lock_fd" || exit 75
  state=$(jq -r '.state' "$tx/state.json") || exit 1
  case "$state" in COMMITTED|ROLLED_BACK)
    dmb_recovery_disarm "$id" || :
    dmb_tx_lock_path "$(dmb_lock_root)/global.lock" || exit 1
    exec {dmb_tx_global_fd}>"$(dmb_lock_root)/global.lock" || exit 1
    flock -w 2 -x "$dmb_tx_global_fd" || exit 75
    dmb_tx_release "$tx"; exit $?;; PREPARED|ARMED|APPLIED|VERIFIED|CONFLICT|ROLLBACK_FAILED) ;; *) exit 2;; esac
  dmb_tx_resources_lock "$tx/plan.json" || exit $?
  trap 'dmb_tx_resources_unlock' EXIT
  dmb_tx_reservation_check "$tx" || { dmb_tx_state_write "$tx" CONFLICT '{"error":"Transaction no longer owns resource reservations"}' || :; exit 76; }
  dmb_tx_active_cancel "$tx" || { dmb_tx_state_write "$tx" ROLLBACK_FAILED '{"error":"Cannot prove active mutator was stopped"}' || :; exit 1; }
  while IFS= read -r i; do
    [[ -f $tx/journal/$(printf '%04d' "$i")-INTENT.json ]] || continue
    dmb_tx_journal_valid "$tx" "$i" INTENT || { failed=1; continue; }
    if [[ -f $tx/journal/$(printf '%04d' "$i")-RESTORED.json ]]; then
      dmb_tx_journal_valid "$tx" "$i" RESTORED || failed=1
      continue
    fi
    dmb_tx_cleanup_step "$tx" "$i" || { failed=1; continue; }
    before=$(jq -cS --argjson i "$i" '.steps[$i].before' "$tx/plan.json") || { failed=1; continue; }
    after=$(jq -cS --argjson i "$i" '.steps[$i].after' "$tx/plan.json") || { failed=1; continue; }
    current=$(dmb_tx_adapter_capture "$tx/plan.json" "$i") || { failed=1; continue; }
    if [[ $current == "$before" ]]; then
      if dmb_tx_has_restore_verify "$tx" "$i"; then
        if ! dmb_tx_adapter_run verify_restore "$tx" "$i"; then
          # Configuration can already be restored while a prior reload failed.
          # The idempotent inverse must reconcile its owned runtime state too.
          dmb_tx_journal "$tx" "$i" RESTORE_INTENT || { failed=1; continue; }
          dmb_tx_adapter_run restore "$tx" "$i" || { failed=1; continue; }
          current=$(dmb_tx_adapter_capture "$tx/plan.json" "$i") || { failed=1; continue; }
          [[ $current == "$before" ]] || { failed=1; continue; }
          dmb_tx_adapter_run verify_restore "$tx" "$i" || { failed=1; continue; }
        fi
      fi
      dmb_tx_cleanup_step "$tx" "$i" || { failed=1; continue; }
      dmb_tx_journal "$tx" "$i" RESTORED || failed=1; continue
    fi
    if [[ $current != "$after" ]]; then
      # A kernel resource may disappear on reboot. Only its own pinned adapter
      # may prove that exact reset condition and authority to rebuild it; all
      # other third states remain conflicts. The inverse rechecks the proof.
      if ! dmb_tx_has_owned_reset "$tx" "$i" || ! dmb_tx_adapter_run owned_reset "$tx" "$i"; then conflict=1; continue; fi
    fi
    dmb_tx_journal "$tx" "$i" RESTORE_INTENT || { failed=1; continue; }
    if ! dmb_tx_adapter_run restore "$tx" "$i"; then failed=1; continue; fi
    current=$(dmb_tx_adapter_capture "$tx/plan.json" "$i") || { failed=1; continue; }
    if [[ $current == "$before" ]]; then
      if dmb_tx_has_restore_verify "$tx" "$i"; then dmb_tx_adapter_run verify_restore "$tx" "$i" || { failed=1; continue; }; fi
      dmb_tx_cleanup_step "$tx" "$i" || { failed=1; continue; }
      dmb_tx_journal "$tx" "$i" RESTORED || failed=1
    else failed=1; fi
  done < <(jq -r '.steps|to_entries|sort_by([(.value.restore_rank // 0),(-.key)])|.[].key' "$tx/plan.json")
  # A previous RESTORED journal entry proves a past action, not the present
  # state. Re-read each touched resource at its original before-version.
  while IFS= read -r i; do
    local resource touched=0 j
    resource=$(jq -r --argjson i "$i" '.steps[$i].resource' "$tx/plan.json") || { failed=1; continue; }
    while IFS= read -r j; do
      [[ -f $tx/journal/$(printf '%04d' "$j")-INTENT.json ]] && touched=1
    done < <(jq -r --arg r "$resource" '.steps|to_entries|.[]|select(.value.resource==$r)|.key' "$tx/plan.json")
    (( touched )) || continue
    before=$(jq -cS --argjson i "$i" '.steps[$i].before' "$tx/plan.json") || { failed=1; continue; }
    current=$(dmb_tx_adapter_capture "$tx/plan.json" "$i") || { failed=1; continue; }
    [[ $current == "$before" ]] || conflict=1
  done < <(jq -r '.steps|to_entries|group_by(.value.resource)|.[]|first|.key' "$tx/plan.json")
  if (( failed )); then dmb_tx_state_write "$tx" ROLLBACK_FAILED '{"error":"Restoration or durable recording failed"}' || :; exit 1; fi
  if (( conflict )); then dmb_tx_state_write "$tx" CONFLICT '{"error":"External state differs; conflicting resources were not overwritten"}' || :; exit 76; fi
  dmb_tx_state_write "$tx" ROLLED_BACK '{"restoration_evidence":"adapter readback and available restore postconditions; external connectivity unverified"}' || exit 1
  dmb_recovery_disarm "$id" || :
  dmb_tx_resources_unlock
  dmb_tx_lock_path "$(dmb_lock_root)/global.lock" || exit 1
  exec {dmb_tx_global_fd}>"$(dmb_lock_root)/global.lock" || exit 1
  flock -w 2 -x "$dmb_tx_global_fd" || exit 75
  dmb_tx_release "$tx"
)
dmb_tx_execute() { local id; id=$(dmb_tx_prepare "$1") || return $?; dmb_tx_apply "$id"; }
dmb_tx_status() { local tx; dmb_require_root || return 1; tx=$(dmb_tx_dir "$1") || return 2; dmb_trusted_path "$tx" || return 1; jq -cS . "$tx/state.json"; }
dmb_tx_list() { local path; dmb_require_root || return 1; for path in "$(dmb_state_root)"/transactions/tx-*/state.json; do [[ -f $path && ! -L $path ]] || continue; jq -cS '{id,state,generation,confirmation_round,error}' "$path" || return 1; done; }
# END MODULE transaction.sh

# BEGIN MODULE recovery/supervisor.sh
# Independent rollback supervision. This file is concatenated into the release.
# Filesystem failure, uninterruptible kernel I/O, or power loss can prevent any
# shell supervisor from guaranteeing rollback; preserve evidence and fail closed.
dmb_recovery_boot_id() { cat /proc/sys/kernel/random/boot_id; }
dmb_recovery_uptime() { local up rest; read -r up rest < /proc/uptime; printf '%s\n' "${up%%.*}"; }
dmb_recovery_systemd_dir() { printf '/etc/systemd/system\n'; }
dmb_recovery_openrc_dir() { printf '/etc/init.d\n'; }
dmb_recovery_install_dir() { printf '/usr/local/libexec/dmitbox-local\n'; }
dmb_recovery_error() { printf 'dmitbox recovery: %s\n' "$*" >&2; }
# Recovery infrastructure is itself an owned resource. Prefixes alone do not
# authorize overwriting a unit or scanner installed by an administrator.
# INTENT records allow interrupted publication to be checked on the next run.
dmb_recovery_owned_write() (
  local path=$1 mode=$2 expected=${3:-} registry lock_fd tmp desired current=absent record='{}' previous next
  [[ -z $expected || $expected =~ ^[a-f0-9]{64}$ ]] || return 2
  registry=$(dmb_state_root)/recovery-files.json
  dmb_trusted_path "$path" allow_missing || return 1
  dmb_trusted_path "$registry" allow_missing || return 1
  dmb_tx_lock_path "$(dmb_lock_root)/recovery-files.lock" || return 1
  exec {lock_fd}>"$(dmb_lock_root)/recovery-files.lock" || return 1
  flock -w 2 -x "$lock_fd" || return 75
  local -a DMB_LOCK_FDS=("${DMB_LOCK_FDS[@]-}" "$lock_fd")
  if [[ -e $registry ]]; then
    jq -e '.schema==1 and (.files|type=="object")' "$registry" >/dev/null || return 1
    record=$(jq -cS . "$registry") || return 1
  else record='{"schema":1,"files":{}}'; fi
  if [[ -e $path ]]; then
    [[ -f $path && ! -L $path ]] || return 1
    current=$(sha256sum -- "$path") || return 1; current=${current%% *}
  fi
  previous=$(jq -cr --arg path "$path" '.files[$path] // null' <<< "$record") || return 1
  if [[ $previous == null ]]; then
    [[ $current == absent ]] || { dmb_recovery_error "Unenrolled recovery file already exists: $path"; return 76; }
  else
    jq -e --arg current "$current" '.after==$current or (.phase=="INTENT" and .before==$current)' <<< "$previous" >/dev/null || { dmb_recovery_error "Recovery file changed outside its ownership record: $path"; return 76; }
  fi
  tmp=$(mktemp "$(dmb_state_root)/.recovery-publish.XXXXXXXX") || return 1
  trap 'rm -f -- "$tmp"' EXIT
  cat > "$tmp" || return 1
  desired=$(sha256sum -- "$tmp") || return 1; desired=${desired%% *}
  [[ -z $expected || $desired == "$expected" ]] || return 1
  next=$(jq -cS --arg path "$path" --arg before "$current" --arg after "$desired" '.files[$path]={phase:"INTENT",before:$before,after:$after}' <<< "$record") || return 1
  printf '%s\n' "$next" | dmb_atomic_write "$registry" 0600 || return 1
  dmb_atomic_write "$path" "$mode" "$desired" < "$tmp" || return 1
  jq -cS --arg path "$path" '.files[$path].phase="DONE"' <<< "$next" | dmb_atomic_write "$registry" 0600
)
dmb_recovery_owned_remove() (
  local path=$1 registry lock_fd current record expected
  registry=$(dmb_state_root)/recovery-files.json
  dmb_trusted_path "$path" allow_missing || return 1
  dmb_trusted_path "$registry" || return 1
  dmb_tx_lock_path "$(dmb_lock_root)/recovery-files.lock" || return 1
  exec {lock_fd}>"$(dmb_lock_root)/recovery-files.lock" || return 1
  flock -w 2 -x "$lock_fd" || return 75
  local -a DMB_LOCK_FDS=("${DMB_LOCK_FDS[@]-}" "$lock_fd")
  record=$(jq -cS 'select(.schema==1 and (.files|type=="object"))' "$registry") || return 1
  expected=$(jq -r --arg path "$path" '.files[$path].after // empty' <<< "$record") || return 1
  if [[ -z $expected ]]; then [[ ! -e $path ]] || return 76; return 0; fi
  if [[ -e $path ]]; then
    current=$(sha256sum -- "$path") || return 1; current=${current%% *}
    [[ $current == "$expected" ]] || { dmb_recovery_error "Preserving externally modified recovery file: $path"; return 76; }
    rm -- "$path" || return 1
    sync -f "${path%/*}" || return 1
  fi
  jq -cS --arg path "$path" 'del(.files[$path])' <<< "$record" | dmb_atomic_write "$registry" 0600
)
dmb_recovery_owned_check() {
  local path=$1 registry expected actual
  dmb_trusted_path "$path" allow_missing || return 1
  [[ -e $path ]] || return 0
  registry=$(dmb_state_root)/recovery-files.json
  dmb_trusted_path "$registry" || return 1
  expected=$(jq -er --arg path "$path" '.files[$path].after' "$registry") || return 1
  actual=$(sha256sum -- "$path") || return 1
  [[ ${actual%% *} == "$expected" ]]
}
dmb_recovery_backend() {
  if [[ -d /run/systemd/system ]] && command -v systemctl >/dev/null 2>&1; then printf 'systemd\n'
  elif [[ -f /run/openrc/softlevel && -x /sbin/openrc-run ]] && command -v rc-service >/dev/null 2>&1 && command -v rc-update >/dev/null 2>&1 && command -v supervise-daemon >/dev/null 2>&1; then printf 'openrc\n'
  else dmb_recovery_error 'No supported independent recovery supervisor (systemd or OpenRC)'; return 1; fi
}
dmb_recovery_id_valid() { [[ ${1:-} =~ ^tx-[a-f0-9]{32}$ ]]; }
dmb_recovery_valid_record() {
  local id=$1 tx=$2
  dmb_recovery_id_valid "$id" || return 1
  dmb_trusted_path "$tx" || return 1
  dmb_trusted_path "$tx/recovery.json" || return 1
  dmb_trusted_path "$tx/worker.sh" || return 1
  jq -e --arg id "$id" '.id==$id and .version==1 and (.nonce|test("^[a-f0-9]{32}$")) and (.worker_sha256|test("^[a-f0-9]{64}$")) and (.backend=="systemd" or .backend=="openrc")' "$tx/recovery.json" >/dev/null || return 1
  local actual expected
  actual=$(sha256sum -- "$tx/worker.sh") || return 1; actual=${actual%% *}
  expected=$(jq -r '.worker_sha256' "$tx/recovery.json") || return 1
  [[ $actual == "$expected" ]] || { dmb_recovery_error "Pinned recovery worker changed: $id"; return 1; }
}
dmb_recovery_copy_worker() {
  local id=$1 tx=$2 source tmp expected actual
  source=$(dmb_artifact_path) || return 1
  dmb_trusted_path "$source" || return 1
  [[ -f $source && ! -L $source ]] || return 1
  # Never overwrite a previously pinned worker while a transaction exists.
  if [[ -e $tx/worker.sh ]]; then return 1; fi
  tmp=$(mktemp "$tx/.worker.XXXXXXXX") || return 1
  if ! cp -- "$source" "$tmp" || ! chmod 0700 "$tmp"; then rm -f -- "$tmp"; return 1; fi
  expected=$(sha256sum -- "$source") || { rm -f -- "$tmp"; return 1; }; expected=${expected%% *}
  actual=$(sha256sum -- "$tmp") || { rm -f -- "$tmp"; return 1; }; actual=${actual%% *}
  [[ $expected == "$actual" ]] || { rm -f -- "$tmp"; return 1; }
  # atomic_write supplies the core's checked sync + rename durability barriers.
  dmb_atomic_write "$tx/worker.sh" 0700 "$expected" < "$tmp" || { rm -f -- "$tmp"; return 1; }
  rm -f -- "$tmp"
  printf '%s\n' "$expected"
}
dmb_recovery_render_watch_unit() {
  local id=$1 tx=$2 nonce=$3
  # Generated arguments contain only restricted transaction ids/nonces and the
  # trusted fixed state-root path, never user-supplied shell commands.
  cat <<EOF
[Unit]
Description=DMITBox independent recovery $id
After=local-fs.target
[Service]
Type=simple
ExecStart=/bin/bash $tx/worker.sh --internal-recover-watch $id $nonce
Restart=on-failure
RestartSec=2s
TimeoutStopSec=50s
KillMode=control-group
[Install]
WantedBy=multi-user.target
EOF
}
dmb_recovery_render_timer() {
  local id=$1 remaining=$2
  [[ $remaining =~ ^[0-9]+$ ]] && (( remaining > 0 && remaining <= 3600 )) || return 1
  cat <<EOF
[Unit]
Description=DMITBox independent monotonic deadline $id
[Timer]
OnActiveSec=${remaining}s
AccuracySec=1s
Unit=dmitbox-$id-expire.service
[Install]
WantedBy=timers.target
EOF
}
dmb_recovery_render_expire_unit() {
  local id=$1 tx=$2
  cat <<EOF
[Unit]
Description=DMITBox deadline recovery $id
After=local-fs.target
[Service]
Type=oneshot
ExecStart=/bin/bash $tx/worker.sh --internal-recover-once $id
TimeoutStartSec=180s
KillMode=control-group
EOF
}
dmb_recovery_render_openrc_watch() {
  local id=$1 tx=$2 nonce=$3
  cat <<EOF
#!/sbin/openrc-run
name="DMITBox independent recovery $id"
command="/bin/bash"
command_args="$tx/worker.sh --internal-recover-watch $id $nonce"
supervisor="supervise-daemon"
respawn_delay="2"
respawn_max="0"
pidfile="/run/dmitbox-local-$id.pid"
retry="TERM/50/KILL/5"
depend() { need localmount; }
EOF
}
dmb_recovery_install_boot_gate() (
  local backend=$1 artifact artifact_hash install units init install_fd
  dmb_tx_lock_path "$(dmb_lock_root)/recovery-install.lock" || return 1
  exec {install_fd}>"$(dmb_lock_root)/recovery-install.lock" || return 1
  flock -w 2 -x "$install_fd" || return 75
  local -a DMB_LOCK_FDS=("${DMB_LOCK_FDS[@]-}" "$install_fd")
  artifact=$(dmb_artifact_path) || return 1
  artifact_hash=$(sha256sum -- "$artifact") || return 1; artifact_hash=${artifact_hash%% *}
  install=$(dmb_recovery_install_dir) || return 1
  [[ $install =~ ^/[A-Za-z0-9_/.-]+$ ]] || return 1
  dmb_trusted_path "$install" allow_missing || return 1
  # Parent ownership is validated; the leaf is explicitly restricted.
  # shellcheck disable=SC2174
  mkdir -p -m 0700 -- "$install" || return 1
  dmb_trusted_path "$install" || return 1
  # The stable boot scanner dispatches each pending transaction's pinned worker.
  # Replacing this scanner does not replace any transaction worker or snapshot.
  dmb_recovery_owned_write "$install/recovery-boot.sh" 0700 "$artifact_hash" < "$artifact" || return 1
  if [[ $backend == systemd ]]; then
    units=$(dmb_recovery_systemd_dir) || return 1
    dmb_trusted_path "$units" || return 1
    dmb_recovery_owned_write "$units/dmitbox-recovery-boot.service" 0644 <<EOF
[Unit]
Description=Recover incomplete DMITBox changes before networking
DefaultDependencies=no
After=local-fs.target
Before=network-pre.target systemd-sysctl.service ssh.service sshd.service
Wants=network-pre.target
[Service]
Type=oneshot
ExecStart=/bin/bash $install/recovery-boot.sh --recover-all
TimeoutStartSec=180s
[Install]
WantedBy=sysinit.target
EOF
    dmb_run 15 systemctl daemon-reload || return 1
    local drops
    drops=$(dmb_run 5 systemctl show --value --property=DropInPaths dmitbox-recovery-boot.service) || return 1
    [[ -z ${drops//[[:space:]]/} ]] || { dmb_recovery_error 'Boot recovery unit has external drop-ins'; return 76; }
    dmb_run 15 systemctl enable dmitbox-recovery-boot.service || return 1
    dmb_run 10 systemctl is-enabled --quiet dmitbox-recovery-boot.service || return 1
  elif [[ $backend == openrc ]]; then
    init=$(dmb_recovery_openrc_dir) || return 1
    dmb_trusted_path "$init" || return 1
    [[ ! -e /etc/conf.d/dmitbox-recovery-boot && ! -L /etc/conf.d/dmitbox-recovery-boot ]] || { dmb_recovery_error 'Boot recovery has external OpenRC configuration'; return 76; }
    dmb_recovery_owned_write "$init/dmitbox-recovery-boot" 0755 <<EOF
#!/sbin/openrc-run
name="Recover incomplete DMITBox changes before networking"
command="/bin/bash"
command_args="$install/recovery-boot.sh --recover-all"
depend() { need localmount; before networking net sshd; }
EOF
    dmb_run 15 rc-update add dmitbox-recovery-boot boot || return 1
    # Exact service presence is checked; successful rc-update alone is insufficient.
    # Consume the complete producer output: grep -q can close the pipe early
    # and turn a successful OpenRC query into SIGPIPE with pipefail enabled.
    local boot_services
    boot_services=$(dmb_run 10 rc-update show boot) || return 1
    grep -E '(^|[[:space:]])dmitbox-recovery-boot([[:space:]]|$)' <<< "$boot_services" >/dev/null || return 1
  else return 1; fi
)
dmb_recovery_arm() {
  local id=$1 tx=${2:-} backend hash nonce unitdir init ready_until now deadline remaining
  dmb_require_root || return 1
  dmb_need jq sha256sum bash mktemp cp chmod || return 1
  [[ -n $tx ]] || tx=$(dmb_tx_dir "$id") || return 1
  dmb_recovery_id_valid "$id" || return 1
  dmb_trusted_path "$tx" || return 1
  [[ $tx =~ ^/[A-Za-z0-9_/.-]+$ ]] || return 1
  backend=$(dmb_recovery_backend) || return 1
  hash=$(dmb_recovery_copy_worker "$id" "$tx") || return 1
  nonce=$(od -An -N16 -tx1 /dev/urandom | tr -d ' \n') || return 1
  [[ $nonce =~ ^[a-f0-9]{32}$ ]] || return 1
  jq -n --arg id "$id" --arg hash "$hash" --arg nonce "$nonce" --arg backend "$backend" '{version:1,id:$id,worker_sha256:$hash,nonce:$nonce,backend:$backend}' | dmb_atomic_write "$tx/recovery.json" 0600 || return 1
  dmb_recovery_install_boot_gate "$backend" || return 1
  if [[ $backend == systemd ]]; then
    unitdir=$(dmb_recovery_systemd_dir) || return 1
    dmb_recovery_render_watch_unit "$id" "$tx" "$nonce" | dmb_recovery_owned_write "$unitdir/dmitbox-$id.service" 0644 || return 1
    now=$(dmb_recovery_uptime) || return 1
    deadline=$(jq -er '.deadline_uptime' "$tx/state.json") || return 1
    remaining=$((deadline-now)); (( remaining > 0 )) || return 1
    dmb_recovery_render_timer "$id" "$remaining" | dmb_recovery_owned_write "$unitdir/dmitbox-$id.timer" 0644 || return 1
    dmb_recovery_render_expire_unit "$id" "$tx" | dmb_recovery_owned_write "$unitdir/dmitbox-$id-expire.service" 0644 || return 1
    dmb_run 15 systemctl daemon-reload || return 1
    dmb_run 15 systemctl enable --now "dmitbox-$id.timer" "dmitbox-$id.service" || return 1
  else
    init=$(dmb_recovery_openrc_dir) || return 1
    [[ ! -e /etc/conf.d/dmitbox-$id && ! -L /etc/conf.d/dmitbox-$id ]] || return 76
    dmb_recovery_render_openrc_watch "$id" "$tx" "$nonce" | dmb_recovery_owned_write "$init/dmitbox-$id" 0755 || return 1
    dmb_run 15 rc-update add "dmitbox-$id" default || return 1
    dmb_run 15 rc-service "dmitbox-$id" start || return 1
  fi
  now=$(dmb_recovery_uptime) || return 1; ready_until=$((now + 12))
  while :; do
    if dmb_recovery_ready "$id" "$tx"; then return 0; fi
    now=$(dmb_recovery_uptime) || return 1
    (( now < ready_until )) || { dmb_recovery_error "Recovery worker did not become ready: $id"; return 1; }
    sleep 1
  done
}
dmb_recovery_ready() {
  local id=$1 tx=${2:-} pid nonce hash boot backend mainpid drops
  [[ -n $tx ]] || tx=$(dmb_tx_dir "$id") || return 1
  dmb_recovery_valid_record "$id" "$tx" || return 1
  dmb_trusted_path "$tx/ready.json" || return 1
  nonce=$(jq -r '.nonce' "$tx/recovery.json") || return 1
  hash=$(jq -r '.worker_sha256' "$tx/recovery.json") || return 1
  boot=$(dmb_recovery_boot_id) || return 1
  jq -e --arg id "$id" --arg nonce "$nonce" --arg hash "$hash" --arg boot "$boot" '.id==$id and .nonce==$nonce and .worker_sha256==$hash and .boot_id==$boot and (.pid|type=="number") and .pid>1' "$tx/ready.json" >/dev/null 2>&1 || return 1
  pid=$(jq -r '.pid' "$tx/ready.json") || return 1
  kill -0 "$pid" 2>/dev/null || return 1
  # Prove the process belongs to the expected transaction, not a reused PID.
  [[ -r /proc/$pid/cmdline ]] || return 1
  # BusyBox grep does not consistently implement -z. Bash reads the kernel's
  # NUL-separated arguments without relying on a distribution-specific grep.
  local argument nonce_found=0
  while IFS= read -r -d '' argument; do
    [[ $argument != "$nonce" ]] || nonce_found=1
  done < "/proc/$pid/cmdline"
  ((nonce_found==1)) || return 1
  backend=$(jq -r '.backend' "$tx/recovery.json") || return 1
  if [[ $backend == systemd ]]; then
    dmb_run 5 systemctl is-active --quiet "dmitbox-$id.service" || return 1
    dmb_run 5 systemctl is-active --quiet "dmitbox-$id.timer" || return 1
    mainpid=$(dmb_run 5 systemctl show --value --property=MainPID "dmitbox-$id.service") || return 1
    [[ $mainpid == "$pid" ]] || return 1
    drops=$(dmb_run 5 systemctl show --value --property=DropInPaths "dmitbox-$id.service" "dmitbox-$id.timer" "dmitbox-$id-expire.service") || return 1
    [[ -z ${drops//[[:space:]]/} ]] || return 1
    dmb_run 5 systemctl show --value --property=Triggers "dmitbox-$id.timer" | grep -Fxq "dmitbox-$id-expire.service" || return 1
  else dmb_run 5 rc-service "dmitbox-$id" status; fi
}
dmb_recovery_attempt_rollback() (
  local id=$1 status=0 start now tx recovery_fd op
  tx=$(dmb_tx_dir "$id") || return 1
  dmb_tx_lock_path "$(dmb_lock_root)/recovery-$id.lock" || return 1
  exec {recovery_fd}>"$(dmb_lock_root)/recovery-$id.lock" || return 1
  flock -w 1 -x "$recovery_fd" || { exec {recovery_fd}>&-; return 75; }
  local -a DMB_LOCK_FDS=("${DMB_LOCK_FDS[@]-}" "$recovery_fd")
  # Cancellation precedes the engine lock: the actor must release its lock
  # after a terminated child exits. Never cancel an active inverse worker.
  if [[ -f $tx/active.json ]]; then
    op=$(jq -er '.operation' "$tx/active.json") || return 1
    case $op in apply|verify) dmb_tx_active_cancel "$tx" || return 1;; esac
  fi
  start=$(dmb_recovery_uptime) || return 1
  while :; do
    status=0; dmb_tx_rollback "$id" || status=$?
    if (( status == 0 )); then exec {recovery_fd}>&-; return 0; fi
    # Engine exit 75 means a bounded lock was busy. All other failures are
    # persistent engine outcomes, not permission to retry blindly forever.
    if (( status != 75 )); then exec {recovery_fd}>&-; return "$status"; fi
    now=$(dmb_recovery_uptime) || return 1
    (( now - start < 45 )) || { dmb_recovery_error "Recovery lock remained unavailable: $id"; exec {recovery_fd}>&-; return 1; }
    sleep 1
  done
)
dmb_recovery_watch_signal() {
  local id=$1 tx=$2 state
  state=$(jq -r '.state' "$tx/state.json" 2>/dev/null) || return 1
  case $state in COMMITTED|ROLLED_BACK) return 0 ;; esac
  dmb_recovery_attempt_rollback "$id"
}
dmb_recovery_watch() {
  local id=${1:-} nonce=${2:-} tx hash boot state deadline originboot now prepared_until actor startticks observed watcher_pid=$BASHPID
  dmb_require_root || return 1
  tx=$(dmb_tx_dir "$id") || return 1
  dmb_recovery_valid_record "$id" "$tx" || return 1
  [[ $nonce == "$(jq -r '.nonce' "$tx/recovery.json")" ]] || return 1
  dmb_trusted_path "$tx/state.json" || return 1
  dmb_trusted_path "$tx/plan.json" || return 1
  jq -e --arg id "$id" '.id==$id and (.deadline_uptime|type=="number") and (.boot_id|type=="string")' "$tx/state.json" >/dev/null || return 1
  jq -e '.schema==1 and (.steps|type=="array")' "$tx/plan.json" >/dev/null || return 1
  hash=$(jq -r '.worker_sha256' "$tx/recovery.json") || return 1
  boot=$(dmb_recovery_boot_id) || return 1
  now=$(dmb_recovery_uptime) || return 1; prepared_until=$((now + 15))
  trap 'dmb_recovery_watch_signal "$id" "$tx"; exit $?' HUP INT TERM
  jq -n --arg id "$id" --arg nonce "$nonce" --arg hash "$hash" --arg boot "$boot" --argjson pid "$watcher_pid" '{id:$id,nonce:$nonce,worker_sha256:$hash,boot_id:$boot,pid:$pid}' | dmb_atomic_write "$tx/ready.json" 0600 || return 1
  while :; do
    dmb_recovery_valid_record "$id" "$tx" || return 1
    state=$(jq -r '.state' "$tx/state.json") || return 1
    case $state in
      COMMITTED|ROLLED_BACK) trap - HUP INT TERM; return 0 ;;
      CONFLICT|ROLLBACK_FAILED) trap - HUP INT TERM; return 1 ;;
      PREPARED|ARMED|APPLIED|VERIFIED) ;;
      *) dmb_recovery_error "Invalid transaction state: $id"; return 1 ;;
    esac
    originboot=$(jq -r '.boot_id' "$tx/state.json") || return 1
    deadline=$(jq -r '.deadline_uptime' "$tx/state.json") || return 1
    [[ $deadline =~ ^[0-9]+$ ]] || return 1
    now=$(dmb_recovery_uptime) || return 1
    if [[ $originboot != "$boot" ]] || (( now >= deadline )) || { [[ $state == PREPARED ]] && (( now >= prepared_until )); }; then
      trap - HUP INT TERM
      dmb_recovery_attempt_rollback "$id"; return $?
    fi
    actor=$(jq -r '.actor_pid // empty' "$tx/state.json") || return 1
    if [[ $state != VERIFIED && -n $actor ]]; then
      [[ $actor =~ ^[0-9]+$ ]] || return 1
      startticks=$(jq -r '.actor_start_ticks // empty' "$tx/state.json") || return 1
      observed=''
      if [[ -r /proc/$actor/stat ]]; then read -r _ observed < <(dmb_tx_proc_fields "$actor") || return 1; fi
      if ! kill -0 "$actor" 2>/dev/null || [[ -n $startticks && $observed != "$startticks" ]]; then
        trap - HUP INT TERM
        dmb_recovery_attempt_rollback "$id"; return $?
      fi
    fi
    sleep 1
  done
}
dmb_recovery_disarm() {
  local id=$1 tx backend state units init
  dmb_require_root || return 1
  tx=$(dmb_tx_dir "$id") || return 1
  dmb_recovery_valid_record "$id" "$tx" || return 1
  state=$(jq -r '.state' "$tx/state.json") || return 1
  [[ $state == COMMITTED || $state == ROLLED_BACK ]] || { dmb_recovery_error 'Unresolved recovery cannot be disarmed'; return 1; }
  backend=$(jq -r '.backend' "$tx/recovery.json") || return 1
  # Worker naturally exits on terminal state. Do not synchronously stop its own
  # service from inside rollback: systemctl/rc-service would kill that worker.
  if [[ $backend == systemd ]]; then
    units=$(dmb_recovery_systemd_dir) || return 1
    dmb_recovery_owned_check "$units/dmitbox-$id.service" || return 76
    dmb_recovery_owned_check "$units/dmitbox-$id.timer" || return 76
    dmb_recovery_owned_check "$units/dmitbox-$id-expire.service" || return 76
    if [[ -e $units/dmitbox-$id.timer ]]; then dmb_run 10 systemctl disable --now "dmitbox-$id.timer" || return 1; fi
    if [[ -e $units/dmitbox-$id.service ]]; then dmb_run 10 systemctl disable "dmitbox-$id.service" || return 1; fi
    dmb_recovery_owned_remove "$units/dmitbox-$id.service" || return 1
    dmb_recovery_owned_remove "$units/dmitbox-$id.timer" || return 1
    dmb_recovery_owned_remove "$units/dmitbox-$id-expire.service" || return 1
    sync -f "$units" || return 1
    dmb_run 10 systemctl daemon-reload || return 1
  else
    init=$(dmb_recovery_openrc_dir) || return 1
    dmb_recovery_owned_check "$init/dmitbox-$id" || return 76
    if [[ -e $init/dmitbox-$id ]]; then dmb_run 10 rc-update del "dmitbox-$id" default || return 1; fi
    dmb_recovery_owned_remove "$init/dmitbox-$id" || return 1
    sync -f "$init" || return 1
  fi
}
dmb_recovery_boot() (
  local root tx id state status=0 rc global_fd
  local -a intents
  dmb_require_root || return 1
  root=$(dmb_state_root) || return 1
  [[ -d $root/transactions ]] || return 0
  dmb_trusted_path "$root/transactions" || return 1
  dmb_tx_init || return 1
  dmb_tx_lock_path "$(dmb_lock_root)/global.lock" || return 1
  exec {global_fd}>"$(dmb_lock_root)/global.lock" || return 1
  flock -w 2 -x "$global_fd" || return 75
  dmb_tx_reap_preparations || return 1
  exec {global_fd}>&-
  for tx in "$root"/transactions/tx-*; do
    [[ -d $tx ]] || continue
    id=${tx##*/}; dmb_recovery_id_valid "$id" || { status=1; continue; }
    if [[ ! -f $tx/state.json && -f $tx/preparation.json ]]; then
      # Reaper validated the dead constructor and released only its metadata.
      continue
    fi
    dmb_trusted_path "$tx/state.json" || { status=1; continue; }
    state=$(jq -r '.state' "$tx/state.json") || { status=1; continue; }
    case $state in
      COMMITTED|ROLLED_BACK)
        # Interrupted unit/reservation cleanup must remain retryable.
        dmb_tx_rollback "$id" || status=1
        continue;;
      PREPARED)
        intents=("$tx"/journal/*-INTENT.json)
        if [[ ! -e ${intents[0]} && ! -e $tx/active.json ]]; then
          # No mutation is permitted before ARMED + INTENT. Missing worker is
          # expected when a reboot happened between prepare and arm.
          dmb_tx_rollback "$id" || status=1
          continue
        fi;;
    esac
    # Never source a recorded transaction's code or data in the scanner process.
    dmb_recovery_valid_record "$id" "$tx" || { status=1; continue; }
    rc=0; dmb_run 60 /bin/bash "$tx/worker.sh" --internal-recover-once "$id" || rc=$?
    (( rc == 0 )) || status=1
  done
  return "$status"
)
# END MODULE recovery/supervisor.sh

# BEGIN MODULE main.sh
# Public CLI. Report/plan commands do not initialize state, install dependencies,
# make connectivity probes, or load kernel modules.
dmb_help() {
  cat <<'EOF'
DMITBox local 4 — standalone Bash, local administration
  --help | --version | --menu | --check
  --net-report | --net-route-test [CONTEXT_JSON] | --net-firewall-hash
  --net-list | --net-status TXID | --net-confirm TXID [ssh|console]
  --net-rollback TXID
  --enroll dns IFACE | --enroll ipv6 IFACE
  --enroll ssh CONFIG_JSON | --enroll nft CONFIG_JSON
  --enroll pool CONFIG_JSON
  --plan dns IFACE PROVIDER [persistent|runtime] [DNS ...]
  --plan mtu IFACE MTU [runtime] [CONTEXT_JSON]
  --plan ipv6 enable|disable [CONTEXT_JSON]
  --plan ssh-port PORT | --plan nft CONFIG_JSON
  --plan pool CONFIG_JSON | --plan nat66 CONFIG_JSON
  --plan tcp PROFILE MEASUREMENT_REQUEST_JSON [runtime|persistent]
  --plan swap PATH SIZE_MIB PRIORITY
  --plan gai v4|default|restore
  --diff PLAN_JSON | --apply-plan PLAN_JSON
  --net-dns-set PROVIDER IFACE [persistent|runtime] [DNS ...]
  --net-dns-restore IFACE | --net-mtu-set IFACE MTU [CONTEXT_JSON]
  --net-ipv6 enable|disable [CONTEXT_JSON]
  --net-iface IFACE up|down [CONTEXT_JSON]
  --net-gai v4|default|restore | --net-ssh-port PORT
  --dns-probe NAME | --pmtu-probe ADDRESS 4|6 [IFACE]
  --tcp-report | --swap-report | --maintenance-report [FAMILY]
  --maintenance ACTION [ARG]

Plans are JSON files. Apply requires root, verified resource ownership, an armed
independent recovery worker, and an enrolled fresh SSH login or local console.
Changing SSH ports requires two fresh authentications before the same deadline.
No status command installs packages or probes the Internet. Probe commands are
explicit. Exit codes: 0 success; 2/64 invalid input; 69 dependency/unsupported;
75 lock contention; 76 conflict; 77 privilege; 78 unsafe filesystem/ownership.
EOF
}
dmb_check() {
  local cmd missing=0
  for cmd in bash jq flock timeout setsid sha256sum sync stat mktemp ip ss; do
    if command -v "$cmd" >/dev/null 2>&1; then printf 'available %s\n' "$cmd"; else printf 'missing %s\n' "$cmd"; missing=1; fi
  done
  for cmd in nft sshd getfacl getfattr setfacl setfattr resolvectl nmcli networkctl rc-service; do
    if command -v "$cmd" >/dev/null 2>&1; then printf 'optional-available %s\n' "$cmd"; else printf 'optional-missing %s\n' "$cmd"; fi
  done
  printf 'Recovery and external reachability are not established by this check.\n'
  ((missing==0))
}
dmb_report() {
  dmb_need jq ip || return
  local links addresses routes4 routes6 rules4 rules6
  links=$(dmb_run 5 ip -j -d link show) || return
  addresses=$(dmb_run 5 ip -j address show) || return
  routes4=$(dmb_run 5 ip -4 -j route show table all) || return
  routes6=$(dmb_run 5 ip -6 -j route show table all) || return
  rules4=$(dmb_run 5 ip -4 -j rule show) || return
  rules6=$(dmb_run 5 ip -6 -j rule show) || return
  jq -cn --argjson links "$links" --argjson addresses "$addresses" --argjson v4 "$routes4" --argjson v6 "$routes6" --argjson r4 "$rules4" --argjson r6 "$rules6" '{schema:1,links:$links,addresses:$addresses,routes:{ipv4:$v4,ipv6:$v6},rules:{ipv4:$r4,ipv6:$r6},external_access:"not_tested"}'
}
dmb_plan() {
  local kind=${1-}; (($#>0)) && shift
  case $kind in
    dns) (($#>=2)) || return 64; local iface=$1 provider=$2 scope=${3:-persistent}; (($#>=3)) && shift 3 || shift 2; dmb_dns_plan "$iface" "$provider" "$scope" "$@";;
    mtu) (($#>=2 && $#<=4)) || return 64; dmb_mtu_plan "$1" "$2" "${3:-runtime}" "${4:-'{}'}";;
    ipv6) (($#>=1 && $#<=2)) || return 64; dmb_ipv6_plan "$1" "${2:-'{}'}";;
    ssh-port) (($#==1)) || return 64; dmb_ssh_plan_port "$1";;
    nft) (($#==1)) || return 64; dmb_nft_plan "$1";;
    pool) (($#==1)) || return 64; local config; config=$(jq -ce . "$1") || return 64; dmb_pool_plan "$config";;
    nat66) (($#==1)) || return 64; local config; config=$(jq -ce . "$1") || return 64; dmb_nat66_plan "$config";;
    tcp) (($#>=2 && $#<=3)) || return 64; dmb_tcp_plan "$1" "$2" "${3:-runtime}";;
    swap) (($#==3)) || return 64; dmb_swap_plan_create "$1" "$2" "$3";;
    gai) (($#==1)) || return 64; dmb_gai_plan "$1";;
    *) dmb_error 'Unknown plan type'; return 64;;
  esac
}
dmb_enroll() {
  dmb_require_root && dmb_need jq || return
  local kind=${1-} manifest path
  case $kind in
    dns) (($#==2)) || return 64; manifest=$(dmb_dns_enroll "$2") || return; dmb_dns_iface_valid "$2" || return 64; path=$DMB_STATE_DIR/enrollments/dns-$2.json;;
    ipv6) (($#==2)) || return 64; manifest=$(dmb_ipv6_enroll "$2") || return; dmb_route_iface_valid "$2" || return 64; path=$DMB_STATE_DIR/enrollments/ipv6-$2.json;;
    ssh) (($#==2)) || return 64; manifest=$(dmb_ssh_enroll "$2") || return; path=$DMB_STATE_DIR/enrollments/ssh.json;;
    nft) (($#==2)) || return 64; manifest=$(dmb_nft_enroll "$2") || return; path=$DMB_STATE_DIR/enrollments/nft.json;;
    pool) (($#==2)) || return 64; local config; config=$(jq -ce . "$2") || return 64; manifest=$(dmb_pool_enroll "$config") || return; local pool_id; pool_id=$(jq -er '.id' <<< "$manifest") || return; dmb_pool_id "$pool_id" || return 64; path=$DMB_STATE_DIR/enrollments/pool-$pool_id.json;;
    *) return 64;;
  esac
  dmb_trusted_path "${path%/*}" allow_missing || return
  mkdir -p -- "${path%/*}" && chmod 0700 -- "${path%/*}" || return
  local fd
  dmb_tx_lock_path "${path%/*}/.enroll.lock" || return
  exec {fd}>"${path%/*}/.enroll.lock" || return
  flock -w 2 -x "$fd" || { exec {fd}>&-; return 75; }
  if [[ -e $path ]]; then dmb_error 'Enrollment exists; inspect and explicitly retire it before replacing'; exec {fd}>&-; return 76; fi
  printf '%s\n' "$manifest" | dmb_atomic_write "$path" 0600
  local rc=$?; exec {fd}>&-; ((rc==0)) || return "$rc"
  dmb_audit enrollment "$(jq -cn --arg kind "$kind" --arg path "$path" '{kind:$kind,path:$path}')" || return
  printf 'Enrolled %s\n' "$path"
}
dmb_apply_file() (
  dmb_require_root && dmb_need jq || return
  local source=$1 tmp plan origin=null manifest console_allowed intended
  [[ -f $source && ! -L $source ]] || return 78
  # Copy input once into private trusted storage. The immutable prepared plan is
  # independently hashed and is never sourced or interpreted as shell code.
  tmp=$(dmb_private_tmp) || return
  trap 'rm -rf -- "$tmp"' EXIT
  plan=$(jq -ceS . "$source") || return 64
  # Baselines supplied in a plan are data, never confirmation authority.
  origin=$(dmb_confirmation_origin 2>/dev/null) || { dmb_error 'Cannot identify the initiating SSH transport or explicitly authorized enrolled console'; return 77; }
  manifest=$(_dmb_confirmation_manifest) || return
  console_allowed=$(jq -c '.confirmation.allow_console_confirmation==true' "$manifest") || return
  intended=$(jq -r '[(.contexts//[])[]|.user]|unique|if length==1 then .[0] else empty end' "$manifest") || return
  plan=$(jq -c --argjson origin "$origin" --argjson console "$console_allowed" --arg intended "$intended" '
    .origin_transport=$origin |
    .allow_console_confirmation=((.allow_console_confirmation // $console) and $console) |
    if (.confirm_user==null and $origin.kind=="console" and $intended!="") then .confirm_user=$intended else . end' <<< "$plan") || return
  printf '%s\n' "$plan" | dmb_atomic_write "$tmp/input.json" 0600 || return
  dmb_tx_execute "$tmp/input.json"
)
dmb_execute_plan() (
  dmb_require_root || return
  local tmp
  tmp=$(dmb_private_tmp) || return
  trap 'rm -rf -- "$tmp"' EXIT
  dmb_plan "$@" > "$tmp/plan.json" || return
  dmb_apply_file "$tmp/plan.json"
)
dmb_diff() {
  local plan=$1 count i before current after adapter
  dmb_need jq || return
  dmb_tx_plan_validate "$plan" || return 64
  count=$(jq '.steps|length' "$plan") || return
  for ((i=0;i<count;i++)); do
    adapter=$(jq -r --argjson i "$i" '.steps[$i].adapter // .adapter' "$plan") || return
    current=$(dmb_tx_adapter_capture "$plan" "$i") || return
    before=$(jq -c --argjson i "$i" '.steps[$i].before // null' "$plan") || return
    after=$(jq -c --argjson i "$i" '.steps[$i].after' "$plan") || return
    jq -cn --argjson i "$i" --arg adapter "$adapter" --argjson current "$current" --argjson expected "$before" --argjson desired "$after" '{step:$i,adapter:$adapter,current:$current,expected_before:$expected,desired:$desired,change:($current!=$desired)}'
  done
}
dmb_menu_dns() {
  local iface provider scope address; local -a servers=()
  printf 'Interface: '; IFS= read -r iface || return
  printf 'Provider (cloudflare/google/quad9/custom): '; IFS= read -r provider || return
  printf 'Scope (persistent/runtime; empty=persistent): '; IFS= read -r scope || return
  if [[ $provider == custom ]]; then
    printf 'Enter one numeric DNS address per line; empty line finishes.\n'
    while :; do
      IFS= read -r address || return
      [[ -n $address ]] || break
      ((${#servers[@]}<8)) || { dmb_error 'At most eight addresses'; return 64; }
      servers+=("$address")
    done
  fi
  dmb_plan dns "$iface" "$provider" "${scope:-persistent}" "${servers[@]}"
}
dmb_menu_family() {
  local family=$1 action iface value second config context
  case $family in
    1)
      printf '1 Route/interface report  2 Transactions  3 Status  4 Confirm  5 Rollback\nChoice: '
      IFS= read -r action || return
      case $action in
        1) dmb_report;; 2) dmb_tx_list;;
        3|4|5) printf 'Transaction ID: '; IFS= read -r value || return
          case $action in 3) dmb_tx_status "$value";; 4) printf 'Confirmation (ssh/console): '; IFS= read -r second || return; dmb_tx_confirm "$value" "$second";; 5) dmb_require_root && dmb_recovery_attempt_rollback "$value";; esac;;
        *) return 64;;
      esac;;
    2)
      printf '1 IPv6 report  2 Toggle plan  3 Pool plan  4 NAT66 plan\nChoice: '
      IFS= read -r action || return
      case $action in
        1) dmb_route_report;;
        2) printf 'Interface: '; IFS= read -r iface || return; printf 'Mode (enable/disable): '; IFS= read -r value || return; context=$(jq -cn --arg iface "$iface" '{iface:$iface}') || return; dmb_plan ipv6 "$value" "$context";;
        3|4) printf 'Configuration JSON file: '; IFS= read -r config || return
          if [[ $action == 3 ]]; then dmb_plan pool "$config"; else dmb_plan nat66 "$config"; fi;;
        *) return 64;;
      esac;;
    3)
      printf '1 TCP report  2 Measured profile plan\nChoice: '; IFS= read -r action || return
      case $action in
        1) dmb_tcp_report;;
        2) printf 'Profile (bbr/cubic): '; IFS= read -r value || return; printf 'Explicit measurement request JSON file: '; IFS= read -r config || return; printf 'Scope (runtime/persistent): '; IFS= read -r second || return; dmb_plan tcp "$value" "$config" "${second:-runtime}";;
        *) return 64;;
      esac;;
    4)
      printf '1 DNS plan  2 MTU plan  3 Address selection plan\nChoice: '; IFS= read -r action || return
      case $action in
        1) dmb_menu_dns;;
        2) printf 'Interface: '; IFS= read -r iface || return; printf 'MTU: '; IFS= read -r value || return; dmb_plan mtu "$iface" "$value";;
        3) printf 'Policy (v4/default/restore): '; IFS= read -r value || return; dmb_plan gai "$value";;
        *) return 64;;
      esac;;
    5)
      printf '1 Resources  2 Ports/connections  3 System\nChoice: '; IFS= read -r action || return
      case $action in 1) dmb_maintenance_report resources;; 2) dmb_maintenance_report ports;; 3) dmb_maintenance_report system;; *) return 64;; esac;;
    6)
      printf '1 SSH/firewall/Fail2Ban report  2 SSH port plan  3 nft policy plan\nChoice: '; IFS= read -r action || return
      case $action in
        1) dmb_maintenance_report security;;
        2) printf 'New SSH port: '; IFS= read -r value || return; dmb_plan ssh-port "$value";;
        3) printf 'Configuration JSON file: '; IFS= read -r config || return; dmb_plan nft "$config";;
        *) return 64;;
      esac;;
    7)
      printf '1 Swap report  2 Swap creation plan  3 Guest components report  4 Maintenance report  5 Explicit maintenance action\nChoice: '; IFS= read -r action || return
      case $action in
        1) dmb_swap_report;;
        2) printf 'New swap path: '; IFS= read -r config || return; printf 'Size MiB: '; IFS= read -r value || return; printf 'Priority: '; IFS= read -r second || return; dmb_plan swap "$config" "$value" "$second";;
        3) dmb_maintenance_report guest;; 4) dmb_maintenance_report;;
        5) printf 'Action (update-packages/clean-package-cache/snapshot/set-timezone/enable-time-sync/clean-journal): '; IFS= read -r value || return
          case $value in set-timezone|clean-journal) printf 'Argument: '; IFS= read -r second || return; dmb_maintenance_run "$value" "$second";; *) dmb_maintenance_run "$value";; esac;;
        *) return 64;;
      esac;;
    *) return 64;;
  esac
}
dmb_menu() {
  [[ -t 0 && -t 1 ]] || return 64
  local choice plan_file code
  while :; do
    printf '\nDMITBox local\n1 Network, routing and transactions\n2 IPv6 and address pools\n3 TCP / BBR\n4 DNS / MTU\n5 System resources and ports\n6 SSH, Fail2Ban and firewall\n7 Maintenance and virtualization\nA Apply a reviewed JSON plan\n0 Exit\nChoice: '
    IFS= read -r choice || return
    code=0
    case $choice in
      0|q|Q) return;;
      [1-7]) dmb_menu_family "$choice" || code=$?;;
      a|A) printf 'Reviewed plan JSON file: '; IFS= read -r plan_file || return; dmb_apply_file "$plan_file" || code=$?;;
      *) dmb_error 'Invalid choice'; code=64;;
    esac
    ((code==0)) || printf 'Operation incomplete (exit %s). Inspect the error and transaction evidence.\n' "$code" >&2
  done
}

dmb_main() {
  local command=${1:---menu}; (($#>0)) && shift
  case $command in
    --help|-h) (($#==0)) || return 64; dmb_help;;
    --version) printf '%s\n' "$DMB_VERSION";;
    --check) dmb_check;; --menu) dmb_menu;;
    --net-report) (($#==0)) || return 64; dmb_report;;
    --net-route-test) (($#<=1)) || return 64; dmb_route_report "${1:-'{}'}";;
    --net-firewall-hash) (($#==0)) || return 64; dmb_need nft jq || return; dmb_nft_ruleset | dmb_nft_semantic | sha256sum;;
    --net-list) (($#==0)) || return 64; dmb_tx_list;;
    --net-status) (($#==1)) || return 64; dmb_tx_status "$1";;
    --net-confirm) (($#>=1 && $#<=2)) || return 64; dmb_tx_confirm "$1" "${2:-ssh}";;
    --net-rollback) (($#==1)) || return 64; dmb_require_root && dmb_recovery_attempt_rollback "$1";;
    --enroll) dmb_enroll "$@";;
    --plan) dmb_plan "$@";;
    --diff) (($#==1)) || return 64; dmb_diff "$1";;
    --apply-plan) (($#==1)) || return 64; dmb_apply_file "$1";;
    --net-dns-set)
      (($#>=2)) || return 64; local provider=$1 iface=$2 scope=${3:-persistent}; (($#>=3)) && shift 3 || shift 2
      dmb_execute_plan dns "$iface" "$provider" "$scope" "$@";;
    --net-dns-restore)
      (($#==1)) || return 64; local tmp; tmp=$(dmb_private_tmp) || return
      if dmb_dns_restore_plan "$1" > "$tmp/plan.json"; then dmb_apply_file "$tmp/plan.json"; local rc=$?; rm -rf -- "$tmp"; return "$rc"; else local rc=$?; rm -rf -- "$tmp"; return "$rc"; fi;;
    --net-mtu-set) (($#>=2 && $#<=3)) || return 64; dmb_execute_plan mtu "$1" "$2" runtime "${3:-'{}'}";;
    --net-ipv6) dmb_execute_plan ipv6 "$@";;
    --net-iface)
      (($#>=2 && $#<=3)) || return 64; dmb_iface_plan "$1" "$2" runtime "${3:-'{}'}";;
    --net-gai) (($#==1)) || return 64; dmb_gai "$1";;
    --net-ssh-port) dmb_execute_plan ssh-port "$@";;
    --dns-probe) (($#==1)) || return 64; dmb_dns_probe "$1";;
    --pmtu-probe) (($#>=2 && $#<=3)) || return 64; dmb_pmtu_probe "$@";;
    --tcp-report) dmb_tcp_report;; --swap-report) dmb_swap_report;;
    --maintenance-report) (($#<=1)) || return 64; dmb_maintenance_report "${1:-system}";;
    --maintenance) (($#>=1)) || return 64; dmb_maintenance_run "$@";;
    --recover-all) (($#==0)) || return 64; dmb_require_root && dmb_recovery_boot;;
    --internal-recover-watch) (($#==2)) || return 64; dmb_require_root && dmb_recovery_watch "$@";;
    --internal-recover-once) (($#==1)) || return 64; dmb_require_root && dmb_recovery_attempt_rollback "$1";;
    --internal-adapter-guarded) (($#==4)) || return 64; dmb_require_root && dmb_tx_adapter_guarded "$@";;
    *) dmb_error "Unknown command: $command"; return 64;;
  esac
}
# END MODULE main.sh

dmb_main "$@"
